window.QURAN_DATA = [{"s":"سُورَةُ ٱلْفَاتِحَةِ","n":1,"ar":"﻿بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ","fa":"به نام خدا که رحمتش بی‌اندازه است و مهربانی‌اش همیشگی."},{"s":"سُورَةُ البَقَرَةِ","n":4,"ar":"وَٱلَّذِينَ يُؤْمِنُونَ بِمَآ أُنزِلَ إِلَيْكَ وَمَآ أُنزِلَ مِن قَبْلِكَ وَبِٱلْءَاخِرَةِ هُمْ يُوقِنُونَ","fa":"و آنان که به آنچه به سوی تو و به آنچه پیش از تو نازل شده، مؤمن هستند و به آخرت یقین دارند."},{"s":"سُورَةُ البَقَرَةِ","n":14,"ar":"وَإِذَا لَقُوا۟ ٱلَّذِينَ ءَامَنُوا۟ قَالُوٓا۟ ءَامَنَّا وَإِذَا خَلَوْا۟ إِلَىٰ شَيَٰطِينِهِمْ قَالُوٓا۟ إِنَّا مَعَكُمْ إِنَّمَا نَحْنُ مُسْتَهْزِءُونَ","fa":"و هنگامی که با اهل ایمان دیدار کنند، گویند: ما ایمان آوردیم و چون با شیطان هایشان [که سرانِ شرک و کفرند] خلوت گزینند، گویند: بدون شک ما با شماییم، جز این نیست که ما [با تظاهر به ایمان] آنان را مسخره می کنیم."},{"s":"سُورَةُ البَقَرَةِ","n":24,"ar":"فَإِن لَّمْ تَفْعَلُوا۟ وَلَن تَفْعَلُوا۟ فَٱتَّقُوا۟ ٱلنَّارَ ٱلَّتِى وَقُودُهَا ٱلنَّاسُ وَٱلْحِجَارَةُ ۖ أُعِدَّتْ لِلْكَٰفِرِينَ","fa":"و اگر این کار را انجام ندادید ـ که هرگز نمی توانید انجام دهید ـ بنابراین از آتشی که هیزمش مردم و سنگ هایند، بپرهیزید؛ آتشی که برای کافران آماده شده است."},{"s":"سُورَةُ البَقَرَةِ","n":34,"ar":"وَإِذْ قُلْنَا لِلْمَلَٰٓئِكَةِ ٱسْجُدُوا۟ لِءَادَمَ فَسَجَدُوٓا۟ إِلَّآ إِبْلِيسَ أَبَىٰ وَٱسْتَكْبَرَ وَكَانَ مِنَ ٱلْكَٰفِرِينَ","fa":"و [یاد کن] هنگامی که به فرشتگان گفتیم: به آدم سجده کنید، [پس] سجده کردند مگر ابلیس که سر پیچید و تکبّر ورزید و از کافران شد."},{"s":"سُورَةُ البَقَرَةِ","n":44,"ar":"۞ أَتَأْمُرُونَ ٱلنَّاسَ بِٱلْبِرِّ وَتَنسَوْنَ أَنفُسَكُمْ وَأَنتُمْ تَتْلُونَ ٱلْكِتَٰبَ ۚ أَفَلَا تَعْقِلُونَ","fa":"آیا مردم را به نیکی فرمان می دهید و خود را [در ارتباط با نیکی] فراموش می کنید؟ در حالی که کتاب [تورات را که با شدت به نیکی دعوتتان کرده] می خوانید. آیا [به وضع زیان بار و خطرناک خود] نمی اندیشید؟"},{"s":"سُورَةُ البَقَرَةِ","n":54,"ar":"وَإِذْ قَالَ مُوسَىٰ لِقَوْمِهِۦ يَٰقَوْمِ إِنَّكُمْ ظَلَمْتُمْ أَنفُسَكُم بِٱتِّخَاذِكُمُ ٱلْعِجْلَ فَتُوبُوٓا۟ إِلَىٰ بَارِئِكُمْ فَٱقْتُلُوٓا۟ أَنفُسَكُمْ ذَٰلِكُمْ خَيْرٌۭ لَّكُمْ عِندَ بَارِئِكُمْ فَتَابَ عَلَيْكُمْ ۚ إِنَّهُۥ هُوَ ٱلتَّوَّابُ ٱلرَّحِيمُ","fa":"و [یاد کنید] زمانی که موسی به قومش گفت: ای قوم من! قطعاً شما به سبب معبود گرفتن گوساله به خودتان ستم ورزیدید، پس به سوی آفریننده خود بازگردید، و [افرادی از] خودتان را [که گوساله را به پرستش گرفتند] بکشید که این [عمل] برای شما در پیشگاه آفریدگارتان بهتر است. پس خدا [به دنبال اجرا کردن دستورش] توبه شما را پذیرفت؛ زیرا او بسیار توبه پذیر و مهربان است."},{"s":"سُورَةُ البَقَرَةِ","n":64,"ar":"ثُمَّ تَوَلَّيْتُم مِّنۢ بَعْدِ ذَٰلِكَ ۖ فَلَوْلَا فَضْلُ ٱللَّهِ عَلَيْكُمْ وَرَحْمَتُهُۥ لَكُنتُم مِّنَ ٱلْخَٰسِرِينَ","fa":"آن گاه بعد از [پیمان گرفتن، از وفاکردن به آن] سرپیچی کردید، و اگر فضل و رحمت خدا بر شما نبود، قطعاً از زیانکاران بودید."},{"s":"سُورَةُ البَقَرَةِ","n":74,"ar":"ثُمَّ قَسَتْ قُلُوبُكُم مِّنۢ بَعْدِ ذَٰلِكَ فَهِىَ كَٱلْحِجَارَةِ أَوْ أَشَدُّ قَسْوَةًۭ ۚ وَإِنَّ مِنَ ٱلْحِجَارَةِ لَمَا يَتَفَجَّرُ مِنْهُ ٱلْأَنْهَٰرُ ۚ وَإِنَّ مِنْهَا لَمَا يَشَّقَّقُ فَيَخْرُجُ مِنْهُ ٱلْمَآءُ ۚ وَإِنَّ مِنْهَا لَمَا يَهْبِطُ مِنْ خَشْيَةِ ٱللَّهِ ۗ وَمَا ٱللَّهُ بِغَٰفِلٍ عَمَّا تَعْمَلُونَ","fa":"سپس دل های شما بعد از آن [معجزه شگفت انگیز] سخت شد، مانند سنگ یا سخت تر؛ زیرا پاره ای از سنگ هاست که از آنها نهرها می جوشد، و پاره ای از آنها می شکافد و آب از آن بیرون می آید، و پاره ای از آنها از ترس خدا [از بلندی] سقوط می کند؛ و خدا از آنچه انجام می دهید بی خبر نیست."},{"s":"سُورَةُ البَقَرَةِ","n":84,"ar":"وَإِذْ أَخَذْنَا مِيثَٰقَكُمْ لَا تَسْفِكُونَ دِمَآءَكُمْ وَلَا تُخْرِجُونَ أَنفُسَكُم مِّن دِيَٰرِكُمْ ثُمَّ أَقْرَرْتُمْ وَأَنتُمْ تَشْهَدُونَ","fa":"و [یاد کنید] هنگامی که از شما پیمان گرفتیم که خون همدیگر را نریزید، و یکدیگر را از خانه های خود آواره نکنید، سپس [به پیمانتان] اقرار کردید و بر آن هم گواهی می دهید."},{"s":"سُورَةُ البَقَرَةِ","n":94,"ar":"قُلْ إِن كَانَتْ لَكُمُ ٱلدَّارُ ٱلْءَاخِرَةُ عِندَ ٱللَّهِ خَالِصَةًۭ مِّن دُونِ ٱلنَّاسِ فَتَمَنَّوُا۟ ٱلْمَوْتَ إِن كُنتُمْ صَٰدِقِينَ","fa":"بگو: اگر [آن گونه که می پندارید] سرای آخرت [با همه نعمت هایش] نزد خدا ویژه شماست نه مردم دیگر، پس چنانچه راستگویید مرگ را آرزو کنید."},{"s":"سُورَةُ البَقَرَةِ","n":104,"ar":"يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَقُولُوا۟ رَٰعِنَا وَقُولُوا۟ ٱنظُرْنَا وَٱسْمَعُوا۟ ۗ وَلِلْكَٰفِرِينَ عَذَابٌ أَلِيمٌۭ","fa":"ای کسانی که ایمان آورده اید! [هنگام سخن گفتن با پیامبر] مگویید: راعنا [یعنی: در ارائه احکام، امیال و هوس های ما را رعایت کن] و بگویید: انظرنا [یعنی: مصلحت دنیا و آخرت ما را ملاحظه کن] و [فرمان های خدا و پیامبرش را] بشنوید. و برای کافران عذابی دردناک است."},{"s":"سُورَةُ البَقَرَةِ","n":114,"ar":"وَمَنْ أَظْلَمُ مِمَّن مَّنَعَ مَسَٰجِدَ ٱللَّهِ أَن يُذْكَرَ فِيهَا ٱسْمُهُۥ وَسَعَىٰ فِى خَرَابِهَآ ۚ أُو۟لَٰٓئِكَ مَا كَانَ لَهُمْ أَن يَدْخُلُوهَآ إِلَّا خَآئِفِينَ ۚ لَهُمْ فِى ٱلدُّنْيَا خِزْىٌۭ وَلَهُمْ فِى ٱلْءَاخِرَةِ عَذَابٌ عَظِيمٌۭ","fa":"و چه کسانی ستمکارتر از کسانی می باشند که از بردن نام خدا در مساجد خدا جلوگیری کردند، و در خرابی آنها کوشیدند؟ آنان را شایسته نیست که در آن [مراکز عبادت] درآیند، جز در حال ترس [از عدالت و انتقام خدا]. برای آنان در دنیا خواری و زبونی است و در آخرت عذابی بزرگ است."},{"s":"سُورَةُ البَقَرَةِ","n":124,"ar":"۞ وَإِذِ ٱبْتَلَىٰٓ إِبْرَٰهِۦمَ رَبُّهُۥ بِكَلِمَٰتٍۢ فَأَتَمَّهُنَّ ۖ قَالَ إِنِّى جَاعِلُكَ لِلنَّاسِ إِمَامًۭا ۖ قَالَ وَمِن ذُرِّيَّتِى ۖ قَالَ لَا يَنَالُ عَهْدِى ٱلظَّٰلِمِينَ","fa":"و [یاد کنید] هنگامی که ابراهیم را پروردگارش به اموری [دشوار و سخت] آزمایش کرد، پس او همه را به طور کامل به انجام رسانید، پروردگارش [به خاطر شایستگی ولیاقت او] فرمود: من تو را برای همه مردم پیشوا و امام قرار دادم. ابراهیم گفت: و از دودمانم [نیز پیشوایانی برگزین]. [پروردگار] فرمود: پیمان من [که امامت و پیشوایی است] به ستمکاران نمی رسد."},{"s":"سُورَةُ البَقَرَةِ","n":134,"ar":"تِلْكَ أُمَّةٌۭ قَدْ خَلَتْ ۖ لَهَا مَا كَسَبَتْ وَلَكُم مَّا كَسَبْتُمْ ۖ وَلَا تُسْـَٔلُونَ عَمَّا كَانُوا۟ يَعْمَلُونَ","fa":"آنان گروهی بودند که درگذشتند، آنچه [از طاعت و معصیت] به دست آوردند مربوط به خود آنان است، و آنچه شما به دست آوردید مربوط به خود شماست؛ و شما در برابر آنچه آنان انجام می دادند، مسؤول نیستید."},{"s":"سُورَةُ البَقَرَةِ","n":144,"ar":"قَدْ نَرَىٰ تَقَلُّبَ وَجْهِكَ فِى ٱلسَّمَآءِ ۖ فَلَنُوَلِّيَنَّكَ قِبْلَةًۭ تَرْضَىٰهَا ۚ فَوَلِّ وَجْهَكَ شَطْرَ ٱلْمَسْجِدِ ٱلْحَرَامِ ۚ وَحَيْثُ مَا كُنتُمْ فَوَلُّوا۟ وُجُوهَكُمْ شَطْرَهُۥ ۗ وَإِنَّ ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَٰبَ لَيَعْلَمُونَ أَنَّهُ ٱلْحَقُّ مِن رَّبِّهِمْ ۗ وَمَا ٱللَّهُ بِغَٰفِلٍ عَمَّا يَعْمَلُونَ","fa":"ما گردانیدن رویت را در [جهت] آسمان [چون کسی که به انتظار مطلبی باشد] می بینیم؛ پس یقیناً تو را به سوی قبله ای که آن را بپسندی برمی گردانیم؛ پس رویت را به سوی مسجد الحرام گردان؛ و [شما ای مسلمانان!] هر جا که باشید، روی خود را به سوی آن برگردانید. و مسلماً اهل کتاب می دانند که این تغییر قبله [از بیت المقدس به کعبه] از سوی پروردگارشان [کاری] درست و حق است؛ [زیرا در تورات و انجیلشان خوانده اند که پیامبر اسلام به دو قبله نماز خواهد خواند] و خدا از آنچه [بر ضد پیامبر و مؤمنان] انجام می دهند، بی خبر نیست."},{"s":"سُورَةُ البَقَرَةِ","n":154,"ar":"وَلَا تَقُولُوا۟ لِمَن يُقْتَلُ فِى سَبِيلِ ٱللَّهِ أَمْوَٰتٌۢ ۚ بَلْ أَحْيَآءٌۭ وَلَٰكِن لَّا تَشْعُرُونَ","fa":"و به آنان که در راه خدا کشته می شوند مرده نگویید، بلکه [در عالم برزخ] دارای حیات اند، ولی شما [کیفیت آن حیات را] درک نمی کنید."},{"s":"سُورَةُ البَقَرَةِ","n":164,"ar":"إِنَّ فِى خَلْقِ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَٱخْتِلَٰفِ ٱلَّيْلِ وَٱلنَّهَارِ وَٱلْفُلْكِ ٱلَّتِى تَجْرِى فِى ٱلْبَحْرِ بِمَا يَنفَعُ ٱلنَّاسَ وَمَآ أَنزَلَ ٱللَّهُ مِنَ ٱلسَّمَآءِ مِن مَّآءٍۢ فَأَحْيَا بِهِ ٱلْأَرْضَ بَعْدَ مَوْتِهَا وَبَثَّ فِيهَا مِن كُلِّ دَآبَّةٍۢ وَتَصْرِيفِ ٱلرِّيَٰحِ وَٱلسَّحَابِ ٱلْمُسَخَّرِ بَيْنَ ٱلسَّمَآءِ وَٱلْأَرْضِ لَءَايَٰتٍۢ لِّقَوْمٍۢ يَعْقِلُونَ","fa":"بی تردید در آفرینش آسمان ها و زمین و رفت و آمد شب و روز و کشتی هایی که در دریاها [با جابجا کردن مسافر و کالا] به سود مردم روانند و بارانی که خدا از آسمان نازل کرده و به وسیله آن زمین را پس از مردگی اش زنده ساخته و در آن از هر نوع جنبنده ای پراکنده کرده و گرداندن بادها و ابرِ مسخّر میان آسمان و زمین، نشانه هایی است [از توحید، ربوبیّت و قدرت خدا] برای گروهی که می اندیشند."},{"s":"سُورَةُ البَقَرَةِ","n":174,"ar":"إِنَّ ٱلَّذِينَ يَكْتُمُونَ مَآ أَنزَلَ ٱللَّهُ مِنَ ٱلْكِتَٰبِ وَيَشْتَرُونَ بِهِۦ ثَمَنًۭا قَلِيلًا ۙ أُو۟لَٰٓئِكَ مَا يَأْكُلُونَ فِى بُطُونِهِمْ إِلَّا ٱلنَّارَ وَلَا يُكَلِّمُهُمُ ٱللَّهُ يَوْمَ ٱلْقِيَٰمَةِ وَلَا يُزَكِّيهِمْ وَلَهُمْ عَذَابٌ أَلِيمٌ","fa":"قطعاً کسانی که آنچه را خدا از کتاب [تورات و انجیل به عنوان حلال و حرام] نازل کرده [به سود خود، از بی سوادان یهود و نصاری] پنهان می کنند، و در برابر این پنهان کاری بهای اندکی به دست می آورند، جز آتش به شکم های خود نمی ریزند. و خدا روز قیامت با آنان سخن نمی گوید، و [از گناهان و زشتی ها] پاکشان نمی کند، و برای آنان عذابی دردناک است."},{"s":"سُورَةُ البَقَرَةِ","n":184,"ar":"أَيَّامًۭا مَّعْدُودَٰتٍۢ ۚ فَمَن كَانَ مِنكُم مَّرِيضًا أَوْ عَلَىٰ سَفَرٍۢ فَعِدَّةٌۭ مِّنْ أَيَّامٍ أُخَرَ ۚ وَعَلَى ٱلَّذِينَ يُطِيقُونَهُۥ فِدْيَةٌۭ طَعَامُ مِسْكِينٍۢ ۖ فَمَن تَطَوَّعَ خَيْرًۭا فَهُوَ خَيْرٌۭ لَّهُۥ ۚ وَأَن تَصُومُوا۟ خَيْرٌۭ لَّكُمْ ۖ إِن كُنتُمْ تَعْلَمُونَ","fa":"[در] روزهایی چند [روزه بگیرید]؛ پس هر که از شما بیمار یا در سفر باشد [به تعداد روزه های فوت شده] از روزهای دیگر [را روزه بگیرد]؛ و بر آنان که روزه گرفتن طاقت فرساست، طعام دادن به یک نیازمند [به جای هر روز] کفاره آن است. و هر که به خواست خودش افزون بر کفاره واجب، بر طعام نیازمند بیفزاید، برایش بهتر است و روزه گرفتن [هر چند دشوار و سخت باشد] اگر [فضیلت و ثوابش را] بدانید برای شما بهتر است."},{"s":"سُورَةُ البَقَرَةِ","n":194,"ar":"ٱلشَّهْرُ ٱلْحَرَامُ بِٱلشَّهْرِ ٱلْحَرَامِ وَٱلْحُرُمَٰتُ قِصَاصٌۭ ۚ فَمَنِ ٱعْتَدَىٰ عَلَيْكُمْ فَٱعْتَدُوا۟ عَلَيْهِ بِمِثْلِ مَا ٱعْتَدَىٰ عَلَيْكُمْ ۚ وَٱتَّقُوا۟ ٱللَّهَ وَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ مَعَ ٱلْمُتَّقِينَ","fa":"ماه حرام در برابر ماه حرام است [اگر دشمن حرمت آن را رعایت نکرد و با شما در آن جنگید، شما هم برای حفظ کیان خود در همان ماه با او بجنگید.] و همه حرمت ها دارای قصاص اند. پس هر که بر شما تعدّی کرد، شما هم به مثل آن بر او تعدّی کنید، و از خدا پروا نمایید، و بدانید که خدا با پروا پیشگان است."},{"s":"سُورَةُ البَقَرَةِ","n":204,"ar":"وَمِنَ ٱلنَّاسِ مَن يُعْجِبُكَ قَوْلُهُۥ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا وَيُشْهِدُ ٱللَّهَ عَلَىٰ مَا فِى قَلْبِهِۦ وَهُوَ أَلَدُّ ٱلْخِصَامِ","fa":"و از مردم کسی است که گفتارش در زندگی دنیا تو را خوش آید، و [برای اینکه چنین وانمود کند که زبانش با دلش یکی است] خدا را بر آنچه در دل دارد شاهد می گیرد، در حالی که سرسخت ترین دشمنان است."},{"s":"سُورَةُ البَقَرَةِ","n":214,"ar":"أَمْ حَسِبْتُمْ أَن تَدْخُلُوا۟ ٱلْجَنَّةَ وَلَمَّا يَأْتِكُم مَّثَلُ ٱلَّذِينَ خَلَوْا۟ مِن قَبْلِكُم ۖ مَّسَّتْهُمُ ٱلْبَأْسَآءُ وَٱلضَّرَّآءُ وَزُلْزِلُوا۟ حَتَّىٰ يَقُولَ ٱلرَّسُولُ وَٱلَّذِينَ ءَامَنُوا۟ مَعَهُۥ مَتَىٰ نَصْرُ ٱللَّهِ ۗ أَلَآ إِنَّ نَصْرَ ٱللَّهِ قَرِيبٌۭ","fa":"آیا پنداشته اید در حالی که هنوز حادثه هایی مانند حوادث گذشتگان شما را نیامده، وارد بهشت می شوید؟! به آنان سختی ها و آسیب هایی رسید وچنان متزلزل و مضطرب شدند تا جایی که پیامبر و کسانی که با او ایمان آورده بودند [در مقام دعا و درخواست یاری] می گفتند: یاری خدا چه زمانی است؟ [به آنان گفتیم:] آگاه باشید! یقیناً یاری خدا نزدیک است."},{"s":"سُورَةُ البَقَرَةِ","n":224,"ar":"وَلَا تَجْعَلُوا۟ ٱللَّهَ عُرْضَةًۭ لِّأَيْمَٰنِكُمْ أَن تَبَرُّوا۟ وَتَتَّقُوا۟ وَتُصْلِحُوا۟ بَيْنَ ٱلنَّاسِ ۗ وَٱللَّهُ سَمِيعٌ عَلِيمٌۭ","fa":"و خدا را در معرض سوگندهایی که می خورید قرار ندهید، [به اینکه سوگند بخورید] که نیکی نکنید، و تقوا پیشه نسازید، و میان مردم آشتی ندهید [خدا رضایت ندارد که نامش وسیله خودداری از کارهایی شود که خودش به انجام آنها فرمان داده است] و خدا [نسبت به همه گفته های شما] شنوا، [و نسبت به تمام کارهای شما] داناست."},{"s":"سُورَةُ البَقَرَةِ","n":234,"ar":"وَٱلَّذِينَ يُتَوَفَّوْنَ مِنكُمْ وَيَذَرُونَ أَزْوَٰجًۭا يَتَرَبَّصْنَ بِأَنفُسِهِنَّ أَرْبَعَةَ أَشْهُرٍۢ وَعَشْرًۭا ۖ فَإِذَا بَلَغْنَ أَجَلَهُنَّ فَلَا جُنَاحَ عَلَيْكُمْ فِيمَا فَعَلْنَ فِىٓ أَنفُسِهِنَّ بِٱلْمَعْرُوفِ ۗ وَٱللَّهُ بِمَا تَعْمَلُونَ خَبِيرٌۭ","fa":"و کسانی از شما که می میرند و همسرانی باقی می گذارند، باید همسرانْ چهار ماه و ده روز انتظار برند [و از شوهر کردن خودداری ورزند]؛ پس چون به پایان مدتشان رسیدند، در آنچه درباره خودشان به طور شایسته و متعارف [نسبت به ازدواج یا ترک آن] انجام دهند بر شما [حاکمان، وارثان متوفّی و اقوام زنان] گناهی نیست؛ و خدا از آنچه انجام می دهید، آگاه است."},{"s":"سُورَةُ البَقَرَةِ","n":244,"ar":"وَقَٰتِلُوا۟ فِى سَبِيلِ ٱللَّهِ وَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ سَمِيعٌ عَلِيمٌۭ","fa":"و در راه خدا پیکار کنید و بدانید که یقیناً خدا شنوا و داناست."},{"s":"سُورَةُ البَقَرَةِ","n":254,"ar":"يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ أَنفِقُوا۟ مِمَّا رَزَقْنَٰكُم مِّن قَبْلِ أَن يَأْتِىَ يَوْمٌۭ لَّا بَيْعٌۭ فِيهِ وَلَا خُلَّةٌۭ وَلَا شَفَٰعَةٌۭ ۗ وَٱلْكَٰفِرُونَ هُمُ ٱلظَّٰلِمُونَ","fa":"ای اهل ایمان! از آنچه به شما روزی کرده ایم انفاق کنید، پیش از آنکه روزی بیاید که در آن نه داد و ستدی است و نه دوستی و نه شفاعتی؛ و تنها کافران ستمکارند."},{"s":"سُورَةُ البَقَرَةِ","n":264,"ar":"يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تُبْطِلُوا۟ صَدَقَٰتِكُم بِٱلْمَنِّ وَٱلْأَذَىٰ كَٱلَّذِى يُنفِقُ مَالَهُۥ رِئَآءَ ٱلنَّاسِ وَلَا يُؤْمِنُ بِٱللَّهِ وَٱلْيَوْمِ ٱلْءَاخِرِ ۖ فَمَثَلُهُۥ كَمَثَلِ صَفْوَانٍ عَلَيْهِ تُرَابٌۭ فَأَصَابَهُۥ وَابِلٌۭ فَتَرَكَهُۥ صَلْدًۭا ۖ لَّا يَقْدِرُونَ عَلَىٰ شَىْءٍۢ مِّمَّا كَسَبُوا۟ ۗ وَٱللَّهُ لَا يَهْدِى ٱلْقَوْمَ ٱلْكَٰفِرِينَ","fa":"ای اهل ایمان! صدقه هایتان را با منت و آزار باطل نکنید، مانند کسی که مالش را به ریا به مردم انفاق می کند و به خدا و روز قیامت ایمان ندارد، که وصفش مانند سنگ سخت و خارایی است که بر آن [پوششی نازک از] خاک قرار دارد و رگباری تند و درشت به آن برسد و آن سنگ را صاف [و بدون خاک] واگذارد [صدقه ریایی مانند آن خاک است و این ریاکاران] به چیزی از آنچه کسب کرده اند، دست نمی یابند و خدا مردم کافر را هدایت نمی کند."},{"s":"سُورَةُ البَقَرَةِ","n":274,"ar":"ٱلَّذِينَ يُنفِقُونَ أَمْوَٰلَهُم بِٱلَّيْلِ وَٱلنَّهَارِ سِرًّۭا وَعَلَانِيَةًۭ فَلَهُمْ أَجْرُهُمْ عِندَ رَبِّهِمْ وَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ","fa":"کسانی که [چون علی بن أبی طالب (علیه السلام)] اموالشان را در شب و روز و پنهان و آشکار انفاق می کنند، برای آنان نزد پروردگارشان پاداشی شایسته و مناسب است؛ و نه بیمی بر آنان است و نه اندوهگین می شوند."},{"s":"سُورَةُ البَقَرَةِ","n":284,"ar":"لِّلَّهِ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ ۗ وَإِن تُبْدُوا۟ مَا فِىٓ أَنفُسِكُمْ أَوْ تُخْفُوهُ يُحَاسِبْكُم بِهِ ٱللَّهُ ۖ فَيَغْفِرُ لِمَن يَشَآءُ وَيُعَذِّبُ مَن يَشَآءُ ۗ وَٱللَّهُ عَلَىٰ كُلِّ شَىْءٍۢ قَدِيرٌ","fa":"آنچه در آسمان ها و آنچه در زمین است، فقط در سیطره مالکیّت و فرمانروایی خداست، و اگر آنچه [از نیّت های فاسد و افکار باطل] در دل دارید آشکار کنید یا پنهان سازید، خدا شما را به آن محاسبه می کند؛ پس هر که را بخواهد می آمرزد، و هر که را بخواهد عذاب می کند؛ و خدا بر هر کاری تواناست."},{"s":"سُورَةُ آلِ عِمۡرَانَ","n":8,"ar":"رَبَّنَا لَا تُزِغْ قُلُوبَنَا بَعْدَ إِذْ هَدَيْتَنَا وَهَبْ لَنَا مِن لَّدُنكَ رَحْمَةً ۚ إِنَّكَ أَنتَ ٱلْوَهَّابُ","fa":"[و می گویند:] پروردگارا! دل هایمان را پس از آنکه هدایتمان فرمودی منحرف مکن، و از سوی خود رحمتی برما ببخش؛ زیرا تو بسیار بخشنده ای."},{"s":"سُورَةُ آلِ عِمۡرَانَ","n":18,"ar":"شَهِدَ ٱللَّهُ أَنَّهُۥ لَآ إِلَٰهَ إِلَّا هُوَ وَٱلْمَلَٰٓئِكَةُ وَأُو۟لُوا۟ ٱلْعِلْمِ قَآئِمًۢا بِٱلْقِسْطِ ۚ لَآ إِلَٰهَ إِلَّا هُوَ ٱلْعَزِيزُ ٱلْحَكِيمُ","fa":"خدا در حالی که برپا دارنده عدل است [با منطق وحی، با نظام مُتقن آفرینش و با زبان همه موجودات] گواهی می دهد که هیچ معبودی جز او نیست؛ و فرشتگان و صاحبان دانش نیز گواهی می دهند که هیچ معبودی جز او نیست؛ معبودی که توانای شکست ناپذیر و حکیم است."},{"s":"سُورَةُ آلِ عِمۡرَانَ","n":28,"ar":"لَّا يَتَّخِذِ ٱلْمُؤْمِنُونَ ٱلْكَٰفِرِينَ أَوْلِيَآءَ مِن دُونِ ٱلْمُؤْمِنِينَ ۖ وَمَن يَفْعَلْ ذَٰلِكَ فَلَيْسَ مِنَ ٱللَّهِ فِى شَىْءٍ إِلَّآ أَن تَتَّقُوا۟ مِنْهُمْ تُقَىٰةًۭ ۗ وَيُحَذِّرُكُمُ ٱللَّهُ نَفْسَهُۥ ۗ وَإِلَى ٱللَّهِ ٱلْمَصِيرُ","fa":"مؤمنان نباید کافران را به جای اهل ایمان، سرپرست و دوست بگیرند؛ و هر کس چنین کند در هیچ پیوند و رابطه ای با خدا نیست، مگر آنکه بخواهید به سبب دفع خطری که متوجه شماست از آنان تقیّه کنید؛ خدا شما را از [عذاب] خود بر حذر می دارد، و بازگشت [همه] به سوی خداست."},{"s":"سُورَةُ آلِ عِمۡرَانَ","n":38,"ar":"هُنَالِكَ دَعَا زَكَرِيَّا رَبَّهُۥ ۖ قَالَ رَبِّ هَبْ لِى مِن لَّدُنكَ ذُرِّيَّةًۭ طَيِّبَةً ۖ إِنَّكَ سَمِيعُ ٱلدُّعَآءِ","fa":"در آنجا بود که زکریا [با دیدن کرامت و عظمت مریم] پروردگار خود را خوانده، گفت: پروردگارا! مرا از سوی خود فرزندی پاک و پاکیزه عطا کن، یقیناً تو شنوای دعایی."},{"s":"سُورَةُ آلِ عِمۡرَانَ","n":48,"ar":"وَيُعَلِّمُهُ ٱلْكِتَٰبَ وَٱلْحِكْمَةَ وَٱلتَّوْرَىٰةَ وَٱلْإِنجِيلَ","fa":"و به او کتاب و حکمت و تورات و انجیل می آموزد."},{"s":"سُورَةُ آلِ عِمۡرَانَ","n":58,"ar":"ذَٰلِكَ نَتْلُوهُ عَلَيْكَ مِنَ ٱلْءَايَٰتِ وَٱلذِّكْرِ ٱلْحَكِيمِ","fa":"این داستان هایی که بر تو می خوانیم از آیات [الهی] و پندهای حکیمانه است."},{"s":"سُورَةُ آلِ عِمۡرَانَ","n":68,"ar":"إِنَّ أَوْلَى ٱلنَّاسِ بِإِبْرَٰهِيمَ لَلَّذِينَ ٱتَّبَعُوهُ وَهَٰذَا ٱلنَّبِىُّ وَٱلَّذِينَ ءَامَنُوا۟ ۗ وَٱللَّهُ وَلِىُّ ٱلْمُؤْمِنِينَ","fa":"مسلماً نزدیک ترین مردم به ابراهیم [از جهت پیوند وانتساب معنوی] کسانی اند که [از روی حقیقت] از او پیروی کردند، و این پیامبر و کسانی که [به او] ایمان آورده اند [از همه به او نزدیک ترند] و خدا یاور و سرپرست مؤمنان است."},{"s":"سُورَةُ آلِ عِمۡرَانَ","n":78,"ar":"وَإِنَّ مِنْهُمْ لَفَرِيقًۭا يَلْوُۥنَ أَلْسِنَتَهُم بِٱلْكِتَٰبِ لِتَحْسَبُوهُ مِنَ ٱلْكِتَٰبِ وَمَا هُوَ مِنَ ٱلْكِتَٰبِ وَيَقُولُونَ هُوَ مِنْ عِندِ ٱللَّهِ وَمَا هُوَ مِنْ عِندِ ٱللَّهِ وَيَقُولُونَ عَلَى ٱللَّهِ ٱلْكَذِبَ وَهُمْ يَعْلَمُونَ","fa":"و از یهود گروهی هستند که هنگام [خواندن] دست نوشته ها [ی دروغ و بر بافته های خود] زبان [و صدایشان] را چنان پیچ و خم می دهند تا شما گمان کنید که [آنچه می خوانند] از کتاب آسمانی است، در حالی که از کتاب [آسمانی] نیست؛ و [با بی شرمی] می گویند: آنچه می خوانیم از سوی خداست. در حالی که از سوی خدا نیست؛ و با آنکه می دانند [از سوی خدا نیست] به خدا دروغ می بندند."},{"s":"سُورَةُ آلِ عِمۡرَانَ","n":88,"ar":"خَٰلِدِينَ فِيهَا لَا يُخَفَّفُ عَنْهُمُ ٱلْعَذَابُ وَلَا هُمْ يُنظَرُونَ","fa":"در آن لعنت جاودانه اند؛ نه عذاب از آنان سبک شود، و نه مهلتشان دهند."},{"s":"سُورَةُ آلِ عِمۡرَانَ","n":98,"ar":"قُلْ يَٰٓأَهْلَ ٱلْكِتَٰبِ لِمَ تَكْفُرُونَ بِـَٔايَٰتِ ٱللَّهِ وَٱللَّهُ شَهِيدٌ عَلَىٰ مَا تَعْمَلُونَ","fa":"بگو: ای اهل کتاب! چرا به آیات خدا کفر می ورزید؟ در حالی که خدا بر آنچه انجام می دهید، گواه است."},{"s":"سُورَةُ آلِ عِمۡرَانَ","n":108,"ar":"تِلْكَ ءَايَٰتُ ٱللَّهِ نَتْلُوهَا عَلَيْكَ بِٱلْحَقِّ ۗ وَمَا ٱللَّهُ يُرِيدُ ظُلْمًۭا لِّلْعَٰلَمِينَ","fa":"اینها [که سرگذشت اهل کتاب، مژده ها، بیم ها و امور مربوط به آخرت است] آیات خداست که آن را به درستی و راستی بر تو می خوانیم؛ و خدا هیچ ستم و بیدادی بر جهانیان نمی خواهد."},{"s":"سُورَةُ آلِ عِمۡرَانَ","n":118,"ar":"يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَتَّخِذُوا۟ بِطَانَةًۭ مِّن دُونِكُمْ لَا يَأْلُونَكُمْ خَبَالًۭا وَدُّوا۟ مَا عَنِتُّمْ قَدْ بَدَتِ ٱلْبَغْضَآءُ مِنْ أَفْوَٰهِهِمْ وَمَا تُخْفِى صُدُورُهُمْ أَكْبَرُ ۚ قَدْ بَيَّنَّا لَكُمُ ٱلْءَايَٰتِ ۖ إِن كُنتُمْ تَعْقِلُونَ","fa":"ای اهل ایمان! از غیر خودتان برای خود محرم راز نگیرید؛ آنان از هیچ توطئه و فسادی درباره شما کوتاهی نمی کنند؛ شدت گرفتاری و رنج و زیان شما را دوست دارند؛ تحقیقاً دشمنی [با اسلام و مسلمانان] از لابلای سخنانشان پدیدار است و آنچه سینه هایشان [از کینه و نفرت] پنهان می دارد بزرگ تر است. ما نشانه ها [یِ دشمنی و کینه آنان] را اگر می اندیشید برای شما روشن ساختیم."},{"s":"سُورَةُ آلِ عِمۡرَانَ","n":128,"ar":"لَيْسَ لَكَ مِنَ ٱلْأَمْرِ شَىْءٌ أَوْ يَتُوبَ عَلَيْهِمْ أَوْ يُعَذِّبَهُمْ فَإِنَّهُمْ ظَٰلِمُونَ","fa":"زمام چیزی از امور [مشرکان و مؤمنانِ فراری از جنگ] در اختیار تو نیست، یا توبه آنان را [به شرط آنکه توبه کنند] می پذیرد یا عذابشان می کند؛ زیرا آنان ستمکارند."},{"s":"سُورَةُ آلِ عِمۡرَانَ","n":138,"ar":"هَٰذَا بَيَانٌۭ لِّلنَّاسِ وَهُدًۭى وَمَوْعِظَةٌۭ لِّلْمُتَّقِينَ","fa":"این [قرآن] برای مردم، بیانگر [حوادث و واقعیات] و برای پرهیزکاران، سراسر هدایت و اندرز است."},{"s":"سُورَةُ آلِ عِمۡرَانَ","n":148,"ar":"فَـَٔاتَىٰهُمُ ٱللَّهُ ثَوَابَ ٱلدُّنْيَا وَحُسْنَ ثَوَابِ ٱلْءَاخِرَةِ ۗ وَٱللَّهُ يُحِبُّ ٱلْمُحْسِنِينَ","fa":"پس خدا پاداش این دنیا و پاداش نیک آخرت را به آنان عطا فرمود؛ و خدا نیکوکاران را دوست دارد."},{"s":"سُورَةُ آلِ عِمۡرَانَ","n":158,"ar":"وَلَئِن مُّتُّمْ أَوْ قُتِلْتُمْ لَإِلَى ٱللَّهِ تُحْشَرُونَ","fa":"و اگر بمیرید یا شهید شوید، به سوی خدا محشور خواهید شد."},{"s":"سُورَةُ آلِ عِمۡرَانَ","n":168,"ar":"ٱلَّذِينَ قَالُوا۟ لِإِخْوَٰنِهِمْ وَقَعَدُوا۟ لَوْ أَطَاعُونَا مَا قُتِلُوا۟ ۗ قُلْ فَٱدْرَءُوا۟ عَنْ أَنفُسِكُمُ ٱلْمَوْتَ إِن كُنتُمْ صَٰدِقِينَ","fa":"همان کسانی که [از جنگ کناره گرفتند]، و در خانه های خود نشستند، و درباره برادرانشان گفتند: اگر از ما فرمان می بردند کشته نمی شدند. بگو: [چنانچه اختیار مرگ در دست شماست] پس مرگ را از خود دفع کنید، اگر راستگویید."},{"s":"سُورَةُ آلِ عِمۡرَانَ","n":178,"ar":"وَلَا يَحْسَبَنَّ ٱلَّذِينَ كَفَرُوٓا۟ أَنَّمَا نُمْلِى لَهُمْ خَيْرٌۭ لِّأَنفُسِهِمْ ۚ إِنَّمَا نُمْلِى لَهُمْ لِيَزْدَادُوٓا۟ إِثْمًۭا ۚ وَلَهُمْ عَذَابٌۭ مُّهِينٌۭ","fa":"و کسانی که کافر شدند، گمان نکنند مهلتی که به آنان می دهیم به سودشان خواهد بود، جز این نیست که مهلتشان می دهیم تا بر گناه خود بیفزایند، و برای آنان عذابی خوار کننده است."},{"s":"سُورَةُ آلِ عِمۡرَانَ","n":188,"ar":"لَا تَحْسَبَنَّ ٱلَّذِينَ يَفْرَحُونَ بِمَآ أَتَوا۟ وَّيُحِبُّونَ أَن يُحْمَدُوا۟ بِمَا لَمْ يَفْعَلُوا۟ فَلَا تَحْسَبَنَّهُم بِمَفَازَةٍۢ مِّنَ ٱلْعَذَابِ ۖ وَلَهُمْ عَذَابٌ أَلِيمٌۭ","fa":"البته مپندار کسانی که به آنچه [از پنهان داشتن حقایق و باز داشتن مردم از اسلام] انجام دادند، شادمانی می کنند، و دوست دارند به آنچه انجام نداده اند ستایش شوند [از عذاب خدا در امانند،] پس گمان مبر که برای آنان نجاتی از عذاب است، [بلکه] برای آنان عذابی دردناک خواهد بود."},{"s":"سُورَةُ آلِ عِمۡرَانَ","n":198,"ar":"لَٰكِنِ ٱلَّذِينَ ٱتَّقَوْا۟ رَبَّهُمْ لَهُمْ جَنَّٰتٌۭ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ خَٰلِدِينَ فِيهَا نُزُلًۭا مِّنْ عِندِ ٱللَّهِ ۗ وَمَا عِندَ ٱللَّهِ خَيْرٌۭ لِّلْأَبْرَارِ","fa":"کسانی که از پروردگارشان پروا کردند [و فریفته زرق و برق زندگی مادی نشدند] برای آنان بهشت هایی است که از زیرِ [درختانِ] آن نهرها جاری است، در آنجا جاودانه اند. [این به عنوان آغاز] پذیرایی از سوی خداست، و آنچه [غیر از بهشت و نعمت هایش] نزد خداست، برای نیکوکاران بهتر است."},{"s":"سُورَةُ النِّسَاءِ","n":8,"ar":"وَإِذَا حَضَرَ ٱلْقِسْمَةَ أُو۟لُوا۟ ٱلْقُرْبَىٰ وَٱلْيَتَٰمَىٰ وَٱلْمَسَٰكِينُ فَٱرْزُقُوهُم مِّنْهُ وَقُولُوا۟ لَهُمْ قَوْلًۭا مَّعْرُوفًۭا","fa":"چون هنگام تقسیم کردن ارث، خویشاوندان و یتیمان و مستمندان حاضر شدند، چیزی از آن را به ایشان بدهید، و با آنان سخنی شایسته و پسندیده گویید."},{"s":"سُورَةُ النِّسَاءِ","n":18,"ar":"وَلَيْسَتِ ٱلتَّوْبَةُ لِلَّذِينَ يَعْمَلُونَ ٱلسَّيِّـَٔاتِ حَتَّىٰٓ إِذَا حَضَرَ أَحَدَهُمُ ٱلْمَوْتُ قَالَ إِنِّى تُبْتُ ٱلْـَٰٔنَ وَلَا ٱلَّذِينَ يَمُوتُونَ وَهُمْ كُفَّارٌ ۚ أُو۟لَٰٓئِكَ أَعْتَدْنَا لَهُمْ عَذَابًا أَلِيمًۭا","fa":"و برای کسانی که پیوسته کارهای زشت مرتکب می شوند، تا زمانی که مرگ یکی از آنان فرا رسد [و در آن لحظه که تمام فرصت ها از دست رفته] گوید: اکنون توبه کردم. و نیز برای آنان که در حال کفر از دنیا می روند، توبه نیست. اینانند که عذابی دردناک برای آنان آماده کرده ایم."},{"s":"سُورَةُ النِّسَاءِ","n":28,"ar":"يُرِيدُ ٱللَّهُ أَن يُخَفِّفَ عَنكُمْ ۚ وَخُلِقَ ٱلْإِنسَٰنُ ضَعِيفًۭا","fa":"خدا می خواهد [با تشریع ازدواج با زنان مؤمن، و ازدواج با کنیزان مؤمن، و ازدواج موقت، بار مشکلات زندگی و مشقت های روابط نامشروع جنسی را] بر شما سبک کند؛ و انسان [در برابر مشکلات و شهوات جنسی] ناتوان آفریده شده است."},{"s":"سُورَةُ النِّسَاءِ","n":38,"ar":"وَٱلَّذِينَ يُنفِقُونَ أَمْوَٰلَهُمْ رِئَآءَ ٱلنَّاسِ وَلَا يُؤْمِنُونَ بِٱللَّهِ وَلَا بِٱلْيَوْمِ ٱلْءَاخِرِ ۗ وَمَن يَكُنِ ٱلشَّيْطَٰنُ لَهُۥ قَرِينًۭا فَسَآءَ قَرِينًۭا","fa":"و آنان که اموالشان را از روی ریا و خودنمایی به مردم انفاق می کنند، و به خدا و روز قیامت ایمان ندارند [شیطان همدم آنان است]. و هر کس شیطانْ همدم او باشد بی تردید بد همدمی است."},{"s":"سُورَةُ النِّسَاءِ","n":48,"ar":"إِنَّ ٱللَّهَ لَا يَغْفِرُ أَن يُشْرَكَ بِهِۦ وَيَغْفِرُ مَا دُونَ ذَٰلِكَ لِمَن يَشَآءُ ۚ وَمَن يُشْرِكْ بِٱللَّهِ فَقَدِ ٱفْتَرَىٰٓ إِثْمًا عَظِيمًا","fa":"مسلماً خدا اینکه به او شرک ورزیده شود نمی آمرزد، و غیر آن را برای هر کس که بخواهد می آمرزد. و هر که به خدا شرک بیاورد، مسلماً گناه بزرگی را مرتکب شده است."},{"s":"سُورَةُ النِّسَاءِ","n":58,"ar":"۞ إِنَّ ٱللَّهَ يَأْمُرُكُمْ أَن تُؤَدُّوا۟ ٱلْأَمَٰنَٰتِ إِلَىٰٓ أَهْلِهَا وَإِذَا حَكَمْتُم بَيْنَ ٱلنَّاسِ أَن تَحْكُمُوا۟ بِٱلْعَدْلِ ۚ إِنَّ ٱللَّهَ نِعِمَّا يَعِظُكُم بِهِۦٓ ۗ إِنَّ ٱللَّهَ كَانَ سَمِيعًۢا بَصِيرًۭا","fa":"خدا قاطعانه به شما فرمان می دهد که امانت ها را به صاحبانش بازگردانید و هنگامی که میان مردم داوری می کنید، به عدالت داوری کنید. یقیناً [فرمان بازگردانیدن امانت و عدالت در داوری] نیکو چیزی است که خدا شما را به آن موعظه می کند؛ بی تردید خدا همواره شنوا و بیناست."},{"s":"سُورَةُ النِّسَاءِ","n":68,"ar":"وَلَهَدَيْنَٰهُمْ صِرَٰطًۭا مُّسْتَقِيمًۭا","fa":"و بی تردید آنان را به راهی راست راهنمایی می کردیم."},{"s":"سُورَةُ النِّسَاءِ","n":78,"ar":"أَيْنَمَا تَكُونُوا۟ يُدْرِككُّمُ ٱلْمَوْتُ وَلَوْ كُنتُمْ فِى بُرُوجٍۢ مُّشَيَّدَةٍۢ ۗ وَإِن تُصِبْهُمْ حَسَنَةٌۭ يَقُولُوا۟ هَٰذِهِۦ مِنْ عِندِ ٱللَّهِ ۖ وَإِن تُصِبْهُمْ سَيِّئَةٌۭ يَقُولُوا۟ هَٰذِهِۦ مِنْ عِندِكَ ۚ قُلْ كُلٌّۭ مِّنْ عِندِ ٱللَّهِ ۖ فَمَالِ هَٰٓؤُلَآءِ ٱلْقَوْمِ لَا يَكَادُونَ يَفْقَهُونَ حَدِيثًۭا","fa":"هر کجا باشید هر چند در قلعه های مرتفع و استوار، مرگ شما را درمی یابد. و اگر خیری [چون پیروزی و غنیمت] به آنان [که سست ایمان و منافق اند] برسد، می گویند: این از سوی خداست. و اگر سختی وحادثه ای [چون بیماری، تنگدستی، شکست وناکامی] به آنان رسد [به پیامبر اسلام] می گویند: از ناحیه توست. بگو: همه اینها از سوی خداست. این گروه را چه شده که نمی خواهند [معارف الهیّه وحقایق را] بفهمند؟!"},{"s":"سُورَةُ النِّسَاءِ","n":88,"ar":"۞ فَمَا لَكُمْ فِى ٱلْمُنَٰفِقِينَ فِئَتَيْنِ وَٱللَّهُ أَرْكَسَهُم بِمَا كَسَبُوٓا۟ ۚ أَتُرِيدُونَ أَن تَهْدُوا۟ مَنْ أَضَلَّ ٱللَّهُ ۖ وَمَن يُضْلِلِ ٱللَّهُ فَلَن تَجِدَ لَهُۥ سَبِيلًۭا","fa":"شما را چه شده که درباره منافقین دو گروه شده اید؟ [گروهی شفیع و طرفدار، و گروهی مخالف و دشمن آنان] در صورتی که خدا آنان را به کیفر اعمال ناپسندی که مرتکب شده اند [در چاه کفر و گمراهی] نگونسار کرده است. آیا می خواهید کسانی را که خدا [به خاطر اعمال ناپسندشان] گمراه کرده هدایت کنید؟ [ای پیامبر!] در حالی که خدا هر که را گمراه کند هرگز برای او راهی [به سوی هدایت] نخواهی یافت."},{"s":"سُورَةُ النِّسَاءِ","n":98,"ar":"إِلَّا ٱلْمُسْتَضْعَفِينَ مِنَ ٱلرِّجَالِ وَٱلنِّسَآءِ وَٱلْوِلْدَٰنِ لَا يَسْتَطِيعُونَ حِيلَةًۭ وَلَا يَهْتَدُونَ سَبِيلًۭا","fa":"مگر مردان و زنان و کودکان مستضعفی که [برای نجات خود از محیط کفر و شرک] هیچ چاره ای ندارند، و راهی [برای هجرت] نمی یابند."},{"s":"سُورَةُ النِّسَاءِ","n":108,"ar":"يَسْتَخْفُونَ مِنَ ٱلنَّاسِ وَلَا يَسْتَخْفُونَ مِنَ ٱللَّهِ وَهُوَ مَعَهُمْ إِذْ يُبَيِّتُونَ مَا لَا يَرْضَىٰ مِنَ ٱلْقَوْلِ ۚ وَكَانَ ٱللَّهُ بِمَا يَعْمَلُونَ مُحِيطًا","fa":"[خیانت پیشگانْ خیانت خود را] از مردم پنهان می دارند، و [نمی توانند] از خدا پنهان نمایند، و خدا با آنان بود آن گاه که در جلسه مخفی شبانه، درباره طرح و نقشه و سخنی که خدا به آن رضایت نداشت، چاره اندیشی می کردند و خدا همواره به آنچه انجام می دهند، احاطه دارد."},{"s":"سُورَةُ النِّسَاءِ","n":118,"ar":"لَّعَنَهُ ٱللَّهُ ۘ وَقَالَ لَأَتَّخِذَنَّ مِنْ عِبَادِكَ نَصِيبًۭا مَّفْرُوضًۭا","fa":"خدا شیطان را از رحمتش دور کرد؛ و [او] گفت: سوگند می خورم که از میان بندگانت سهمی مُعیّن [برای پیروی از فرهنگ ویرانگرم] برخواهم گرفت."},{"s":"سُورَةُ النِّسَاءِ","n":128,"ar":"وَإِنِ ٱمْرَأَةٌ خَافَتْ مِنۢ بَعْلِهَا نُشُوزًا أَوْ إِعْرَاضًۭا فَلَا جُنَاحَ عَلَيْهِمَآ أَن يُصْلِحَا بَيْنَهُمَا صُلْحًۭا ۚ وَٱلصُّلْحُ خَيْرٌۭ ۗ وَأُحْضِرَتِ ٱلْأَنفُسُ ٱلشُّحَّ ۚ وَإِن تُحْسِنُوا۟ وَتَتَّقُوا۟ فَإِنَّ ٱللَّهَ كَانَ بِمَا تَعْمَلُونَ خَبِيرًۭا","fa":"و اگر زنی از ناسازگاری شوهرش، یا روی گردانی اش [از حقوق همسرداری] بترسد، بر آن دو گناهی نیست که با یکدیگر به طور شایسته و پسندیده آشتی کنند، [گرچه به چشم پوشی بخشی از حقوقشان باشد.] و [در حقیقت] صلح و آشتی بهتر است. و بخل، نزد نفوس [آدمیان] حاضر است [به این خاطر هر یک از دو زوج در عفو و گذشت و سازش و ادای حقوق بخل می ورزند]. و اگر [شما شوهران] نیکی کنید و [از سرکشی و ناسازگاری نسبت به زنان] بپرهیزید [از ثواب و پاداش حق بهره مند می شوید]؛ یقیناً خدا همواره به آنچه انجام می دهید، آگاه است."},{"s":"سُورَةُ النِّسَاءِ","n":138,"ar":"بَشِّرِ ٱلْمُنَٰفِقِينَ بِأَنَّ لَهُمْ عَذَابًا أَلِيمًا","fa":"منافقان را بشارت ده که عذابی دردناک برای آنان است."},{"s":"سُورَةُ النِّسَاءِ","n":148,"ar":"۞ لَّا يُحِبُّ ٱللَّهُ ٱلْجَهْرَ بِٱلسُّوٓءِ مِنَ ٱلْقَوْلِ إِلَّا مَن ظُلِمَ ۚ وَكَانَ ٱللَّهُ سَمِيعًا عَلِيمًا","fa":"خدا افشای بدی های دیگران را دوست ندارد، جز برای کسی که مورد ستم قرار گرفته است [که بر ستمدیده برای دفع ستم، افشای بدی های ستمکار جایز است]؛ و خدا شنوا و داناست."},{"s":"سُورَةُ النِّسَاءِ","n":158,"ar":"بَل رَّفَعَهُ ٱللَّهُ إِلَيْهِ ۚ وَكَانَ ٱللَّهُ عَزِيزًا حَكِيمًۭا","fa":"بلکه خدا او را به سوی خود بالا برد؛ و خدا همواره توانای شکست ناپذیر و حکیم است."},{"s":"سُورَةُ النِّسَاءِ","n":168,"ar":"إِنَّ ٱلَّذِينَ كَفَرُوا۟ وَظَلَمُوا۟ لَمْ يَكُنِ ٱللَّهُ لِيَغْفِرَ لَهُمْ وَلَا لِيَهْدِيَهُمْ طَرِيقًا","fa":"بی تردید کسانی که کافر شدند و [به آیات الهی، به خود و به دیگران] ستم ورزیدند، خدا بر آن نیست که آنان را بیامرزد و به راهی [مستقیم و استوار] هدایت کند."},{"s":"سُورَةُ المَائـِدَةِ","n":2,"ar":"يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تُحِلُّوا۟ شَعَٰٓئِرَ ٱللَّهِ وَلَا ٱلشَّهْرَ ٱلْحَرَامَ وَلَا ٱلْهَدْىَ وَلَا ٱلْقَلَٰٓئِدَ وَلَآ ءَآمِّينَ ٱلْبَيْتَ ٱلْحَرَامَ يَبْتَغُونَ فَضْلًۭا مِّن رَّبِّهِمْ وَرِضْوَٰنًۭا ۚ وَإِذَا حَلَلْتُمْ فَٱصْطَادُوا۟ ۚ وَلَا يَجْرِمَنَّكُمْ شَنَـَٔانُ قَوْمٍ أَن صَدُّوكُمْ عَنِ ٱلْمَسْجِدِ ٱلْحَرَامِ أَن تَعْتَدُوا۟ ۘ وَتَعَاوَنُوا۟ عَلَى ٱلْبِرِّ وَٱلتَّقْوَىٰ ۖ وَلَا تَعَاوَنُوا۟ عَلَى ٱلْإِثْمِ وَٱلْعُدْوَٰنِ ۚ وَٱتَّقُوا۟ ٱللَّهَ ۖ إِنَّ ٱللَّهَ شَدِيدُ ٱلْعِقَابِ","fa":"ای اهل ایمان! [هتکِ حرمتِ] شعایر خدا [مانند مناسک حج] و ماه های حرام [رجب، ذوالقعده، ذوالحجه ومحرم] و قربانی بی نشان، و قربانی نشان دار و قاصدان [و راهیان به سوی] بیت الحرام را که فضل و خشنودی پروردگارشان را می طلبند، حلال مشمارید. و چون از احرام بیرون آمدید [اگر مایل باشید، می توانید] شکار کنید. و کینه توزی و دشمنی گروهی که شما را از [ورود به] مسجد الحرام بازداشتند وادارتان نکند که [به آنان] تعدّی و تجاوز کنید. و یکدیگر را بر انجام کارهای خیر و پرهیزکاری یاری نمایید، و یکدیگر را بر گناه و تجاوز یاری ندهید؛ و از خدا پروا کنید که خدا سخت کیفر است."},{"s":"سُورَةُ المَائـِدَةِ","n":12,"ar":"۞ وَلَقَدْ أَخَذَ ٱللَّهُ مِيثَٰقَ بَنِىٓ إِسْرَٰٓءِيلَ وَبَعَثْنَا مِنْهُمُ ٱثْنَىْ عَشَرَ نَقِيبًۭا ۖ وَقَالَ ٱللَّهُ إِنِّى مَعَكُمْ ۖ لَئِنْ أَقَمْتُمُ ٱلصَّلَوٰةَ وَءَاتَيْتُمُ ٱلزَّكَوٰةَ وَءَامَنتُم بِرُسُلِى وَعَزَّرْتُمُوهُمْ وَأَقْرَضْتُمُ ٱللَّهَ قَرْضًا حَسَنًۭا لَّأُكَفِّرَنَّ عَنكُمْ سَيِّـَٔاتِكُمْ وَلَأُدْخِلَنَّكُمْ جَنَّٰتٍۢ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ ۚ فَمَن كَفَرَ بَعْدَ ذَٰلِكَ مِنكُمْ فَقَدْ ضَلَّ سَوَآءَ ٱلسَّبِيلِ","fa":"خدا از بنی اسرائیل [بر لزوم اطاعت از آیینش و پیروی از موسی] پیمان گرفت، و از میان آنان دوازده سرپرست برانیگختیم [تا هر یک عهده دار امور قبیله ای از قبایل بنی اسرائیل باشد]، و خدا به آنان فرمود: یقیناً من با شمایم، اگر نماز را برپا دارید، و زکات بپردازید، و به پیامبرانم ایمان آورید، و آنان را تقویت و یاری کنید و به خدا وامی نیکو دهید، مسلماً گناهانتان را محو می کنم، و شما را در بهشت هایی که از زیرِ [درختانِ] آن نهرها جاری است در می آورم؛ پس هر که از شما بعد از این کافر شود، یقیناً راه راست را گم کرده است."},{"s":"سُورَةُ المَائـِدَةِ","n":22,"ar":"قَالُوا۟ يَٰمُوسَىٰٓ إِنَّ فِيهَا قَوْمًۭا جَبَّارِينَ وَإِنَّا لَن نَّدْخُلَهَا حَتَّىٰ يَخْرُجُوا۟ مِنْهَا فَإِن يَخْرُجُوا۟ مِنْهَا فَإِنَّا دَٰخِلُونَ","fa":"گفتند: ای موسی! مسلماً در آنجا مردمی زورگو و ستم گر قرار دارند، و ما هرگز وارد آنجا نمی شویم تا آنان از آنجا بیرون روند، پس اگر از آنجا بیرون روند البته ما وارد خواهیم شد."},{"s":"سُورَةُ المَائـِدَةِ","n":32,"ar":"مِنْ أَجْلِ ذَٰلِكَ كَتَبْنَا عَلَىٰ بَنِىٓ إِسْرَٰٓءِيلَ أَنَّهُۥ مَن قَتَلَ نَفْسًۢا بِغَيْرِ نَفْسٍ أَوْ فَسَادٍۢ فِى ٱلْأَرْضِ فَكَأَنَّمَا قَتَلَ ٱلنَّاسَ جَمِيعًۭا وَمَنْ أَحْيَاهَا فَكَأَنَّمَآ أَحْيَا ٱلنَّاسَ جَمِيعًۭا ۚ وَلَقَدْ جَآءَتْهُمْ رُسُلُنَا بِٱلْبَيِّنَٰتِ ثُمَّ إِنَّ كَثِيرًۭا مِّنْهُم بَعْدَ ذَٰلِكَ فِى ٱلْأَرْضِ لَمُسْرِفُونَ","fa":"به این سبب بر بنی اسرائیل لازم و مقرّر کردیم که هر کس انسانی را جز برای حق، [قصاص] یا بدون آنکه فسادی در زمین کرده باشد، بکشد، چنان است که همه انسان ها را کشته، و هر کس انسانی را از مرگ برهاند و زنده بدارد، گویی همه انسان ها را زنده داشته است. و یقیناً پیامبران دلایل روشنی برای بنی اسرائیل آوردند، سپس بسیاری از آنان بعد از آن در روی زمین به [تجاوز از حدود حقّ و فساد و] زیاده روی برخاستند."},{"s":"سُورَةُ المَائـِدَةِ","n":42,"ar":"سَمَّٰعُونَ لِلْكَذِبِ أَكَّٰلُونَ لِلسُّحْتِ ۚ فَإِن جَآءُوكَ فَٱحْكُم بَيْنَهُمْ أَوْ أَعْرِضْ عَنْهُمْ ۖ وَإِن تُعْرِضْ عَنْهُمْ فَلَن يَضُرُّوكَ شَيْـًۭٔا ۖ وَإِنْ حَكَمْتَ فَٱحْكُم بَيْنَهُم بِٱلْقِسْطِ ۚ إِنَّ ٱللَّهَ يُحِبُّ ٱلْمُقْسِطِينَ","fa":"آنان فوق العاده شِنوای دروغ اند [با آنکه می دانند دروغ است و] بسیار خورنده مال حرام؛ پس اگر نزد تو آمدند میان آنان [در آنچه تو را داور قرار دادند] داوری کن، یا [اگر نخواستی داوری کنی] از آنان روی برتاب. و اگر روی برتابی هرگز هیچ زیانی به تو نمی رسانند. و اگر میانشان داوری کردی به عدالت داوری کن؛ زیرا خدا عدالت پیشگان را دوست دارد."},{"s":"سُورَةُ المَائـِدَةِ","n":52,"ar":"فَتَرَى ٱلَّذِينَ فِى قُلُوبِهِم مَّرَضٌۭ يُسَٰرِعُونَ فِيهِمْ يَقُولُونَ نَخْشَىٰٓ أَن تُصِيبَنَا دَآئِرَةٌۭ ۚ فَعَسَى ٱللَّهُ أَن يَأْتِىَ بِٱلْفَتْحِ أَوْ أَمْرٍۢ مِّنْ عِندِهِۦ فَيُصْبِحُوا۟ عَلَىٰ مَآ أَسَرُّوا۟ فِىٓ أَنفُسِهِمْ نَٰدِمِينَ","fa":"کسانی که در دل هایشان بیماری [دورویی] است، می بینی که در دوستی با یهود و نصاری شتاب می ورزند و [بر پایه خیال باطلشان که مبادا اسلام و مسلمانان تکیه گاه استواری نباشند] می گویند: می ترسیم آسیب و گزند ناگواری به ما برسد [به این سبب باید برای دوستی به سوی یهود و نصاری بشتابیم]. امید است خدا از سوی خود پیروزی یا واقعیت دیگری [به نفع مسلمانان] پیش آرد تا این بیماردلان بر آنچه در دل هایشان پنهان می داشتند، پشیمان شوند."},{"s":"سُورَةُ المَائـِدَةِ","n":62,"ar":"وَتَرَىٰ كَثِيرًۭا مِّنْهُمْ يُسَٰرِعُونَ فِى ٱلْإِثْمِ وَٱلْعُدْوَٰنِ وَأَكْلِهِمُ ٱلسُّحْتَ ۚ لَبِئْسَ مَا كَانُوا۟ يَعْمَلُونَ","fa":"و بسیاری از آنان را می بینی که در گناه و تجاوز [از حدود خدا] و حرام خوری خود می شتابند؛ همانا بد است اعمالی که همواره انجام می دادند."},{"s":"سُورَةُ المَائـِدَةِ","n":72,"ar":"لَقَدْ كَفَرَ ٱلَّذِينَ قَالُوٓا۟ إِنَّ ٱللَّهَ هُوَ ٱلْمَسِيحُ ٱبْنُ مَرْيَمَ ۖ وَقَالَ ٱلْمَسِيحُ يَٰبَنِىٓ إِسْرَٰٓءِيلَ ٱعْبُدُوا۟ ٱللَّهَ رَبِّى وَرَبَّكُمْ ۖ إِنَّهُۥ مَن يُشْرِكْ بِٱللَّهِ فَقَدْ حَرَّمَ ٱللَّهُ عَلَيْهِ ٱلْجَنَّةَ وَمَأْوَىٰهُ ٱلنَّارُ ۖ وَمَا لِلظَّٰلِمِينَ مِنْ أَنصَارٍۢ","fa":"آنان که گفتند: خدا همان مسیح، فرزند مریم است، بی تردید کافر شدند؛ و حال آنکه مسیح گفت: ای بنی اسرائیل! خدای یکتا را که پروردگار من و پروردگار شماست بپرستید، مسلماً هر کس به خدا شرک ورزد، بی تردید خدا بهشت را بر او حرام کند، و جایگاهش آتش است، و برای ستمکاران هیچ یاوری نیست."},{"s":"سُورَةُ المَائـِدَةِ","n":82,"ar":"۞ لَتَجِدَنَّ أَشَدَّ ٱلنَّاسِ عَدَٰوَةًۭ لِّلَّذِينَ ءَامَنُوا۟ ٱلْيَهُودَ وَٱلَّذِينَ أَشْرَكُوا۟ ۖ وَلَتَجِدَنَّ أَقْرَبَهُم مَّوَدَّةًۭ لِّلَّذِينَ ءَامَنُوا۟ ٱلَّذِينَ قَالُوٓا۟ إِنَّا نَصَٰرَىٰ ۚ ذَٰلِكَ بِأَنَّ مِنْهُمْ قِسِّيسِينَ وَرُهْبَانًۭا وَأَنَّهُمْ لَا يَسْتَكْبِرُونَ","fa":"یقیناً سرسخت ترین مردم را در کینه و دشمنی نسبت به مؤمنان، یهودیان و مشرکان خواهی یافت. و البته نزدیک ترینشان را در دوستی با مؤمنان، کسانی می یابی که گفتند: ما نصرانی هستیم. این واقعیت برای آن است که گروهی از آنان کشیشان دانشمند و عابدان خدا ترس اند، و آنان [در پیروی از حق] تکبّر نمی کنند."},{"s":"سُورَةُ المَائـِدَةِ","n":92,"ar":"وَأَطِيعُوا۟ ٱللَّهَ وَأَطِيعُوا۟ ٱلرَّسُولَ وَٱحْذَرُوا۟ ۚ فَإِن تَوَلَّيْتُمْ فَٱعْلَمُوٓا۟ أَنَّمَا عَلَىٰ رَسُولِنَا ٱلْبَلَٰغُ ٱلْمُبِينُ","fa":"و از خدا اطاعت کنید و از پیامبر فرمان برید، و [از مخالفت با خدا و پیامبر] بپرهیزید، پس اگر روی گردانید [سزاوار کیفر می شوید]، و بدانید که بر عهده پیامبر ما فقط رساندن آشکارِ [پیام وحی] است."},{"s":"سُورَةُ المَائـِدَةِ","n":102,"ar":"قَدْ سَأَلَهَا قَوْمٌۭ مِّن قَبْلِكُمْ ثُمَّ أَصْبَحُوا۟ بِهَا كَٰفِرِينَ","fa":"گروهی از پیشینیان شما از آن احکام و معارف پرسیدند، [چون برای آنان روشن شد، از اجرایش روی گرداندند] سپس به آن کافر شدند."},{"s":"سُورَةُ المَائـِدَةِ","n":112,"ar":"إِذْ قَالَ ٱلْحَوَارِيُّونَ يَٰعِيسَى ٱبْنَ مَرْيَمَ هَلْ يَسْتَطِيعُ رَبُّكَ أَن يُنَزِّلَ عَلَيْنَا مَآئِدَةًۭ مِّنَ ٱلسَّمَآءِ ۖ قَالَ ٱتَّقُوا۟ ٱللَّهَ إِن كُنتُم مُّؤْمِنِينَ","fa":"[و یاد کنید] زمانی که حواریون گفتند: ای عیسی بن مریم! آیا پروردگارت می تواند برای ما سفره ای که غذا در آن باشد از آسمان نازل کند؟! گفت: اگر ایمان دارید، از خدا پروا کنید."},{"s":"سُورَةُ الأَنۡعَامِ","n":2,"ar":"هُوَ ٱلَّذِى خَلَقَكُم مِّن طِينٍۢ ثُمَّ قَضَىٰٓ أَجَلًۭا ۖ وَأَجَلٌۭ مُّسَمًّى عِندَهُۥ ۖ ثُمَّ أَنتُمْ تَمْتَرُونَ","fa":"اوست که شما را از گِلی مخصوص آفرید، سپس برای عمر شما مدتی مقرّر کرد، و اجل حتمی و ثابت نزد اوست، [شگفتا! که] باز شما [با این همه دلایل آشکار در یکتایی و ربوبیّت و خالقیّت او] شک می کنید."},{"s":"سُورَةُ الأَنۡعَامِ","n":12,"ar":"قُل لِّمَن مَّا فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ ۖ قُل لِّلَّهِ ۚ كَتَبَ عَلَىٰ نَفْسِهِ ٱلرَّحْمَةَ ۚ لَيَجْمَعَنَّكُمْ إِلَىٰ يَوْمِ ٱلْقِيَٰمَةِ لَا رَيْبَ فِيهِ ۚ ٱلَّذِينَ خَسِرُوٓا۟ أَنفُسَهُمْ فَهُمْ لَا يُؤْمِنُونَ","fa":"بگو: مالکیّت و فرمانروایی آنچه در آسمان ها و زمین است در سیطره کیست؟ بگو: در سیطره خداست که رحمت را بر خود لازم و مقرّر کرده؛ یقیناً همه شما را در روز قیامت که تردیدی در آن نیست جمع خواهد کرد. فقط کسانی که سرمایه وجودشان را تباه کرده اند، ایمان نمی آورند."},{"s":"سُورَةُ الأَنۡعَامِ","n":22,"ar":"وَيَوْمَ نَحْشُرُهُمْ جَمِيعًۭا ثُمَّ نَقُولُ لِلَّذِينَ أَشْرَكُوٓا۟ أَيْنَ شُرَكَآؤُكُمُ ٱلَّذِينَ كُنتُمْ تَزْعُمُونَ","fa":"و [یاد کنید] روزی که همه آنان را [در عرصه قیامت] جمع می کنیم، سپس به کسانی که شرک ورزیده اند، می گوییم: شریکانتان که آنان را شریک خدا می پنداشتید، کجایند [تا شما را از عذاب امروز نجات دهند؟]"},{"s":"سُورَةُ الأَنۡعَامِ","n":32,"ar":"وَمَا ٱلْحَيَوٰةُ ٱلدُّنْيَآ إِلَّا لَعِبٌۭ وَلَهْوٌۭ ۖ وَلَلدَّارُ ٱلْءَاخِرَةُ خَيْرٌۭ لِّلَّذِينَ يَتَّقُونَ ۗ أَفَلَا تَعْقِلُونَ","fa":"و زندگی دنیا [بدون ایمان و عمل صالح] بازی و سرگرمی است، و یقیناً سرای آخرت برای آنان که همواره پرهیزکاری می کنند، بهتر است. آیا نمی اندیشید؟"},{"s":"سُورَةُ الأَنۡعَامِ","n":42,"ar":"وَلَقَدْ أَرْسَلْنَآ إِلَىٰٓ أُمَمٍۢ مِّن قَبْلِكَ فَأَخَذْنَٰهُم بِٱلْبَأْسَآءِ وَٱلضَّرَّآءِ لَعَلَّهُمْ يَتَضَرَّعُونَ","fa":"و بی تردید ما به سوی امت هایی که پیش از تو بودند [پیامبرانی] فرستادیم؛ پس آنان را [هنگامی که با پیامبران به مخالفت و دشمنی برخاستند] به تهیدستی و سختی و رنج و بیماری دچار کردیم، باشد که [در پیشگاه ما] فروتنی و زاری کنند."},{"s":"سُورَةُ الأَنۡعَامِ","n":52,"ar":"وَلَا تَطْرُدِ ٱلَّذِينَ يَدْعُونَ رَبَّهُم بِٱلْغَدَوٰةِ وَٱلْعَشِىِّ يُرِيدُونَ وَجْهَهُۥ ۖ مَا عَلَيْكَ مِنْ حِسَابِهِم مِّن شَىْءٍۢ وَمَا مِنْ حِسَابِكَ عَلَيْهِم مِّن شَىْءٍۢ فَتَطْرُدَهُمْ فَتَكُونَ مِنَ ٱلظَّٰلِمِينَ","fa":"و آنان که بامدادان و شامگاهان پروردگارشان را می خوانند [و با این خواندن] خشنودی او را می خواهند، از خود مران. نه چیزی از حساب [عمل] آنان بر عهده توست، و نه چیزی از حساب [کار] تو بر عهده آنان است تا آنان را برانی و [به سبب راندنشان] از ستمکاران باشی."},{"s":"سُورَةُ الأَنۡعَامِ","n":62,"ar":"ثُمَّ رُدُّوٓا۟ إِلَى ٱللَّهِ مَوْلَىٰهُمُ ٱلْحَقِّ ۚ أَلَا لَهُ ٱلْحُكْمُ وَهُوَ أَسْرَعُ ٱلْحَٰسِبِينَ","fa":"سپس [همه] به سوی خدا، سرپرست و مولای به حقّشان بازگردانده می شوند. آگاه باشید! [که در آن روز] فرمانروایی و حکومت مطلق فقط ویژه اوست؛ و او سریع ترین حساب گران است."},{"s":"سُورَةُ الأَنۡعَامِ","n":72,"ar":"وَأَنْ أَقِيمُوا۟ ٱلصَّلَوٰةَ وَٱتَّقُوهُ ۚ وَهُوَ ٱلَّذِىٓ إِلَيْهِ تُحْشَرُونَ","fa":"و [نیز فرمان یافته ایم] به اینکه نماز را بر پا دارید و از خدا پروا کنید، و اوست که به سویش گردآوری می شوید."},{"s":"سُورَةُ الأَنۡعَامِ","n":82,"ar":"ٱلَّذِينَ ءَامَنُوا۟ وَلَمْ يَلْبِسُوٓا۟ إِيمَٰنَهُم بِظُلْمٍ أُو۟لَٰٓئِكَ لَهُمُ ٱلْأَمْنُ وَهُم مُّهْتَدُونَ","fa":"کسانی که ایمان آوردند و ایمانشان را به ستمی [چون شرک] نیامیختند، ایمنی [از عذاب] برای آنان است، و آنان راه یافتگانند."},{"s":"سُورَةُ الأَنۡعَامِ","n":92,"ar":"وَهَٰذَا كِتَٰبٌ أَنزَلْنَٰهُ مُبَارَكٌۭ مُّصَدِّقُ ٱلَّذِى بَيْنَ يَدَيْهِ وَلِتُنذِرَ أُمَّ ٱلْقُرَىٰ وَمَنْ حَوْلَهَا ۚ وَٱلَّذِينَ يُؤْمِنُونَ بِٱلْءَاخِرَةِ يُؤْمِنُونَ بِهِۦ ۖ وَهُمْ عَلَىٰ صَلَاتِهِمْ يُحَافِظُونَ","fa":"و این [قرآن] کتابی است پرفایده، که ما آن را نازل کردیم، تصدیق کننده کتاب های آسمانی پیش از خود است، و [نزولش] برای این است که مردم مکه و کسانی را که پیرامون آنند بیم دهی؛ و آنان که به آخرت ایمان دارند به آن ایمان می آورند، و آنان همواره بر نمازشان محافظت می کنند."},{"s":"سُورَةُ الأَنۡعَامِ","n":102,"ar":"ذَٰلِكُمُ ٱللَّهُ رَبُّكُمْ ۖ لَآ إِلَٰهَ إِلَّا هُوَ ۖ خَٰلِقُ كُلِّ شَىْءٍۢ فَٱعْبُدُوهُ ۚ وَهُوَ عَلَىٰ كُلِّ شَىْءٍۢ وَكِيلٌۭ","fa":"این است خدا پروردگار شما، جز او معبودی نیست، آفریننده همه چیز است؛ پس تنها او را بپرستید، و او کارساز هر چیز است."},{"s":"سُورَةُ الأَنۡعَامِ","n":112,"ar":"وَكَذَٰلِكَ جَعَلْنَا لِكُلِّ نَبِىٍّ عَدُوًّۭا شَيَٰطِينَ ٱلْإِنسِ وَٱلْجِنِّ يُوحِى بَعْضُهُمْ إِلَىٰ بَعْضٍۢ زُخْرُفَ ٱلْقَوْلِ غُرُورًۭا ۚ وَلَوْ شَآءَ رَبُّكَ مَا فَعَلُوهُ ۖ فَذَرْهُمْ وَمَا يَفْتَرُونَ","fa":"و این گونه برای هر پیامبری دشمنانی از شیاطین انس و جن قرار دادیم، که برای فریب مردم همواره گفتاری باطل ولی به ظاهر آراسته و دلپسند به یکدیگر القاء می کنند، و اگر پروردگارت می خواست چنین نمی کردند، پس آنان و آنچه را به دروغ به هم می بافند واگذار."},{"s":"سُورَةُ الأَنۡعَامِ","n":122,"ar":"أَوَمَن كَانَ مَيْتًۭا فَأَحْيَيْنَٰهُ وَجَعَلْنَا لَهُۥ نُورًۭا يَمْشِى بِهِۦ فِى ٱلنَّاسِ كَمَن مَّثَلُهُۥ فِى ٱلظُّلُمَٰتِ لَيْسَ بِخَارِجٍۢ مِّنْهَا ۚ كَذَٰلِكَ زُيِّنَ لِلْكَٰفِرِينَ مَا كَانُوا۟ يَعْمَلُونَ","fa":"آیا کسی که [از نظر عقلی و روحی] مرده بود و ما او را [به وسیله هدایت و ایمان] زنده کردیم، و برای وی نوری قرار دادیم تا در پرتو آن در میان مردم [به درستی و سلامت] حرکت کند، مانند کسی است که در تاریکی ها [یِ جهل و گمراهی] است و از آن بیرون شدنی نیست؟! این گونه برای کافران [به خاطر لجاجت و عنادشان] آنچه انجام می دادند، آراسته شد [تا گمان کنند اعمالی را که انجام می دهند نیکوست.]"},{"s":"سُورَةُ الأَنۡعَامِ","n":132,"ar":"وَلِكُلٍّۢ دَرَجَٰتٌۭ مِّمَّا عَمِلُوا۟ ۚ وَمَا رَبُّكَ بِغَٰفِلٍ عَمَّا يَعْمَلُونَ","fa":"و [در قیامت] برای هر کدام [از دو گروه جن و انس] به سزای آنچه انجام می دادند، درجاتی [از ثواب و عذاب] است؛ و پروردگارت از آنچه انجام می دهند، بی خبر نیست."},{"s":"سُورَةُ الأَنۡعَامِ","n":142,"ar":"وَمِنَ ٱلْأَنْعَٰمِ حَمُولَةًۭ وَفَرْشًۭا ۚ كُلُوا۟ مِمَّا رَزَقَكُمُ ٱللَّهُ وَلَا تَتَّبِعُوا۟ خُطُوَٰتِ ٱلشَّيْطَٰنِ ۚ إِنَّهُۥ لَكُمْ عَدُوٌّۭ مُّبِينٌۭ","fa":"و از دام ها، حیوانات باربر و حیوانات کُرک دار و پشم دهنده را [آفرید]؛ از آنچه خدا روزی شما کرده بخورید، و از گام های شیطان پیروی نکنید، که بی تردید او برای شما دشمنی آشکار است."},{"s":"سُورَةُ الأَنۡعَامِ","n":152,"ar":"وَلَا تَقْرَبُوا۟ مَالَ ٱلْيَتِيمِ إِلَّا بِٱلَّتِى هِىَ أَحْسَنُ حَتَّىٰ يَبْلُغَ أَشُدَّهُۥ ۖ وَأَوْفُوا۟ ٱلْكَيْلَ وَٱلْمِيزَانَ بِٱلْقِسْطِ ۖ لَا نُكَلِّفُ نَفْسًا إِلَّا وُسْعَهَا ۖ وَإِذَا قُلْتُمْ فَٱعْدِلُوا۟ وَلَوْ كَانَ ذَا قُرْبَىٰ ۖ وَبِعَهْدِ ٱللَّهِ أَوْفُوا۟ ۚ ذَٰلِكُمْ وَصَّىٰكُم بِهِۦ لَعَلَّكُمْ تَذَكَّرُونَ","fa":"و به مال یتیم جز به روشی که نیکوتر است، نزدیک نشوید تا به حدّ بلوغِ [بدنی و عقلیِ] خود برسد، و پیمانه و ترازو را بر اساس عدالت و انصاف کامل و تمام بدهید؛ هیچ کس را جز به اندازه توانش تکلیف نمی کنیم؛ و هنگامی که سخن گویید، عدالت ورزید هر چند درباره خویشان باشد، و به پیمان خدا وفا کنید؛ خدا این [گونه] به شما سفارش کرده تا پند گیرید."},{"s":"سُورَةُ الأَنۡعَامِ","n":162,"ar":"قُلْ إِنَّ صَلَاتِى وَنُسُكِى وَمَحْيَاىَ وَمَمَاتِى لِلَّهِ رَبِّ ٱلْعَٰلَمِينَ","fa":"بگو: مسلماً نماز و عبادتم و زندگی کردن و مرگم برای خدا پروردگار جهانیان است."},{"s":"سُورَةُ الأَعۡرَافِ","n":7,"ar":"فَلَنَقُصَّنَّ عَلَيْهِم بِعِلْمٍۢ ۖ وَمَا كُنَّا غَآئِبِينَ","fa":"بی تردید برای آنان [در آن روز، عقاید، اعمال و اخلاقشان را] از روی دانشی [دقیق و فراگیر] بیان خواهیم کرد؛ [زیرا] ما هیچ گاه از آنان غایب نبوده ایم."},{"s":"سُورَةُ الأَعۡرَافِ","n":17,"ar":"ثُمَّ لَءَاتِيَنَّهُم مِّنۢ بَيْنِ أَيْدِيهِمْ وَمِنْ خَلْفِهِمْ وَعَنْ أَيْمَٰنِهِمْ وَعَن شَمَآئِلِهِمْ ۖ وَلَا تَجِدُ أَكْثَرَهُمْ شَٰكِرِينَ","fa":"سپس از پیش رو و پشت سر و از طرف راست و از جانب چپشان بر آنان می تازم و [تا جایی آنان را دچار وسوسه و اغواگری می کنم که] بیشترشان را سپاس گزار نخواهی یافت."},{"s":"سُورَةُ الأَعۡرَافِ","n":27,"ar":"يَٰبَنِىٓ ءَادَمَ لَا يَفْتِنَنَّكُمُ ٱلشَّيْطَٰنُ كَمَآ أَخْرَجَ أَبَوَيْكُم مِّنَ ٱلْجَنَّةِ يَنزِعُ عَنْهُمَا لِبَاسَهُمَا لِيُرِيَهُمَا سَوْءَٰتِهِمَآ ۗ إِنَّهُۥ يَرَىٰكُمْ هُوَ وَقَبِيلُهُۥ مِنْ حَيْثُ لَا تَرَوْنَهُمْ ۗ إِنَّا جَعَلْنَا ٱلشَّيَٰطِينَ أَوْلِيَآءَ لِلَّذِينَ لَا يُؤْمِنُونَ","fa":"ای فرزندان آدم! شیطان، شما را نفریبد چنان که پدر و مادرتان را [با فریبکاریش] از بهشت بیرون کرد، لباسشان را از اندامشان بر می کشید تا شرمگاهشان را به آنان بنمایاند، او و دار و دسته اش شما را از آنجا که شما آنان را نمی بینید می بینند، ما شیاطین را سرپرست و یاران کسانی قرار دادیم که ایمان نمی آورند."},{"s":"سُورَةُ الأَعۡرَافِ","n":37,"ar":"فَمَنْ أَظْلَمُ مِمَّنِ ٱفْتَرَىٰ عَلَى ٱللَّهِ كَذِبًا أَوْ كَذَّبَ بِـَٔايَٰتِهِۦٓ ۚ أُو۟لَٰٓئِكَ يَنَالُهُمْ نَصِيبُهُم مِّنَ ٱلْكِتَٰبِ ۖ حَتَّىٰٓ إِذَا جَآءَتْهُمْ رُسُلُنَا يَتَوَفَّوْنَهُمْ قَالُوٓا۟ أَيْنَ مَا كُنتُمْ تَدْعُونَ مِن دُونِ ٱللَّهِ ۖ قَالُوا۟ ضَلُّوا۟ عَنَّا وَشَهِدُوا۟ عَلَىٰٓ أَنفُسِهِمْ أَنَّهُمْ كَانُوا۟ كَٰفِرِينَ","fa":"پس ستمکارتر از کسانی که بر خدا دروغ می بندند، یا آیات او را تکذیب می کنند، کیست؟! آنانند که سهمشان از آنچه که [از نعمت ها] مقرّر و مقدّر شده به آنان می رسد. تا هنگامی که فرستادگان ما برای ستاندن جانشان به سویشان آیند، می گویند: بت ها و معبودهایی که به جای خدا می پرستیدید، کجایند؟ [تا شما را از سختی های مرگ و پس از آن نجات دهند] می گویند: از دست ما رفتند؛ و بر ضد خود گواهی دهند که کافر بوده اند."},{"s":"سُورَةُ الأَعۡرَافِ","n":47,"ar":"۞ وَإِذَا صُرِفَتْ أَبْصَٰرُهُمْ تِلْقَآءَ أَصْحَٰبِ ٱلنَّارِ قَالُوا۟ رَبَّنَا لَا تَجْعَلْنَا مَعَ ٱلْقَوْمِ ٱلظَّٰلِمِينَ","fa":"و چون بهشتیان، چشمانشان ناخواسته به سوی دوزخیان گردانده شود، گویند: پروردگارا! ما را با گروه ستمکاران قرار مده."},{"s":"سُورَةُ الأَعۡرَافِ","n":57,"ar":"وَهُوَ ٱلَّذِى يُرْسِلُ ٱلرِّيَٰحَ بُشْرًۢا بَيْنَ يَدَىْ رَحْمَتِهِۦ ۖ حَتَّىٰٓ إِذَآ أَقَلَّتْ سَحَابًۭا ثِقَالًۭا سُقْنَٰهُ لِبَلَدٍۢ مَّيِّتٍۢ فَأَنزَلْنَا بِهِ ٱلْمَآءَ فَأَخْرَجْنَا بِهِۦ مِن كُلِّ ٱلثَّمَرَٰتِ ۚ كَذَٰلِكَ نُخْرِجُ ٱلْمَوْتَىٰ لَعَلَّكُمْ تَذَكَّرُونَ","fa":"و اوست که بادها را پیشاپیشِ [بارانِ] رحمتش به عنوان مژده دهنده می فرستد تا هنگامی که ابرهای سنگین بار را بردارند، آن را به سوی سرزمینی مرده می رانیم، پس به وسیله آن باران نازل می کنیم و به وسیله باران از هر نوع میوه [از زمین] بیرون می آوریم [و] مردگان را نیز [در روز قیامت] این گونه [از لابلای گورها] بیرون می آوریم، [باد، ابر، باران، زمین، روییدن گیاهان و انواع میوه ها را مثل زدیم] تا متذکّر و یادآور [اراده و قدرت بی نهایت خدا] شوید."},{"s":"سُورَةُ الأَعۡرَافِ","n":67,"ar":"قَالَ يَٰقَوْمِ لَيْسَ بِى سَفَاهَةٌۭ وَلَٰكِنِّى رَسُولٌۭ مِّن رَّبِّ ٱلْعَٰلَمِينَ","fa":"گفت: ای قوم من! در من هیچ سبک مغزی و نادانی نیست، بلکه من فرستاده ای از سوی پروردگار جهانیانم."},{"s":"سُورَةُ الأَعۡرَافِ","n":77,"ar":"فَعَقَرُوا۟ ٱلنَّاقَةَ وَعَتَوْا۟ عَنْ أَمْرِ رَبِّهِمْ وَقَالُوا۟ يَٰصَٰلِحُ ٱئْتِنَا بِمَا تَعِدُنَآ إِن كُنتَ مِنَ ٱلْمُرْسَلِينَ","fa":"پس آن ماده شتر را پی کردند، و از فرمان پروردگارشان سرپیچی نمودند و به صالح گفتند: اگر از پیامبران هستی عذابی که همواره به ما وعده می دهی، بیاور."},{"s":"سُورَةُ الأَعۡرَافِ","n":87,"ar":"وَإِن كَانَ طَآئِفَةٌۭ مِّنكُمْ ءَامَنُوا۟ بِٱلَّذِىٓ أُرْسِلْتُ بِهِۦ وَطَآئِفَةٌۭ لَّمْ يُؤْمِنُوا۟ فَٱصْبِرُوا۟ حَتَّىٰ يَحْكُمَ ٱللَّهُ بَيْنَنَا ۚ وَهُوَ خَيْرُ ٱلْحَٰكِمِينَ","fa":"و اگر گروهی از شما به آیینی که من به آن فرستاده شده ام، ایمان آوردند و گروهی ایمان نیاوردند، پس [شما مؤمنان] شکیبایی ورزید تا خدا میان ما داوری کند، که او بهترین داوران است."},{"s":"سُورَةُ الأَعۡرَافِ","n":97,"ar":"أَفَأَمِنَ أَهْلُ ٱلْقُرَىٰٓ أَن يَأْتِيَهُم بَأْسُنَا بَيَٰتًۭا وَهُمْ نَآئِمُونَ","fa":"آیا اهل شهرها ایمنند از اینکه هنگام شب، عذاب ما در حالی که خوابند بر آنان درآید؟!"},{"s":"سُورَةُ الأَعۡرَافِ","n":107,"ar":"فَأَلْقَىٰ عَصَاهُ فَإِذَا هِىَ ثُعْبَانٌۭ مُّبِينٌۭ","fa":"پس موسی عصایش را انداخت، پس به ناگاه اژدهایی آشکار شد."},{"s":"سُورَةُ الأَعۡرَافِ","n":117,"ar":"۞ وَأَوْحَيْنَآ إِلَىٰ مُوسَىٰٓ أَنْ أَلْقِ عَصَاكَ ۖ فَإِذَا هِىَ تَلْقَفُ مَا يَأْفِكُونَ","fa":"و به موسی وحی کردیم: عصایت را بینداز. ناگهان آنچه را جادوگران به دروغ بافته بودند، به سرعت بلعید!"},{"s":"سُورَةُ الأَعۡرَافِ","n":127,"ar":"وَقَالَ ٱلْمَلَأُ مِن قَوْمِ فِرْعَوْنَ أَتَذَرُ مُوسَىٰ وَقَوْمَهُۥ لِيُفْسِدُوا۟ فِى ٱلْأَرْضِ وَيَذَرَكَ وَءَالِهَتَكَ ۚ قَالَ سَنُقَتِّلُ أَبْنَآءَهُمْ وَنَسْتَحْىِۦ نِسَآءَهُمْ وَإِنَّا فَوْقَهُمْ قَٰهِرُونَ","fa":"اشراف و سران قوم فرعون گفتند: آیا موسی و قومش را رها می کنی تا در این سرزمین فساد و تباهی کنند و تو و معبودهایت را واگذارند؟ گفت: به زودی پسرانشان را به صورتی وسیع و گسترده به قتل می رسانیم و زنانشان را زنده می گذاریم و ما بر آنان چیره و مُسلّطیم."},{"s":"سُورَةُ الأَعۡرَافِ","n":137,"ar":"وَأَوْرَثْنَا ٱلْقَوْمَ ٱلَّذِينَ كَانُوا۟ يُسْتَضْعَفُونَ مَشَٰرِقَ ٱلْأَرْضِ وَمَغَٰرِبَهَا ٱلَّتِى بَٰرَكْنَا فِيهَا ۖ وَتَمَّتْ كَلِمَتُ رَبِّكَ ٱلْحُسْنَىٰ عَلَىٰ بَنِىٓ إِسْرَٰٓءِيلَ بِمَا صَبَرُوا۟ ۖ وَدَمَّرْنَا مَا كَانَ يَصْنَعُ فِرْعَوْنُ وَقَوْمُهُۥ وَمَا كَانُوا۟ يَعْرِشُونَ","fa":"و به آن گروهی که همواره ناتوان و زبونشان شمرده بودند، نواحی شرقی و غربی آن سرزمین را که در آن [از جهت فراوانی نعمت، ارزانی و حاصل خیزی] برکت قرار داده بودیم، بخشیدیم؛ و وعده نیکوتر و زیباتر پروردگارت بر بنی اسرائیل به [پاداش] صبری که [بر سختی ها و بلاها] کردند تحقّق یافت، و آنچه را که همواره فرعون وفرعونیان [از کاخ و قصرهای مجلّل] و سایه بان های خوش نشین می افراشتند، نابود کردیم."},{"s":"سُورَةُ الأَعۡرَافِ","n":147,"ar":"وَٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَٰتِنَا وَلِقَآءِ ٱلْءَاخِرَةِ حَبِطَتْ أَعْمَٰلُهُمْ ۚ هَلْ يُجْزَوْنَ إِلَّا مَا كَانُوا۟ يَعْمَلُونَ","fa":"و آنان که آیات ما و دیدار آخرت را تکذیب کردند، اعمالشان تباه و بی اثر شد. آیا جز به آنچه همواره [بر طبق کفر و انحرافشان] انجام می دادند، کیفر داده می شوند؟!"},{"s":"سُورَةُ الأَعۡرَافِ","n":157,"ar":"ٱلَّذِينَ يَتَّبِعُونَ ٱلرَّسُولَ ٱلنَّبِىَّ ٱلْأُمِّىَّ ٱلَّذِى يَجِدُونَهُۥ مَكْتُوبًا عِندَهُمْ فِى ٱلتَّوْرَىٰةِ وَٱلْإِنجِيلِ يَأْمُرُهُم بِٱلْمَعْرُوفِ وَيَنْهَىٰهُمْ عَنِ ٱلْمُنكَرِ وَيُحِلُّ لَهُمُ ٱلطَّيِّبَٰتِ وَيُحَرِّمُ عَلَيْهِمُ ٱلْخَبَٰٓئِثَ وَيَضَعُ عَنْهُمْ إِصْرَهُمْ وَٱلْأَغْلَٰلَ ٱلَّتِى كَانَتْ عَلَيْهِمْ ۚ فَٱلَّذِينَ ءَامَنُوا۟ بِهِۦ وَعَزَّرُوهُ وَنَصَرُوهُ وَٱتَّبَعُوا۟ ٱلنُّورَ ٱلَّذِىٓ أُنزِلَ مَعَهُۥٓ ۙ أُو۟لَٰٓئِكَ هُمُ ٱلْمُفْلِحُونَ","fa":"همان کسانی که از این رسول و پیامبر «ناخوانده درس» که او را نزد خود [با همه نشانه ها و اوصافش] در تورات وانجیل نگاشته می یابند، پیروی می کنند؛ پیامبری که آنان را به کارهای شایسته فرمان می دهد، و از اعمال زشت بازمی دارد، و پاکیزه ها را بر آنان حلال می نماید، و ناپاک ها را بر آنان حرام می کند، و بارهای تکالیف سنگین و زنجیره ها [یِ جهل، بی خبری و بدعت را] که بر دوش عقل وجان آنان است برمی دارد؛ پس کسانی که به او ایمان آوردند و او را [در برابر دشمنان] حمایت کردند و یاریش دادند و از نوری که بر او نازل شده پیروی نمودند، فقط آنان رستگارانند."},{"s":"سُورَةُ الأَعۡرَافِ","n":167,"ar":"وَإِذْ تَأَذَّنَ رَبُّكَ لَيَبْعَثَنَّ عَلَيْهِمْ إِلَىٰ يَوْمِ ٱلْقِيَٰمَةِ مَن يَسُومُهُمْ سُوٓءَ ٱلْعَذَابِ ۗ إِنَّ رَبَّكَ لَسَرِيعُ ٱلْعِقَابِ ۖ وَإِنَّهُۥ لَغَفُورٌۭ رَّحِيمٌۭ","fa":"و [یاد کن] هنگامی را که پروردگارت اعلام کرد که بی تردید تا روز قیامت کسانی را بر ضد یهودیان [متجاوز و سرکش] برانگیزد و مسلط کند که همواره عذابی سخت به آنان بچشاند؛ مسلماً پروردگارت زود کیفر و یقیناً [نسبت به تائبان] بسیار آمرزنده و مهربان است."},{"s":"سُورَةُ الأَعۡرَافِ","n":177,"ar":"سَآءَ مَثَلًا ٱلْقَوْمُ ٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَٰتِنَا وَأَنفُسَهُمْ كَانُوا۟ يَظْلِمُونَ","fa":"بد است داستان گروهی که آیات ما را تکذیب کردند وهمواره به خود ستم روا می داشتند."},{"s":"سُورَةُ الأَعۡرَافِ","n":187,"ar":"يَسْـَٔلُونَكَ عَنِ ٱلسَّاعَةِ أَيَّانَ مُرْسَىٰهَا ۖ قُلْ إِنَّمَا عِلْمُهَا عِندَ رَبِّى ۖ لَا يُجَلِّيهَا لِوَقْتِهَآ إِلَّا هُوَ ۚ ثَقُلَتْ فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ ۚ لَا تَأْتِيكُمْ إِلَّا بَغْتَةًۭ ۗ يَسْـَٔلُونَكَ كَأَنَّكَ حَفِىٌّ عَنْهَا ۖ قُلْ إِنَّمَا عِلْمُهَا عِندَ ٱللَّهِ وَلَٰكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يَعْلَمُونَ","fa":"همواره درباره قیامت از تو می پرسند که وقوع آن چه وقت است؟ بگو: دانش آن فقط نزد پروردگار من است، غیر او آن را در وقت معینش آشکار نمی کند؛ [تحملِ این حادثه عظیم و هولناک،] بر آسمان ها و زمین سنگین و دشوار است، جز به طور ناگهانی بر شما نمی آید. آن گونه از تو می پرسند که گویا تو از وقت وقوعش به شدت کنجکاوی کرده ای [و کاملاً از آن آگاهی]، بگو: دانش آن فقط نزد خداست، ولی بیشتر مردم نمی دانند [که این دانش، مخصوص به خدا و فقط در اختیار اوست.]"},{"s":"سُورَةُ الأَعۡرَافِ","n":197,"ar":"وَٱلَّذِينَ تَدْعُونَ مِن دُونِهِۦ لَا يَسْتَطِيعُونَ نَصْرَكُمْ وَلَآ أَنفُسَهُمْ يَنصُرُونَ","fa":"و کسانی را که به جای خدا می خوانید، نه می توانند شما را یاری دهند و نه خود را یاری رسانند."},{"s":"سُورَةُ الأَنفَالِ","n":1,"ar":"بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ يَسْـَٔلُونَكَ عَنِ ٱلْأَنفَالِ ۖ قُلِ ٱلْأَنفَالُ لِلَّهِ وَٱلرَّسُولِ ۖ فَٱتَّقُوا۟ ٱللَّهَ وَأَصْلِحُوا۟ ذَاتَ بَيْنِكُمْ ۖ وَأَطِيعُوا۟ ٱللَّهَ وَرَسُولَهُۥٓ إِن كُنتُم مُّؤْمِنِينَ","fa":"از تو درباره انفال] یعنی غنایم جنگی و هر گونه مالی که مالک معینی ندارد [می پرسند، [که مالک آنها کیست و چگونه باید تقسیم شود؟] بگو: [مالکیّتِ حقیقیِ] انفال ویژه خدا وپیامبر است، پس اگر مؤمن هستید [نسبت به انفال] از خدا پروا کنید و [اختلاف و نزاع] بین خود را اصلاح نمایید، و از خدا و پیامبرش اطاعت کنید."},{"s":"سُورَةُ الأَنفَالِ","n":11,"ar":"إِذْ يُغَشِّيكُمُ ٱلنُّعَاسَ أَمَنَةًۭ مِّنْهُ وَيُنَزِّلُ عَلَيْكُم مِّنَ ٱلسَّمَآءِ مَآءًۭ لِّيُطَهِّرَكُم بِهِۦ وَيُذْهِبَ عَنكُمْ رِجْزَ ٱلشَّيْطَٰنِ وَلِيَرْبِطَ عَلَىٰ قُلُوبِكُمْ وَيُثَبِّتَ بِهِ ٱلْأَقْدَامَ","fa":"و [یاد کنید] هنگامی را که به سبب امنیت و آرامشی که ازسوی خدا یافتید، خواب سبکی را به همه شما مسلط کرد و برایتان آبی از آسمان نازل کرد تا شما را به وسیله آن [از آلودگی ها] پاک کند، و وسوسه شیطان را [که از بدترین کثافات است] از شما برطرف نماید، و دل هایتان را استحکام دهد، و گام هایتان را به آن استوار و پا برجا کند."},{"s":"سُورَةُ الأَنفَالِ","n":21,"ar":"وَلَا تَكُونُوا۟ كَٱلَّذِينَ قَالُوا۟ سَمِعْنَا وَهُمْ لَا يَسْمَعُونَ","fa":"و مانند کسانی نباشید که [از روی تظاهر] گفتند: شنیدیم در حالی که [از روی حقیقت] نمی شنوند."},{"s":"سُورَةُ الأَنفَالِ","n":31,"ar":"وَإِذَا تُتْلَىٰ عَلَيْهِمْ ءَايَٰتُنَا قَالُوا۟ قَدْ سَمِعْنَا لَوْ نَشَآءُ لَقُلْنَا مِثْلَ هَٰذَآ ۙ إِنْ هَٰذَآ إِلَّآ أَسَٰطِيرُ ٱلْأَوَّلِينَ","fa":"و هنگامی که آیات ما را بر آنان می خوانند، می گویند: البته شنیدیم [ولی این آیات، مطلب فوق العاده ای نیست] ما هم اگر بخواهیم مانند آن را می گوییم، این آیات جز افسانه پیشینیان نیست!!"},{"s":"سُورَةُ الأَنفَالِ","n":41,"ar":"۞ وَٱعْلَمُوٓا۟ أَنَّمَا غَنِمْتُم مِّن شَىْءٍۢ فَأَنَّ لِلَّهِ خُمُسَهُۥ وَلِلرَّسُولِ وَلِذِى ٱلْقُرْبَىٰ وَٱلْيَتَٰمَىٰ وَٱلْمَسَٰكِينِ وَٱبْنِ ٱلسَّبِيلِ إِن كُنتُمْ ءَامَنتُم بِٱللَّهِ وَمَآ أَنزَلْنَا عَلَىٰ عَبْدِنَا يَوْمَ ٱلْفُرْقَانِ يَوْمَ ٱلْتَقَى ٱلْجَمْعَانِ ۗ وَٱللَّهُ عَلَىٰ كُلِّ شَىْءٍۢ قَدِيرٌ","fa":"و بدانید هر چیزی را که [از راه جهاد یا کسب یا هر طریق مشروعی] به عنوان غنیمت و فایده به دست آوردید [کم باشد یا زیاد] یک پنجم آن برای خدا و رسول خدا (صلی الله علیه وآله) و خویشان پیامبر، و یتیمان و مسکینان و در راه ماندگان است، اگر به خدا و آنچه بر بنده اش روز جدا کننده حق از باطل، روز رویارویی دو گروه [مؤمن وکافر در جنگ بدر] نازل کردیم، ایمان آورده اید [پس آن را به عنوان حقّی واجب به خدا و رسول و دیگر نامبردگان بپردازید]؛ و خدا بر هرکاری تواناست."},{"s":"سُورَةُ الأَنفَالِ","n":51,"ar":"ذَٰلِكَ بِمَا قَدَّمَتْ أَيْدِيكُمْ وَأَنَّ ٱللَّهَ لَيْسَ بِظَلَّٰمٍۢ لِّلْعَبِيدِ","fa":"این به سبب گناهانی است که مرتکب شده اند و گرنه خدا نسبت به بندگانش [حتی به کمترین چیزی از ستم] ستمکار نیست."},{"s":"سُورَةُ الأَنفَالِ","n":61,"ar":"۞ وَإِن جَنَحُوا۟ لِلسَّلْمِ فَٱجْنَحْ لَهَا وَتَوَكَّلْ عَلَى ٱللَّهِ ۚ إِنَّهُۥ هُوَ ٱلسَّمِيعُ ٱلْعَلِيمُ","fa":"و اگر دشمنان به صلح گرایند، تو هم به صلح گرای، و بر خدا توکل کن، که یقیناً او شنوا و داناست."},{"s":"سُورَةُ الأَنفَالِ","n":71,"ar":"وَإِن يُرِيدُوا۟ خِيَانَتَكَ فَقَدْ خَانُوا۟ ٱللَّهَ مِن قَبْلُ فَأَمْكَنَ مِنْهُمْ ۗ وَٱللَّهُ عَلِيمٌ حَكِيمٌ","fa":"و اگر اسیران آزاد شده بخواهند [پس از آزاد شدنشان] به تو خیانت ورزند، [کار جدید و تازه ای نیست] آنان پیش از این هم به خدا خیانت ورزیدند، پس او تو را بر آنان مسلط ساخت؛ و خدا دانا و حکیم است."},{"s":"سُورَةُ التَّوۡبَةِ","n":6,"ar":"وَإِنْ أَحَدٌۭ مِّنَ ٱلْمُشْرِكِينَ ٱسْتَجَارَكَ فَأَجِرْهُ حَتَّىٰ يَسْمَعَ كَلَٰمَ ٱللَّهِ ثُمَّ أَبْلِغْهُ مَأْمَنَهُۥ ۚ ذَٰلِكَ بِأَنَّهُمْ قَوْمٌۭ لَّا يَعْلَمُونَ","fa":"و اگر یکی از مشرکان از تو پناه خواست، پس پناهش بده تا سخن خدا را بشنود، آن گاه او را به جایگاه امنش برسان؛ این به سبب آن است که آنان گروهی هستند که [حقایق را] نمی دانند [باشد که در پناه تو و شنیدن سخن حق مسلمان شوند.]"},{"s":"سُورَةُ التَّوۡبَةِ","n":16,"ar":"أَمْ حَسِبْتُمْ أَن تُتْرَكُوا۟ وَلَمَّا يَعْلَمِ ٱللَّهُ ٱلَّذِينَ جَٰهَدُوا۟ مِنكُمْ وَلَمْ يَتَّخِذُوا۟ مِن دُونِ ٱللَّهِ وَلَا رَسُولِهِۦ وَلَا ٱلْمُؤْمِنِينَ وَلِيجَةًۭ ۚ وَٱللَّهُ خَبِيرٌۢ بِمَا تَعْمَلُونَ","fa":"آیا گمان کرده اید که شما را به خود واگذارند [و به بوته آزمایش نیازمایند] در حالی که هنوز کسانی از شما را که جهاد کردند و غیر خدا و پیامبرش و مؤمنان را محرم اسرار خود نگرفتند، از دیگران معلوم و مشخص نکرده است [یقیناً باید آزمایش شوید تا مؤمن از غیر مؤمن معلوم و مشخص شود]؛ و خدا به آنچه انجام می دهید، آگاه است."},{"s":"سُورَةُ التَّوۡبَةِ","n":26,"ar":"ثُمَّ أَنزَلَ ٱللَّهُ سَكِينَتَهُۥ عَلَىٰ رَسُولِهِۦ وَعَلَى ٱلْمُؤْمِنِينَ وَأَنزَلَ جُنُودًۭا لَّمْ تَرَوْهَا وَعَذَّبَ ٱلَّذِينَ كَفَرُوا۟ ۚ وَذَٰلِكَ جَزَآءُ ٱلْكَٰفِرِينَ","fa":"آن گاه خدا آرامش خود را [که حالت طمأنینه قلبی است] بر پیامبرش و مؤمنان نازل کرد، و لشکریانی که آنان را نمی دیدید [برای یاری مؤمنان] فرود آورد، و کسانی را که کفر می ورزیدند، به عذاب سختی مجازات کرد؛ و این است کیفر کفرپیشگان."},{"s":"سُورَةُ التَّوۡبَةِ","n":36,"ar":"إِنَّ عِدَّةَ ٱلشُّهُورِ عِندَ ٱللَّهِ ٱثْنَا عَشَرَ شَهْرًۭا فِى كِتَٰبِ ٱللَّهِ يَوْمَ خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ مِنْهَآ أَرْبَعَةٌ حُرُمٌۭ ۚ ذَٰلِكَ ٱلدِّينُ ٱلْقَيِّمُ ۚ فَلَا تَظْلِمُوا۟ فِيهِنَّ أَنفُسَكُمْ ۚ وَقَٰتِلُوا۟ ٱلْمُشْرِكِينَ كَآفَّةًۭ كَمَا يُقَٰتِلُونَكُمْ كَآفَّةًۭ ۚ وَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ مَعَ ٱلْمُتَّقِينَ","fa":"یقیناً شماره ماه ها در پیشگاه خدا از روزی که آسمان ها و زمین را آفریده در کتاب [علم] خدا دوازده ماه است؛ از آنها چهار ماهش ماه حرام است؛ این است حساب استوار و پایدار؛ پس در این چهار ماه [با جنگ و فتنه و خونریزی] بر خود ستم روا مدارید و با همه مشرکان همان گونه که آنان با همه شما می جنگند، بجنگید و بدانید خدا با پرهیزکاران است."},{"s":"سُورَةُ التَّوۡبَةِ","n":46,"ar":"۞ وَلَوْ أَرَادُوا۟ ٱلْخُرُوجَ لَأَعَدُّوا۟ لَهُۥ عُدَّةًۭ وَلَٰكِن كَرِهَ ٱللَّهُ ٱنۢبِعَاثَهُمْ فَثَبَّطَهُمْ وَقِيلَ ٱقْعُدُوا۟ مَعَ ٱلْقَٰعِدِينَ","fa":"و اگر برای بیرون رفتن [به سوی میدان نبرد] تصمیم جدّی داشتند، مسلماً برای آن ساز و برگ آماده می کردند، ولی خدا [به سبب سستی اراده و نفاقشان] برانگیختن آنان را [به سوی میدان نبرد] خوش نداشت، پس آنان را از حرکت بازداشت، و [انگار به آنان] گفته شد: با نشستگان [در خانه ها که به علتی معذور از جنگند] بنشینید."},{"s":"سُورَةُ التَّوۡبَةِ","n":56,"ar":"وَيَحْلِفُونَ بِٱللَّهِ إِنَّهُمْ لَمِنكُمْ وَمَا هُم مِّنكُمْ وَلَٰكِنَّهُمْ قَوْمٌۭ يَفْرَقُونَ","fa":"[با کمال بی شرمی] به خدا سوگند یاد می کنند که حتماً از زمره شمایند؛ در صورتی که از شما نیستند، بلکه گروهی اند که از شما [به سبب ایمان استوارتان] در اضطراب و ترس به سر می برند."},{"s":"سُورَةُ التَّوۡبَةِ","n":66,"ar":"لَا تَعْتَذِرُوا۟ قَدْ كَفَرْتُم بَعْدَ إِيمَٰنِكُمْ ۚ إِن نَّعْفُ عَن طَآئِفَةٍۢ مِّنكُمْ نُعَذِّبْ طَآئِفَةًۢ بِأَنَّهُمْ كَانُوا۟ مُجْرِمِينَ","fa":"[بگو: نسبت به اعمال و گفتارتان] عذرخواهی نکنید که [عذرخواهی شما را پایه واساسی نیست] یقیناً شما پس از ایمانتان کافر شدید؛ اگر از گروهی از شما [که تابع و دنباله رو بودید] درگذریم، گروه دیگر را [که سردمداران برنامه های منافقانه بودند] به سبب آنکه همواره [در جامعه اسلامی] دست به جرم و خطا می زدند، قطعاً عذاب می کنیم."},{"s":"سُورَةُ التَّوۡبَةِ","n":76,"ar":"فَلَمَّآ ءَاتَىٰهُم مِّن فَضْلِهِۦ بَخِلُوا۟ بِهِۦ وَتَوَلَّوا۟ وَّهُم مُّعْرِضُونَ","fa":"هنگامی که خدا از فضل و احسانش به آنان عطا کرد نسبت به [هزینه کردن] آن [در راه خدا] بخل ورزیدند و اعراض کنان [از پیمانشان] روی گرداندند."},{"s":"سُورَةُ التَّوۡبَةِ","n":86,"ar":"وَإِذَآ أُنزِلَتْ سُورَةٌ أَنْ ءَامِنُوا۟ بِٱللَّهِ وَجَٰهِدُوا۟ مَعَ رَسُولِهِ ٱسْتَـْٔذَنَكَ أُو۟لُوا۟ ٱلطَّوْلِ مِنْهُمْ وَقَالُوا۟ ذَرْنَا نَكُن مَّعَ ٱلْقَٰعِدِينَ","fa":"و چون سوره ای نازل شود که: [در آن سوره از آنان خواسته اند] به خدا ایمان آورید و همراه پیامبرش جهاد کنید؛ ثروتمندان و قدرتمندان [منافق] از تو اجازه می خواهند [که در جهاد شرکت نکنند] و می گویند: بگذار که ما با خانه نشینان باشیم."},{"s":"سُورَةُ التَّوۡبَةِ","n":96,"ar":"يَحْلِفُونَ لَكُمْ لِتَرْضَوْا۟ عَنْهُمْ ۖ فَإِن تَرْضَوْا۟ عَنْهُمْ فَإِنَّ ٱللَّهَ لَا يَرْضَىٰ عَنِ ٱلْقَوْمِ ٱلْفَٰسِقِينَ","fa":"برای شما [در جهت معذور بودن خود] سوگند می خورند تا از آنان راضی شوید، اگر شما هم از آنان راضی شوید، یقیناً خدا از گروه فاسقان راضی نخواهد شد."},{"s":"سُورَةُ التَّوۡبَةِ","n":106,"ar":"وَءَاخَرُونَ مُرْجَوْنَ لِأَمْرِ ٱللَّهِ إِمَّا يُعَذِّبُهُمْ وَإِمَّا يَتُوبُ عَلَيْهِمْ ۗ وَٱللَّهُ عَلِيمٌ حَكِيمٌۭ","fa":"و گروهی دیگر کارشان موقوف به مشیّت خداست، یا آنان را عذاب می کند یا توبه آنان را می پذیرد؛ و خدا دانا و حکیم است."},{"s":"سُورَةُ التَّوۡبَةِ","n":116,"ar":"إِنَّ ٱللَّهَ لَهُۥ مُلْكُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ ۖ يُحْىِۦ وَيُمِيتُ ۚ وَمَا لَكُم مِّن دُونِ ٱللَّهِ مِن وَلِىٍّۢ وَلَا نَصِيرٍۢ","fa":"یقیناً خداست که مالکیّت و فرمانروایی آسمان ها و زمین در سیطره اوست؛ زنده می کند و می میراند؛ و شما را هیچ سرپرست و یاری جز خدا نیست."},{"s":"سُورَةُ التَّوۡبَةِ","n":126,"ar":"أَوَلَا يَرَوْنَ أَنَّهُمْ يُفْتَنُونَ فِى كُلِّ عَامٍۢ مَّرَّةً أَوْ مَرَّتَيْنِ ثُمَّ لَا يَتُوبُونَ وَلَا هُمْ يَذَّكَّرُونَ","fa":"آیا نمی بینند که در هر سال یک بار یا دو بار [به وسیله جهاد یا پیش آمدهای دیگر] آزمایش می شوند، ولی نه توبه می کنند ونه پند می گیرند."},{"s":"سُورَةُ يُونُسَ","n":7,"ar":"إِنَّ ٱلَّذِينَ لَا يَرْجُونَ لِقَآءَنَا وَرَضُوا۟ بِٱلْحَيَوٰةِ ٱلدُّنْيَا وَٱطْمَأَنُّوا۟ بِهَا وَٱلَّذِينَ هُمْ عَنْ ءَايَٰتِنَا غَٰفِلُونَ","fa":"مسلماً کسانی که دیدارِ [قیامتِ] ما [و محاسبه شدن اعمالشان] را امید ندارند و به زندگی دنیا خشنود شده اند و به آن آرام یافته اند و آنانکه از آیات ما بی خبرند."},{"s":"سُورَةُ يُونُسَ","n":17,"ar":"فَمَنْ أَظْلَمُ مِمَّنِ ٱفْتَرَىٰ عَلَى ٱللَّهِ كَذِبًا أَوْ كَذَّبَ بِـَٔايَٰتِهِۦٓ ۚ إِنَّهُۥ لَا يُفْلِحُ ٱلْمُجْرِمُونَ","fa":"پس ستمکارتر از کسی که بر خدا دروغ بندد یا آیاتش را تکذیب کند، کیست؟ یقیناً گنهکاران، رستگار نخواهند شد."},{"s":"سُورَةُ يُونُسَ","n":27,"ar":"وَٱلَّذِينَ كَسَبُوا۟ ٱلسَّيِّـَٔاتِ جَزَآءُ سَيِّئَةٍۭ بِمِثْلِهَا وَتَرْهَقُهُمْ ذِلَّةٌۭ ۖ مَّا لَهُم مِّنَ ٱللَّهِ مِنْ عَاصِمٍۢ ۖ كَأَنَّمَآ أُغْشِيَتْ وُجُوهُهُمْ قِطَعًۭا مِّنَ ٱلَّيْلِ مُظْلِمًا ۚ أُو۟لَٰٓئِكَ أَصْحَٰبُ ٱلنَّارِ ۖ هُمْ فِيهَا خَٰلِدُونَ","fa":"و کسانی که مرتکب بدی ها شدند، کیفر هر بدی مانند همان بدی است و خواری آنان را فرامی گیرد، برای آنان از [خشم و عذاب] خدا هیچ حافظ و نگه دارنده ای نخواهد بود؛ گویی چهره هایشان با پاره هایی از شب تاریک پوشیده شده؛ آنان اهل آتش اند و در آن جاودانه اند."},{"s":"سُورَةُ يُونُسَ","n":37,"ar":"وَمَا كَانَ هَٰذَا ٱلْقُرْءَانُ أَن يُفْتَرَىٰ مِن دُونِ ٱللَّهِ وَلَٰكِن تَصْدِيقَ ٱلَّذِى بَيْنَ يَدَيْهِ وَتَفْصِيلَ ٱلْكِتَٰبِ لَا رَيْبَ فِيهِ مِن رَّبِّ ٱلْعَٰلَمِينَ","fa":"و این قرآن را نسزد که دروغی ساختگی از سوی غیر خدا باشد، بلکه [با آیات محکم و استوارش] تصدیق کننده کتاب های پیش از خود و شرح و توضیحی بر هر کتاب [آسمانی] است، در آن هیچ تردیدی نیست که از سوی پروردگار جهانیان است."},{"s":"سُورَةُ يُونُسَ","n":47,"ar":"وَلِكُلِّ أُمَّةٍۢ رَّسُولٌۭ ۖ فَإِذَا جَآءَ رَسُولُهُمْ قُضِىَ بَيْنَهُم بِٱلْقِسْطِ وَهُمْ لَا يُظْلَمُونَ","fa":"و برای هر امتی پیامبری است؛ پس هنگامی که پیامبرشان [در قیامت] به سویشان آید، در میانشان به عدالت وانصاف داوری شود و مورد ستم قرار نخواهند گرفت."},{"s":"سُورَةُ يُونُسَ","n":57,"ar":"يَٰٓأَيُّهَا ٱلنَّاسُ قَدْ جَآءَتْكُم مَّوْعِظَةٌۭ مِّن رَّبِّكُمْ وَشِفَآءٌۭ لِّمَا فِى ٱلصُّدُورِ وَهُدًۭى وَرَحْمَةٌۭ لِّلْمُؤْمِنِينَ","fa":"ای مردم! یقیناً از سوی پروردگارتان برای شما پند وموعظه ای آمده، و شفاست برای آنچه [ازبیماری های اعتقادی و اخلاقی] در سینه هاست، و سراسر هدایت و رحمتی است برای مؤمنان."},{"s":"سُورَةُ يُونُسَ","n":67,"ar":"هُوَ ٱلَّذِى جَعَلَ لَكُمُ ٱلَّيْلَ لِتَسْكُنُوا۟ فِيهِ وَٱلنَّهَارَ مُبْصِرًا ۚ إِنَّ فِى ذَٰلِكَ لَءَايَٰتٍۢ لِّقَوْمٍۢ يَسْمَعُونَ","fa":"اوست کسی که شبِ [تاریک] را برای شما پدید آورد تا در آن بیارامید، و روز را نور افشان [قرار داد تا در آن به کار و کوشش بپردازید]؛ یقیناً در این امور برای گروهی که حقایق را بشنوند، نشانه هایی [از توحید و قدرت و ربوبیّت خدا] ست."},{"s":"سُورَةُ يُونُسَ","n":77,"ar":"قَالَ مُوسَىٰٓ أَتَقُولُونَ لِلْحَقِّ لَمَّا جَآءَكُمْ ۖ أَسِحْرٌ هَٰذَا وَلَا يُفْلِحُ ٱلسَّٰحِرُونَ","fa":"موسی گفت: آیا درباره حق هنگامی که به سویتان آمد، می گویید: آیا این جادوست؟ [نه، این جادو نیست، اگر جادو بود پیروزی نداشت] زیرا جادوگران پیروز نمی شوند."},{"s":"سُورَةُ يُونُسَ","n":87,"ar":"وَأَوْحَيْنَآ إِلَىٰ مُوسَىٰ وَأَخِيهِ أَن تَبَوَّءَا لِقَوْمِكُمَا بِمِصْرَ بُيُوتًۭا وَٱجْعَلُوا۟ بُيُوتَكُمْ قِبْلَةًۭ وَأَقِيمُوا۟ ٱلصَّلَوٰةَ ۗ وَبَشِّرِ ٱلْمُؤْمِنِينَ","fa":"و به موسی و برادرش وحی کردیم که خانه هایی در سرزمین مصر برای قوم خود فراهم آورید، و خانه هایتان را روبروی هم قرار دهید، و نماز را برپا دارید، و مؤمنان را [به رهایی از چنگال فرعونیان] مژده ده."},{"s":"سُورَةُ يُونُسَ","n":97,"ar":"وَلَوْ جَآءَتْهُمْ كُلُّ ءَايَةٍ حَتَّىٰ يَرَوُا۟ ٱلْعَذَابَ ٱلْأَلِيمَ","fa":"گرچه همه نشانه ها و معجزه ها برای آنان بیاید تا آن زمان که عذاب دردناک را ببینند [که آن هنگام ایمان آوردنشان هیچ سودی نخواهد داشت.]"},{"s":"سُورَةُ يُونُسَ","n":107,"ar":"وَإِن يَمْسَسْكَ ٱللَّهُ بِضُرٍّۢ فَلَا كَاشِفَ لَهُۥٓ إِلَّا هُوَ ۖ وَإِن يُرِدْكَ بِخَيْرٍۢ فَلَا رَآدَّ لِفَضْلِهِۦ ۚ يُصِيبُ بِهِۦ مَن يَشَآءُ مِنْ عِبَادِهِۦ ۚ وَهُوَ ٱلْغَفُورُ ٱلرَّحِيمُ","fa":"و اگر خدا گزند و آسیبی به تو رساند، آن را جز او برطرف کننده ای نیست، و اگر برای تو خیری خواهد فضل و احسانش را دفع کننده ای نیست؛ خیرش را به هر کس از بندگانش بخواهد می رساند و او بسیار آمرزنده و مهربان است."},{"s":"سُورَةُ هُودٍ","n":8,"ar":"وَلَئِنْ أَخَّرْنَا عَنْهُمُ ٱلْعَذَابَ إِلَىٰٓ أُمَّةٍۢ مَّعْدُودَةٍۢ لَّيَقُولُنَّ مَا يَحْبِسُهُۥٓ ۗ أَلَا يَوْمَ يَأْتِيهِمْ لَيْسَ مَصْرُوفًا عَنْهُمْ وَحَاقَ بِهِم مَّا كَانُوا۟ بِهِۦ يَسْتَهْزِءُونَ","fa":"و اگر عذاب را از آنان تا مدتی اندک به تأخیر اندازیم، مسلماً [از روی استهزا] خواهند گفت: چه عاملی آن را [از آمدن] باز می دارد؟! آگاه باشید! روزی که عذاب به آنان رسد، از آنان بازگشتنی و بازداشتنی نیست و عذابی را که همواره مسخره می کردند، آنان را فراخواهد گرفت."},{"s":"سُورَةُ هُودٍ","n":18,"ar":"وَمَنْ أَظْلَمُ مِمَّنِ ٱفْتَرَىٰ عَلَى ٱللَّهِ كَذِبًا ۚ أُو۟لَٰٓئِكَ يُعْرَضُونَ عَلَىٰ رَبِّهِمْ وَيَقُولُ ٱلْأَشْهَٰدُ هَٰٓؤُلَآءِ ٱلَّذِينَ كَذَبُوا۟ عَلَىٰ رَبِّهِمْ ۚ أَلَا لَعْنَةُ ٱللَّهِ عَلَى ٱلظَّٰلِمِينَ","fa":"و ستمکارتر از کسانی که به خدا دروغ بندند چه کسی است؟ اینان [در قیامت] بر پروردگارشان عرضه خواهند شد، وگواهان [اعمال] می گویند: اینان کسانی هستند که بر پروردگارشان دروغ بستند؛ آگاه باشید! لعنت خدا بر ستمکاران باد."},{"s":"سُورَةُ هُودٍ","n":28,"ar":"قَالَ يَٰقَوْمِ أَرَءَيْتُمْ إِن كُنتُ عَلَىٰ بَيِّنَةٍۢ مِّن رَّبِّى وَءَاتَىٰنِى رَحْمَةًۭ مِّنْ عِندِهِۦ فَعُمِّيَتْ عَلَيْكُمْ أَنُلْزِمُكُمُوهَا وَأَنتُمْ لَهَا كَٰرِهُونَ","fa":"نوح گفت: ای قوم من! مرا خبر دهید: اگر من بر دلیل روشنی از سوی پروردگارم متکی باشم و مرا از نزد خود رحمتی عطا کرده باشد که بر شما مخفی مانده [باز هم نبوّت مرا تکذیب می کنید؟] آیا [در صورتی که اجباری در پذیرش دین نیست] می توان شما را به پذیرش آن دلیل روشن در حالی که آن را خوش ندارید، وادار کنیم؟"},{"s":"سُورَةُ هُودٍ","n":38,"ar":"وَيَصْنَعُ ٱلْفُلْكَ وَكُلَّمَا مَرَّ عَلَيْهِ مَلَأٌۭ مِّن قَوْمِهِۦ سَخِرُوا۟ مِنْهُ ۚ قَالَ إِن تَسْخَرُوا۟ مِنَّا فَإِنَّا نَسْخَرُ مِنكُمْ كَمَا تَسْخَرُونَ","fa":"و [نوح] کشتی را می ساخت و هرگاه گروهی از [اشراف و سرانِ] قومش بر او عبور می کردند، او را به مسخره می گرفتند. گفت: اگر شما ما را مسخره می کنید، مسلماً ما هم شما را [به هنگام پدید آمدن توفان] همان گونه که ما را مسخره می کنید، مسخره خواهیم کرد."},{"s":"سُورَةُ هُودٍ","n":48,"ar":"قِيلَ يَٰنُوحُ ٱهْبِطْ بِسَلَٰمٍۢ مِّنَّا وَبَرَكَٰتٍ عَلَيْكَ وَعَلَىٰٓ أُمَمٍۢ مِّمَّن مَّعَكَ ۚ وَأُمَمٌۭ سَنُمَتِّعُهُمْ ثُمَّ يَمَسُّهُم مِّنَّا عَذَابٌ أَلِيمٌۭ","fa":"گفته شد: ای نوح! با سلام و برکاتی از سوی ما بر تو و امت هایی که با تواند [از کشتی] فرود آی و امت هایی [از نسل همراهانت به وجود می آیند] که به زودی آنان را [از نعمت های خود] برخوردار می کنیم، سپس آنان را از سوی ما [به سبب کفران نعمت] عذابی دردناک خواهد رسید."},{"s":"سُورَةُ هُودٍ","n":58,"ar":"وَلَمَّا جَآءَ أَمْرُنَا نَجَّيْنَا هُودًۭا وَٱلَّذِينَ ءَامَنُوا۟ مَعَهُۥ بِرَحْمَةٍۢ مِّنَّا وَنَجَّيْنَٰهُم مِّنْ عَذَابٍ غَلِيظٍۢ","fa":"و هنگامی که فرمان ما [بر عذاب آنان] فرا رسید، هود و آنان را که با او ایمان آورده بودند با رحمتی از سوی خود نجات دادیم و آنان را از عذابی سخت رهایی بخشیدیم."},{"s":"سُورَةُ هُودٍ","n":68,"ar":"كَأَن لَّمْ يَغْنَوْا۟ فِيهَآ ۗ أَلَآ إِنَّ ثَمُودَا۟ كَفَرُوا۟ رَبَّهُمْ ۗ أَلَا بُعْدًۭا لِّثَمُودَ","fa":"گویی در آنجا اقامت نداشتند. آگاه باشید! قطعاً قوم ثمود به پروردگارشان کافر شدند. هان! دوری [از رحمت خدا] بر قوم ثمود باد."},{"s":"سُورَةُ هُودٍ","n":78,"ar":"وَجَآءَهُۥ قَوْمُهُۥ يُهْرَعُونَ إِلَيْهِ وَمِن قَبْلُ كَانُوا۟ يَعْمَلُونَ ٱلسَّيِّـَٔاتِ ۚ قَالَ يَٰقَوْمِ هَٰٓؤُلَآءِ بَنَاتِى هُنَّ أَطْهَرُ لَكُمْ ۖ فَٱتَّقُوا۟ ٱللَّهَ وَلَا تُخْزُونِ فِى ضَيْفِىٓ ۖ أَلَيْسَ مِنكُمْ رَجُلٌۭ رَّشِيدٌۭ","fa":"و قومش شتابان به سویش آمدند [تا به خیال خود به مهمانانش دست درازی کنند، آن قومی] که پیش از آن کارهای زشت و ناپسند مرتکب می شدند، گفت: ای قوم من! اینان دختران من هستند، اینان [از نظر ازدواج] برای شما پاکیزه ترند، از خدا پروا کنید و مرا در میان مهمانانم رسوا نکنید؛ آیا از میان شما مردی راه یافته نیست؟"},{"s":"سُورَةُ هُودٍ","n":88,"ar":"قَالَ يَٰقَوْمِ أَرَءَيْتُمْ إِن كُنتُ عَلَىٰ بَيِّنَةٍۢ مِّن رَّبِّى وَرَزَقَنِى مِنْهُ رِزْقًا حَسَنًۭا ۚ وَمَآ أُرِيدُ أَنْ أُخَالِفَكُمْ إِلَىٰ مَآ أَنْهَىٰكُمْ عَنْهُ ۚ إِنْ أُرِيدُ إِلَّا ٱلْإِصْلَٰحَ مَا ٱسْتَطَعْتُ ۚ وَمَا تَوْفِيقِىٓ إِلَّا بِٱللَّهِ ۚ عَلَيْهِ تَوَكَّلْتُ وَإِلَيْهِ أُنِيبُ","fa":"گفت: ای قوم من! مرا خبر دهید اگر من بر دلیل روشنی از سوی پروردگارم متکی باشم و از جانب او رزق نیکویی به من داده باشد [آیا رواست که خلاف خواسته او عمل کنم؟] و من نمی خواهم آنچه که شما را از آن باز می دارم خود مرتکب شوم؛ تا جایی که قدرت دارم جز اصلاح [شما را] نمی خواهم؛ و توفیقم فقط به [یاری] خداست؛ بر او توکل کردم و به سوی او باز می گردم."},{"s":"سُورَةُ هُودٍ","n":98,"ar":"يَقْدُمُ قَوْمَهُۥ يَوْمَ ٱلْقِيَٰمَةِ فَأَوْرَدَهُمُ ٱلنَّارَ ۖ وَبِئْسَ ٱلْوِرْدُ ٱلْمَوْرُودُ","fa":"[فرعون] روز قیامت پیشاپیش قومش می رود، پس آنان را به آتش درمی آورد، و بد نصیب و سهمی است [آتشی] که در آن وارد می شود."},{"s":"سُورَةُ هُودٍ","n":108,"ar":"۞ وَأَمَّا ٱلَّذِينَ سُعِدُوا۟ فَفِى ٱلْجَنَّةِ خَٰلِدِينَ فِيهَا مَا دَامَتِ ٱلسَّمَٰوَٰتُ وَٱلْأَرْضُ إِلَّا مَا شَآءَ رَبُّكَ ۖ عَطَآءً غَيْرَ مَجْذُوذٍۢ","fa":"اما نیک بختان [که به توفیق و رحمت خدا سعادت یافته اند] تا آسمان ها و زمین پابرجاست، در بهشت جاودانه اند مگر آنچه را مشیّت پروردگارت اقتضا کرده، [بهشت] عطایی قطع ناشدنی و بی پایان است."},{"s":"سُورَةُ هُودٍ","n":118,"ar":"وَلَوْ شَآءَ رَبُّكَ لَجَعَلَ ٱلنَّاسَ أُمَّةًۭ وَٰحِدَةًۭ ۖ وَلَا يَزَالُونَ مُخْتَلِفِينَ","fa":"اگر پروردگارت می خواست یقیناً تمام مردم را [از روی اجبار، در مسیر هدایت] امت واحدی قرار می داد، [ولی نخواست به همین سبب] همواره [در امر دین] در اختلاف اند."},{"s":"سُورَةُ يُوسُفَ","n":5,"ar":"قَالَ يَٰبُنَىَّ لَا تَقْصُصْ رُءْيَاكَ عَلَىٰٓ إِخْوَتِكَ فَيَكِيدُوا۟ لَكَ كَيْدًا ۖ إِنَّ ٱلشَّيْطَٰنَ لِلْإِنسَٰنِ عَدُوٌّۭ مُّبِينٌۭ","fa":"[پدر] گفت: ای پسرک من! خواب خود را برای برادرانت مگو که نقشه ای خطرناک بر ضد تو به کار می بندند، بدون شک شیطان برای انسان دشمنی آشکار است."},{"s":"سُورَةُ يُوسُفَ","n":15,"ar":"فَلَمَّا ذَهَبُوا۟ بِهِۦ وَأَجْمَعُوٓا۟ أَن يَجْعَلُوهُ فِى غَيَٰبَتِ ٱلْجُبِّ ۚ وَأَوْحَيْنَآ إِلَيْهِ لَتُنَبِّئَنَّهُم بِأَمْرِهِمْ هَٰذَا وَهُمْ لَا يَشْعُرُونَ","fa":"پس هنگامی که وی را بردند و تصمیم گرفتند که او را در مخفی گاه آن چاه قرارش دهند [تصمیم خود را به مرحله اجرا گذاشتند] و ما هم به او الهام کردیم که از این کار آگاهشان خواهی ساخت در حالی که آنان نمی فهمند [که تو همان یوسفی.]"},{"s":"سُورَةُ يُوسُفَ","n":25,"ar":"وَٱسْتَبَقَا ٱلْبَابَ وَقَدَّتْ قَمِيصَهُۥ مِن دُبُرٍۢ وَأَلْفَيَا سَيِّدَهَا لَدَا ٱلْبَابِ ۚ قَالَتْ مَا جَزَآءُ مَنْ أَرَادَ بِأَهْلِكَ سُوٓءًا إِلَّآ أَن يُسْجَنَ أَوْ عَذَابٌ أَلِيمٌۭ","fa":"و هر دو به سوی در کاخ پیشی گرفتند، و بانو پیراهن یوسف را از پشت پاره کرد و [در آن حال] در کنار [آستانه] در به شوهر وی برخوردند؛ بانو به شوهرش گفت: کسی که نسبت به خانواده ات قصد بدی داشته باشد، کیفرش جز زندان یا شکنجه دردناک [چه خواهد بود؟!]"},{"s":"سُورَةُ يُوسُفَ","n":35,"ar":"ثُمَّ بَدَا لَهُم مِّنۢ بَعْدِ مَا رَأَوُا۟ ٱلْءَايَٰتِ لَيَسْجُنُنَّهُۥ حَتَّىٰ حِينٍۢ","fa":"آن گاه آنان پس از آنکه نشانه ها [یِ پاکی و پاکدامنی یوسف] را دیده بودند، عزمشان بر این جزم شد که تا مدتی او را به زندان اندازند."},{"s":"سُورَةُ يُوسُفَ","n":45,"ar":"وَقَالَ ٱلَّذِى نَجَا مِنْهُمَا وَٱدَّكَرَ بَعْدَ أُمَّةٍ أَنَا۠ أُنَبِّئُكُم بِتَأْوِيلِهِۦ فَأَرْسِلُونِ","fa":"از آن دو زندانی آنکه آزاد شده بود و پس از مدتی [یوسف را] به یاد آورد گفت: من یقیناً شما را از تعبیر آن آگاه می کنم، پس [مرا به زندان] بفرستید."},{"s":"سُورَةُ يُوسُفَ","n":55,"ar":"قَالَ ٱجْعَلْنِى عَلَىٰ خَزَآئِنِ ٱلْأَرْضِ ۖ إِنِّى حَفِيظٌ عَلِيمٌۭ","fa":"یوسف گفت: مرا سرپرست خزانه های این سرزمین قرار ده؛ زیرا من نگهبان دانایی هستم."},{"s":"سُورَةُ يُوسُفَ","n":65,"ar":"وَلَمَّا فَتَحُوا۟ مَتَٰعَهُمْ وَجَدُوا۟ بِضَٰعَتَهُمْ رُدَّتْ إِلَيْهِمْ ۖ قَالُوا۟ يَٰٓأَبَانَا مَا نَبْغِى ۖ هَٰذِهِۦ بِضَٰعَتُنَا رُدَّتْ إِلَيْنَا ۖ وَنَمِيرُ أَهْلَنَا وَنَحْفَظُ أَخَانَا وَنَزْدَادُ كَيْلَ بَعِيرٍۢ ۖ ذَٰلِكَ كَيْلٌۭ يَسِيرٌۭ","fa":"و هنگامی که کالایشان را گشودند، دیدند اموالشان را به آنان بازگردانده اند، گفتند: ای پدر! [بهتر از این] چه می خواهیم؟ این اموال ماست که به ما بازگردانده و ما [دوباره با همین اموال] برای خانواده خود آذوقه می آوریم و برادرمان را حفظ می کنیم، و بار شتری اضافه می کنیم و آن [بار شتر از نظر عزیز که مردی کریم است] باری ناچیز است."},{"s":"سُورَةُ يُوسُفَ","n":75,"ar":"قَالُوا۟ جَزَٰٓؤُهُۥ مَن وُجِدَ فِى رَحْلِهِۦ فَهُوَ جَزَٰٓؤُهُۥ ۚ كَذَٰلِكَ نَجْزِى ٱلظَّٰلِمِينَ","fa":"گفتند: کسی که آبخوری در بار و بنه اش پیدا شود، کیفرش خود اوست [که به غلامی گرفته شود]. ما ستمکاران را [در کنعان] به همین صورت کیفر می دهیم."},{"s":"سُورَةُ يُوسُفَ","n":85,"ar":"قَالُوا۟ تَٱللَّهِ تَفْتَؤُا۟ تَذْكُرُ يُوسُفَ حَتَّىٰ تَكُونَ حَرَضًا أَوْ تَكُونَ مِنَ ٱلْهَٰلِكِينَ","fa":"گفتند: به خدا آن قدر از یوسف یاد می کنی تا سخت ناتوان شوی یا جانت را از دست بدهی."},{"s":"سُورَةُ يُوسُفَ","n":95,"ar":"قَالُوا۟ تَٱللَّهِ إِنَّكَ لَفِى ضَلَٰلِكَ ٱلْقَدِيمِ","fa":"گفتند: به خدا سوگند تو در همان خطا و گمراهی دیرینت هستی."},{"s":"سُورَةُ يُوسُفَ","n":105,"ar":"وَكَأَيِّن مِّنْ ءَايَةٍۢ فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ يَمُرُّونَ عَلَيْهَا وَهُمْ عَنْهَا مُعْرِضُونَ","fa":"و [برای هدایت مردم] در آسمان ها و زمین چه بسیار نشانه هاست که [در غفلت و بی خبری] بر آنها می گذرند در حالی که از آنها روی می گردانند."},{"s":"سُورَةُ الرَّعۡدِ","n":4,"ar":"وَفِى ٱلْأَرْضِ قِطَعٌۭ مُّتَجَٰوِرَٰتٌۭ وَجَنَّٰتٌۭ مِّنْ أَعْنَٰبٍۢ وَزَرْعٌۭ وَنَخِيلٌۭ صِنْوَانٌۭ وَغَيْرُ صِنْوَانٍۢ يُسْقَىٰ بِمَآءٍۢ وَٰحِدٍۢ وَنُفَضِّلُ بَعْضَهَا عَلَىٰ بَعْضٍۢ فِى ٱلْأُكُلِ ۚ إِنَّ فِى ذَٰلِكَ لَءَايَٰتٍۢ لِّقَوْمٍۢ يَعْقِلُونَ","fa":"در زمین قطعه هایی مختلف و گوناگون، و باغ هایی از انگور و کشتزار و درختان خرمایی است که بر یک ریشه و غیر یک ریشه [می رویند]. ما برخی از آنان را در میوه و محصول با آنکه از یک آب سیراب می شوند بر برخی دیگر برتری می دهیم. بی تردید در این امور برای مردمی که تعقّل می کنند، نشانه هایی [بر توحید، ربوبیّت و قدرت خدا] ست."},{"s":"سُورَةُ الرَّعۡدِ","n":14,"ar":"لَهُۥ دَعْوَةُ ٱلْحَقِّ ۖ وَٱلَّذِينَ يَدْعُونَ مِن دُونِهِۦ لَا يَسْتَجِيبُونَ لَهُم بِشَىْءٍ إِلَّا كَبَٰسِطِ كَفَّيْهِ إِلَى ٱلْمَآءِ لِيَبْلُغَ فَاهُ وَمَا هُوَ بِبَٰلِغِهِۦ ۚ وَمَا دُعَآءُ ٱلْكَٰفِرِينَ إِلَّا فِى ضَلَٰلٍۢ","fa":"دعوت حق [که اجابتش مایه سعادت دنیا و آخرت است] فقط ویژه خداست. و کسانی را که مشرکان به جای خدا می خوانند، چیزی [از درخواست ها و نیازهایشان را] برای آنان برآورده نمی کنند [درخواست این بی خردان از بتان بی جان و جاندار نیست] مگر مانند کسی که دو دستش را به سوی آبی [که با آن فاصله زیادی دارد] می گشاید تا آب به دهانش برسد و حال آنکه هرگز نخواهد رسید، و دعا و درخواست کافران [از غیر خدا] جز در گمراهی و تباهی [که به نتیجه و هدف نمی رسد] نیست."},{"s":"سُورَةُ الرَّعۡدِ","n":24,"ar":"سَلَٰمٌ عَلَيْكُم بِمَا صَبَرْتُمْ ۚ فَنِعْمَ عُقْبَى ٱلدَّارِ","fa":"[و به آنان گویند:] سلام بر شما به پاس استقامت و صبرتان [در برابر عبادت، معصیت و مصیبت] پس نیکوست فرجام این سرای."},{"s":"سُورَةُ الرَّعۡدِ","n":34,"ar":"لَّهُمْ عَذَابٌۭ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا ۖ وَلَعَذَابُ ٱلْءَاخِرَةِ أَشَقُّ ۖ وَمَا لَهُم مِّنَ ٱللَّهِ مِن وَاقٍۢ","fa":"برای آنان در زندگی دنیا عذابی است، و مسلماً عذاب آخرت سخت تر و پر مشقت تر است، و آنان را هیچ حافظ و نگه دارنده ای [از عذاب خدا] نیست."},{"s":"سُورَةُ إِبۡرَاهِيمَ","n":1,"ar":"بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ الٓر ۚ كِتَٰبٌ أَنزَلْنَٰهُ إِلَيْكَ لِتُخْرِجَ ٱلنَّاسَ مِنَ ٱلظُّلُمَٰتِ إِلَى ٱلنُّورِ بِإِذْنِ رَبِّهِمْ إِلَىٰ صِرَٰطِ ٱلْعَزِيزِ ٱلْحَمِيدِ","fa":"الر ـ [این] کتابی است که آن را بر تو نازل کردیم تا مردم را به اجازه پروردگارشان از تاریکی ها [یِ جهل، گمراهی و طغیان] به سوی روشناییِ [معرفت، عدالت و ایمان و در حقیقت] به سوی راه [خدایِ] توانای شکست ناپذیر و ستوده بیرون آوری."},{"s":"سُورَةُ إِبۡرَاهِيمَ","n":11,"ar":"قَالَتْ لَهُمْ رُسُلُهُمْ إِن نَّحْنُ إِلَّا بَشَرٌۭ مِّثْلُكُمْ وَلَٰكِنَّ ٱللَّهَ يَمُنُّ عَلَىٰ مَن يَشَآءُ مِنْ عِبَادِهِۦ ۖ وَمَا كَانَ لَنَآ أَن نَّأْتِيَكُم بِسُلْطَٰنٍ إِلَّا بِإِذْنِ ٱللَّهِ ۚ وَعَلَى ٱللَّهِ فَلْيَتَوَكَّلِ ٱلْمُؤْمِنُونَ","fa":"پیامبرانشان به آنان گفتند: یقینی است که ما بشری مانند شما هستیم، ولی خدا به هر کس از بندگانش که بخواهد [با عطا کردن مقام نبوّت] منّت می نهد و ما را نسزد که جز به اجازه خدا معجزه ای برای شما بیاوریم، و باید مؤمنان فقط بر خدا توکل کنند."},{"s":"سُورَةُ إِبۡرَاهِيمَ","n":21,"ar":"وَبَرَزُوا۟ لِلَّهِ جَمِيعًۭا فَقَالَ ٱلضُّعَفَٰٓؤُا۟ لِلَّذِينَ ٱسْتَكْبَرُوٓا۟ إِنَّا كُنَّا لَكُمْ تَبَعًۭا فَهَلْ أَنتُم مُّغْنُونَ عَنَّا مِنْ عَذَابِ ٱللَّهِ مِن شَىْءٍۢ ۚ قَالُوا۟ لَوْ هَدَىٰنَا ٱللَّهُ لَهَدَيْنَٰكُمْ ۖ سَوَآءٌ عَلَيْنَآ أَجَزِعْنَآ أَمْ صَبَرْنَا مَا لَنَا مِن مَّحِيصٍۢ","fa":"و [در عرصه قیامت] همگی در پیشگاه خدا ظاهر می شوند؛ پس ناتوانان [ی که بدون به کار گرفتن عقل، بلکه از روی تقلید کورکورانه پیرو مستکبران بودند] به مستکبران می گویند: ما [در دنیا بدون درخواست دلیل و برهان] پیروِ [مکتب] شما بودیم، آیا امروز چیزی از عذاب خدا را [به پاداش آنکه از شما پیروی کردیم] از ما برطرف می کنید؟ می گویند: اگر خدا ما را [در صورت داشتن لیاقت] هدایت کرده بود، همانا ما هم شما را هدایت می کردیم، [اکنون همه سرمایه های وجودی ما و تلاش و کوششمان بر باد رفته] چه بیتابی کنیم وچه شکیبایی ورزیم، برای ما یکسان است، ما را هیچ راه گریزی نیست."},{"s":"سُورَةُ إِبۡرَاهِيمَ","n":31,"ar":"قُل لِّعِبَادِىَ ٱلَّذِينَ ءَامَنُوا۟ يُقِيمُوا۟ ٱلصَّلَوٰةَ وَيُنفِقُوا۟ مِمَّا رَزَقْنَٰهُمْ سِرًّۭا وَعَلَانِيَةًۭ مِّن قَبْلِ أَن يَأْتِىَ يَوْمٌۭ لَّا بَيْعٌۭ فِيهِ وَلَا خِلَٰلٌ","fa":"به بندگان مؤمنم بگو: نماز را بر پا دارند، و از آنچه روزی آنان کرده ایم، پنهان و آشکار، انفاق کنند، پیش از آنکه روزی فرا رسد که در آن نه داد و ستدی است و نه پیوند دوستی و رفاقت."},{"s":"سُورَةُ إِبۡرَاهِيمَ","n":41,"ar":"رَبَّنَا ٱغْفِرْ لِى وَلِوَٰلِدَىَّ وَلِلْمُؤْمِنِينَ يَوْمَ يَقُومُ ٱلْحِسَابُ","fa":"پروردگارا! روزی که حساب برپا می شود، مرا و پدر و مادرم و مؤمنان را بیامرز."},{"s":"سُورَةُ إِبۡرَاهِيمَ","n":51,"ar":"لِيَجْزِىَ ٱللَّهُ كُلَّ نَفْسٍۢ مَّا كَسَبَتْ ۚ إِنَّ ٱللَّهَ سَرِيعُ ٱلْحِسَابِ","fa":"تا [به این کیفیت] خدا هر کس را [به سبب] آنچه انجام داده کیفر دهد؛ یقیناً خدا حسابرسی سریع است."},{"s":"سُورَةُ الحِجۡرِ","n":9,"ar":"إِنَّا نَحْنُ نَزَّلْنَا ٱلذِّكْرَ وَإِنَّا لَهُۥ لَحَٰفِظُونَ","fa":"همانا ما قرآن را نازل کردیم، و یقیناً ما نگهبان آن [از تحریف و زوال] هستیم."},{"s":"سُورَةُ الحِجۡرِ","n":19,"ar":"وَٱلْأَرْضَ مَدَدْنَٰهَا وَأَلْقَيْنَا فِيهَا رَوَٰسِىَ وَأَنۢبَتْنَا فِيهَا مِن كُلِّ شَىْءٍۢ مَّوْزُونٍۢ","fa":"و زمین را گستراندیم و در آن کوه های استوار افکندیم، واز هر گیاه موزون وسنجیده ای در آن رویاندیم."},{"s":"سُورَةُ الحِجۡرِ","n":29,"ar":"فَإِذَا سَوَّيْتُهُۥ وَنَفَخْتُ فِيهِ مِن رُّوحِى فَقَعُوا۟ لَهُۥ سَٰجِدِينَ","fa":"پس چون او را درست و نیکو گردانم و از روح خود در او بدمم، برای او سجده کنان بیفتید."},{"s":"سُورَةُ الحِجۡرِ","n":39,"ar":"قَالَ رَبِّ بِمَآ أَغْوَيْتَنِى لَأُزَيِّنَنَّ لَهُمْ فِى ٱلْأَرْضِ وَلَأُغْوِيَنَّهُمْ أَجْمَعِينَ","fa":"گفت: پروردگارا! به سبب اینکه مرا گمراه نمودی، من هم یقیناً [همه کارهای زشت را] در زمین برای آنان می آرایم [تا ارتکاب زشتی ها برای آنان آسان شود] و مسلماً همه را گمراه می کنم."},{"s":"سُورَةُ الحِجۡرِ","n":49,"ar":"۞ نَبِّئْ عِبَادِىٓ أَنِّىٓ أَنَا ٱلْغَفُورُ ٱلرَّحِيمُ","fa":"به بندگانم خبر ده که یقیناً من [نسبت به مؤمنان] بسیار آمرزنده و مهربانم."},{"s":"سُورَةُ الحِجۡرِ","n":59,"ar":"إِلَّآ ءَالَ لُوطٍ إِنَّا لَمُنَجُّوهُمْ أَجْمَعِينَ","fa":"مگر خاندان لوط را که قطعاً همه آنان را نجات می دهیم،"},{"s":"سُورَةُ الحِجۡرِ","n":69,"ar":"وَٱتَّقُوا۟ ٱللَّهَ وَلَا تُخْزُونِ","fa":"از خدا پروا کنید و مرا [نزد مهمانانم] خوار و بی مقدار نسازید."},{"s":"سُورَةُ الحِجۡرِ","n":79,"ar":"فَٱنتَقَمْنَا مِنْهُمْ وَإِنَّهُمَا لَبِإِمَامٍۢ مُّبِينٍۢ","fa":"در نتیجه از آنان انتقام گرفتیم، و [آثار] دو شهر نابود شده [قوم لوط و شعیب] بر سر جاده ای آشکار قرار دارد."},{"s":"سُورَةُ الحِجۡرِ","n":89,"ar":"وَقُلْ إِنِّىٓ أَنَا ٱلنَّذِيرُ ٱلْمُبِينُ","fa":"و [به اخلال گران در امر دین] بگو: بی تردید من بیم دهنده آشکارم."},{"s":"سُورَةُ الحِجۡرِ","n":99,"ar":"وَٱعْبُدْ رَبَّكَ حَتَّىٰ يَأْتِيَكَ ٱلْيَقِينُ","fa":"و پروردگارت را تا هنگامی که تو را مرگ بیاید، بندگی کن."},{"s":"سُورَةُ النَّحۡلِ","n":10,"ar":"هُوَ ٱلَّذِىٓ أَنزَلَ مِنَ ٱلسَّمَآءِ مَآءًۭ ۖ لَّكُم مِّنْهُ شَرَابٌۭ وَمِنْهُ شَجَرٌۭ فِيهِ تُسِيمُونَ","fa":"اوست که از آسمان، آبی برای شما نازل کرد که بخشی از آن نوشیدنی است و از بخشی از آن درخت و گیاه می روید که [دام هایتان] را در آن می چرانید."},{"s":"سُورَةُ النَّحۡلِ","n":20,"ar":"وَٱلَّذِينَ يَدْعُونَ مِن دُونِ ٱللَّهِ لَا يَخْلُقُونَ شَيْـًۭٔا وَهُمْ يُخْلَقُونَ","fa":"و معبودهایی را که به جای خدا می پرستند [نه اینکه] چیزی را نمی آفرینند، بلکه خودشان آفریده می شوند."},{"s":"سُورَةُ النَّحۡلِ","n":30,"ar":"۞ وَقِيلَ لِلَّذِينَ ٱتَّقَوْا۟ مَاذَآ أَنزَلَ رَبُّكُمْ ۚ قَالُوا۟ خَيْرًۭا ۗ لِّلَّذِينَ أَحْسَنُوا۟ فِى هَٰذِهِ ٱلدُّنْيَا حَسَنَةٌۭ ۚ وَلَدَارُ ٱلْءَاخِرَةِ خَيْرٌۭ ۚ وَلَنِعْمَ دَارُ ٱلْمُتَّقِينَ","fa":"و هنگامی که به پرهیزکاران گویند: پروردگارتان چه چیزی نازل کرد؟ گویند: خیر را [که قرآن هدایت گر است و سراسر آیاتش وحی الهی است، نازل کرد]. برای کسانی که نیکی کردند [پاداش] نیکویی در این دنیاست، وهمانا سرای آخرت بهتر است، و سرای پرهیزکاران چه نیکوست."},{"s":"سُورَةُ النَّحۡلِ","n":40,"ar":"إِنَّمَا قَوْلُنَا لِشَىْءٍ إِذَآ أَرَدْنَٰهُ أَن نَّقُولَ لَهُۥ كُن فَيَكُونُ","fa":"[زنده کردن مردگان برای ما دشوار نیست] فرمان ما درباره چیزی چون [به وجود آمدنش را] اراده کنیم، فقط این است که به آن می گوییم: باش، پس [بی درنگ] موجود می شود."},{"s":"سُورَةُ النَّحۡلِ","n":50,"ar":"يَخَافُونَ رَبَّهُم مِّن فَوْقِهِمْ وَيَفْعَلُونَ مَا يُؤْمَرُونَ ۩","fa":"از پروردگارشان که بر فراز آنان است، می ترسند، و آنچه را به آن مأمور می شوند، انجام می دهند."},{"s":"سُورَةُ النَّحۡلِ","n":60,"ar":"لِلَّذِينَ لَا يُؤْمِنُونَ بِٱلْءَاخِرَةِ مَثَلُ ٱلسَّوْءِ ۖ وَلِلَّهِ ٱلْمَثَلُ ٱلْأَعْلَىٰ ۚ وَهُوَ ٱلْعَزِيزُ ٱلْحَكِيمُ","fa":"برای کسانی که به آخرت ایمان نمی آورند، صفات زشت [وسیرت بد] است، وصفات برتر و والا ویژه خداست، و او توانای شکست ناپذیر و حکیم است."},{"s":"سُورَةُ النَّحۡلِ","n":70,"ar":"وَٱللَّهُ خَلَقَكُمْ ثُمَّ يَتَوَفَّىٰكُمْ ۚ وَمِنكُم مَّن يُرَدُّ إِلَىٰٓ أَرْذَلِ ٱلْعُمُرِ لِكَىْ لَا يَعْلَمَ بَعْدَ عِلْمٍۢ شَيْـًٔا ۚ إِنَّ ٱللَّهَ عَلِيمٌۭ قَدِيرٌۭ","fa":"و خدا شما را آفرید، آن گاه شما را می میراند، برخی از شما به سوی پست ترین مرحله عمر [که سالخوردگی و فرتوتی است] برگردانده می شود، تا پس از دانش اندکی که داشت چیزی را نداند؛ یقیناً خدا دانا و تواناست."},{"s":"سُورَةُ النَّحۡلِ","n":80,"ar":"وَٱللَّهُ جَعَلَ لَكُم مِّنۢ بُيُوتِكُمْ سَكَنًۭا وَجَعَلَ لَكُم مِّن جُلُودِ ٱلْأَنْعَٰمِ بُيُوتًۭا تَسْتَخِفُّونَهَا يَوْمَ ظَعْنِكُمْ وَيَوْمَ إِقَامَتِكُمْ ۙ وَمِنْ أَصْوَافِهَا وَأَوْبَارِهَا وَأَشْعَارِهَآ أَثَٰثًۭا وَمَتَٰعًا إِلَىٰ حِينٍۢ","fa":"و خدا خانه هایتان را برای شما مایه آرامش و راحت قرار داد، و برای شما از پوست دام ها سر پناه [مانند قبّه و خیمه] مقرّر کرد، که آنها را روز کوچ کردنتان و هنگام اقامتتان [در جابجا کردن] سبک می یابید و [برای شما] از پشم ها و کرک ها و موهای آنها تا زمانی معین، وسایل زندگی و کالای تجارت پدید آورد."},{"s":"سُورَةُ النَّحۡلِ","n":90,"ar":"۞ إِنَّ ٱللَّهَ يَأْمُرُ بِٱلْعَدْلِ وَٱلْإِحْسَٰنِ وَإِيتَآئِ ذِى ٱلْقُرْبَىٰ وَيَنْهَىٰ عَنِ ٱلْفَحْشَآءِ وَٱلْمُنكَرِ وَٱلْبَغْىِ ۚ يَعِظُكُمْ لَعَلَّكُمْ تَذَكَّرُونَ","fa":"به راستی خدا به عدالت و احسان و بخشش به خویشاوندان فرمان می دهد، و از فحشا و منکر و ستم گری نهی می کند. شما را اندرز می دهد تا متذکّر [این حقیقت] شوید [که فرمان های الهی، ضامن سعادت دنیا و آخرت شماست.]"},{"s":"سُورَةُ النَّحۡلِ","n":100,"ar":"إِنَّمَا سُلْطَٰنُهُۥ عَلَى ٱلَّذِينَ يَتَوَلَّوْنَهُۥ وَٱلَّذِينَ هُم بِهِۦ مُشْرِكُونَ","fa":"تسلّطش فقط بر کسانی است که او را سرپرست و دوست خود گرفته اند و بر کسانی است که [به وسیله اغواگری او] برای خدا شریک قرار داده اند."},{"s":"سُورَةُ النَّحۡلِ","n":110,"ar":"ثُمَّ إِنَّ رَبَّكَ لِلَّذِينَ هَاجَرُوا۟ مِنۢ بَعْدِ مَا فُتِنُوا۟ ثُمَّ جَٰهَدُوا۟ وَصَبَرُوٓا۟ إِنَّ رَبَّكَ مِنۢ بَعْدِهَا لَغَفُورٌۭ رَّحِيمٌۭ","fa":"آن گاه یقیناً پروردگارت نسبت به کسانی که پس از آزار دیدنِ [از مشرکان، سرزمین شرک را رها کرده] هجرت نمودند، سپس جهاد کردند، و [برای حفظ دینشان] شکیبایی ورزیدند، آری، پروردگارت [نسبت به آنان] پس از این [همه بلا] بسیار آمرزنده و مهربان است."},{"s":"سُورَةُ النَّحۡلِ","n":120,"ar":"إِنَّ إِبْرَٰهِيمَ كَانَ أُمَّةًۭ قَانِتًۭا لِّلَّهِ حَنِيفًۭا وَلَمْ يَكُ مِنَ ٱلْمُشْرِكِينَ","fa":"بدون تردید، ابراهیم [به تنهایی] یک امت بود، برای خدا از روی فروتنی فرمانبردار و [یکتاپرستی] حق گرا بود واز مشرکان نبود."},{"s":"سُورَةُ الإِسۡرَاءِ","n":2,"ar":"وَءَاتَيْنَا مُوسَى ٱلْكِتَٰبَ وَجَعَلْنَٰهُ هُدًۭى لِّبَنِىٓ إِسْرَٰٓءِيلَ أَلَّا تَتَّخِذُوا۟ مِن دُونِى وَكِيلًۭا","fa":"و ما به موسی کتاب دادیم و آن را برای بنی اسرائیل وسیله هدایت قرار دادیم [و در آن کتاب، آنان را به این حقیقت راهنمایی کردیم] که جز مرا [که خدای یگانه ام] وکیل و کار ساز نگیرید."},{"s":"سُورَةُ الإِسۡرَاءِ","n":12,"ar":"وَجَعَلْنَا ٱلَّيْلَ وَٱلنَّهَارَ ءَايَتَيْنِ ۖ فَمَحَوْنَآ ءَايَةَ ٱلَّيْلِ وَجَعَلْنَآ ءَايَةَ ٱلنَّهَارِ مُبْصِرَةًۭ لِّتَبْتَغُوا۟ فَضْلًۭا مِّن رَّبِّكُمْ وَلِتَعْلَمُوا۟ عَدَدَ ٱلسِّنِينَ وَٱلْحِسَابَ ۚ وَكُلَّ شَىْءٍۢ فَصَّلْنَٰهُ تَفْصِيلًۭا","fa":"ما شب و روز را دو نشانه [قدرت و حکمت خود] قرار دادیم؛ پس شب را بی نور نمودیم و روز را روشن ساختیم، تا [در آن] روزی و رزقی را از پروردگارتان بطلبید و برای اینکه شماره سال ها و حساب [اوقات و زمان ها] را بدانید، و هر چیزی را [که نسبت به دنیا و دینتان و تربیت و کمالتان نیازمند به آن هستید] به روشنی و به طور کامل بیان کردیم."},{"s":"سُورَةُ الإِسۡرَاءِ","n":22,"ar":"لَّا تَجْعَلْ مَعَ ٱللَّهِ إِلَٰهًا ءَاخَرَ فَتَقْعُدَ مَذْمُومًۭا مَّخْذُولًۭا","fa":"با خدا معبودی دیگر قرار مده که [نزد شایستگان] نکوهیده و [در دنیا و آخرت] بی یار و یاور شوی."},{"s":"سُورَةُ الإِسۡرَاءِ","n":32,"ar":"وَلَا تَقْرَبُوا۟ ٱلزِّنَىٰٓ ۖ إِنَّهُۥ كَانَ فَٰحِشَةًۭ وَسَآءَ سَبِيلًۭا","fa":"و نزدیک زنا نشوید که کاری بسیار زشت و راهی بد است."},{"s":"سُورَةُ الإِسۡرَاءِ","n":42,"ar":"قُل لَّوْ كَانَ مَعَهُۥٓ ءَالِهَةٌۭ كَمَا يَقُولُونَ إِذًۭا لَّٱبْتَغَوْا۟ إِلَىٰ ذِى ٱلْعَرْشِ سَبِيلًۭا","fa":"بگو: اگر آن گونه که می گویند، باخدا خدایانی بود، در آن هنگام به سوی صاحب عرش راهی می جستند [تا قدرتش را تصاحب کنند.]"},{"s":"سُورَةُ الإِسۡرَاءِ","n":52,"ar":"يَوْمَ يَدْعُوكُمْ فَتَسْتَجِيبُونَ بِحَمْدِهِۦ وَتَظُنُّونَ إِن لَّبِثْتُمْ إِلَّا قَلِيلًۭا","fa":"روزی که شما را [از میان گورها برای ورود به عرصه قیامت] فرا می خواند، پس [فرا خواندنش را] در حالی که او را سپاس و ستایش می گویید، اجابت می کنید، وگمان می برید که [در دنیا یا در برزخ] جز اندکی درنگ نکرده اید."},{"s":"سُورَةُ الإِسۡرَاءِ","n":62,"ar":"قَالَ أَرَءَيْتَكَ هَٰذَا ٱلَّذِى كَرَّمْتَ عَلَىَّ لَئِنْ أَخَّرْتَنِ إِلَىٰ يَوْمِ ٱلْقِيَٰمَةِ لَأَحْتَنِكَنَّ ذُرِّيَّتَهُۥٓ إِلَّا قَلِيلًۭا","fa":"[سپس] گفت: مرا خبر ده این کسی که او را بر من برتری دادی [سببش چه بود؟] اگر تا قیامت مهلتم بخشی، بی تردید فرزندانش را جز اندکی لجام می زنم [و به دنبال خود به عرصه هلاکت و نابودی می کشم.]"},{"s":"سُورَةُ الإِسۡرَاءِ","n":72,"ar":"وَمَن كَانَ فِى هَٰذِهِۦٓ أَعْمَىٰ فَهُوَ فِى ٱلْءَاخِرَةِ أَعْمَىٰ وَأَضَلُّ سَبِيلًۭا","fa":"و کسی که در این دنیا کوردل باشد، در آخرت هم کوردل و گمراه تر است."},{"s":"سُورَةُ الإِسۡرَاءِ","n":82,"ar":"وَنُنَزِّلُ مِنَ ٱلْقُرْءَانِ مَا هُوَ شِفَآءٌۭ وَرَحْمَةٌۭ لِّلْمُؤْمِنِينَ ۙ وَلَا يَزِيدُ ٱلظَّٰلِمِينَ إِلَّا خَسَارًۭا","fa":"و ما از قرآن آنچه را برای مؤمنان مایه درمان ورحمت است، نازل می کنیم وستمکاران را جز خسارت نمی افزاید."},{"s":"سُورَةُ الإِسۡرَاءِ","n":92,"ar":"أَوْ تُسْقِطَ ٱلسَّمَآءَ كَمَا زَعَمْتَ عَلَيْنَا كِسَفًا أَوْ تَأْتِىَ بِٱللَّهِ وَٱلْمَلَٰٓئِكَةِ قَبِيلًا","fa":"یا آسمان را آن گونه که گمان کرده ای [قدرت داری] پاره پاره بر سر ما بیفکنی، یا خدا و فرشتگان را رو به روی ما آوری."},{"s":"سُورَةُ الإِسۡرَاءِ","n":102,"ar":"قَالَ لَقَدْ عَلِمْتَ مَآ أَنزَلَ هَٰٓؤُلَآءِ إِلَّا رَبُّ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ بَصَآئِرَ وَإِنِّى لَأَظُنُّكَ يَٰفِرْعَوْنُ مَثْبُورًۭا","fa":"موسی گفت: مسلماً تو می دانی این معجزه ها را که بصیرت آور هستند، جز پروردگار آسمان ها و زمین نازل نکرده است، و ای فرعون! قطعاً من تو را هلاک شده می پندارم."},{"s":"سُورَةُ الكَهۡفِ","n":1,"ar":"بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ ٱلْحَمْدُ لِلَّهِ ٱلَّذِىٓ أَنزَلَ عَلَىٰ عَبْدِهِ ٱلْكِتَٰبَ وَلَمْ يَجْعَل لَّهُۥ عِوَجَا ۜ","fa":"همه ستایش ها ویژه خداست که این کتاب را بر بنده اش نازل کرد و برای آن هیچ گونه انحراف و کژی قرار نداد."},{"s":"سُورَةُ الكَهۡفِ","n":11,"ar":"فَضَرَبْنَا عَلَىٰٓ ءَاذَانِهِمْ فِى ٱلْكَهْفِ سِنِينَ عَدَدًۭا","fa":"پس سالیانی چند در آن غار، خواب را بر گوش هایشان چیره ساختیم."},{"s":"سُورَةُ الكَهۡفِ","n":21,"ar":"وَكَذَٰلِكَ أَعْثَرْنَا عَلَيْهِمْ لِيَعْلَمُوٓا۟ أَنَّ وَعْدَ ٱللَّهِ حَقٌّۭ وَأَنَّ ٱلسَّاعَةَ لَا رَيْبَ فِيهَآ إِذْ يَتَنَٰزَعُونَ بَيْنَهُمْ أَمْرَهُمْ ۖ فَقَالُوا۟ ٱبْنُوا۟ عَلَيْهِم بُنْيَٰنًۭا ۖ رَّبُّهُمْ أَعْلَمُ بِهِمْ ۚ قَالَ ٱلَّذِينَ غَلَبُوا۟ عَلَىٰٓ أَمْرِهِمْ لَنَتَّخِذَنَّ عَلَيْهِم مَّسْجِدًۭا","fa":"و این گونه [مردم آن شهر را به وسیله آن سکه قدیمی] از حال آنان آگاه کردیم تا بدانند که وعده خدا [در برانگیختن مردگان در روز قیامت] حق است و در برپا شدن قیامت هیچ تردیدی نیست. هنگامی که [کاشفانِ غار] میان خودشان در کار آنان نزاع و ستیز داشتند، پس [یک گروه] گفتند: ساختمانی به روی [جایگاه] آنان بنا کنید [تا از دیده ها پنهان بمانند] البته پروردگارشان به آنان داناتر است. ولی آنان که بر کارشان [نسبت به اصحاب کهف] پیروز شدند، گفتند: به یقین مسجدی بر روی [جایگاه] آنان بنا خواهیم کرد."},{"s":"سُورَةُ الكَهۡفِ","n":31,"ar":"أُو۟لَٰٓئِكَ لَهُمْ جَنَّٰتُ عَدْنٍۢ تَجْرِى مِن تَحْتِهِمُ ٱلْأَنْهَٰرُ يُحَلَّوْنَ فِيهَا مِنْ أَسَاوِرَ مِن ذَهَبٍۢ وَيَلْبَسُونَ ثِيَابًا خُضْرًۭا مِّن سُندُسٍۢ وَإِسْتَبْرَقٍۢ مُّتَّكِـِٔينَ فِيهَا عَلَى ٱلْأَرَآئِكِ ۚ نِعْمَ ٱلثَّوَابُ وَحَسُنَتْ مُرْتَفَقًۭا","fa":"برای آنان بهشت های جاودانی است که از زیرِ درختانِ [آن] نهرها جاری است، در حالی که در آنجا بر تخت ها تکیه دارند با دستبندهایی از طلا آراسته می شوند، و جامه هایی سبز از دیبای نازک و سِتبر می پوشند، چه پاداش خوبی و چه آسایش گاه نیکویی."},{"s":"سُورَةُ الكَهۡفِ","n":41,"ar":"أَوْ يُصْبِحَ مَآؤُهَا غَوْرًۭا فَلَن تَسْتَطِيعَ لَهُۥ طَلَبًۭا","fa":"یا آب آن در زمین فرو رود که هرگز نتوانی آن را به دست آوری."},{"s":"سُورَةُ الكَهۡفِ","n":51,"ar":"۞ مَّآ أَشْهَدتُّهُمْ خَلْقَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَلَا خَلْقَ أَنفُسِهِمْ وَمَا كُنتُ مُتَّخِذَ ٱلْمُضِلِّينَ عَضُدًۭا","fa":"من ابلیس و نسلش را در آفرینش آسمان ها و [در پدید آوردن]، زمین و در آفرینش خودشان شاهد و گواه نگرفتم [تا یاریم دهند]؛ و من گمراه کنندگان را یار و مددکار خود نگرفته ام."},{"s":"سُورَةُ الكَهۡفِ","n":61,"ar":"فَلَمَّا بَلَغَا مَجْمَعَ بَيْنِهِمَا نَسِيَا حُوتَهُمَا فَٱتَّخَذَ سَبِيلَهُۥ فِى ٱلْبَحْرِ سَرَبًۭا","fa":"پس هنگامی که به محل برخورد دو دریا رسیدند، ماهی خود را [که برای خوردن فراهم کرده بودند] از یاد بردند، [آن] ماهی راه خود را [به طور سرازیر] در دریا پیش گرفت."},{"s":"سُورَةُ الكَهۡفِ","n":71,"ar":"فَٱنطَلَقَا حَتَّىٰٓ إِذَا رَكِبَا فِى ٱلسَّفِينَةِ خَرَقَهَا ۖ قَالَ أَخَرَقْتَهَا لِتُغْرِقَ أَهْلَهَا لَقَدْ جِئْتَ شَيْـًٔا إِمْرًۭا","fa":"پس هر دو به راه افتادند تا وقتی که در کشتی سوار شدند، او شکافی در کشتی ایجاد کرد. موسی گفت: آیا آن را شکافتی تا سرنشینانش را غرق کنی؟ به راستی که کاری بسیار زشت کردی!"},{"s":"سُورَةُ الكَهۡفِ","n":81,"ar":"فَأَرَدْنَآ أَن يُبْدِلَهُمَا رَبُّهُمَا خَيْرًۭا مِّنْهُ زَكَوٰةًۭ وَأَقْرَبَ رُحْمًۭا","fa":"پس خواستیم پروردگارشان پاک تر و مهربان تر از او را به آنان عوض دهد."},{"s":"سُورَةُ الكَهۡفِ","n":91,"ar":"كَذَٰلِكَ وَقَدْ أَحَطْنَا بِمَا لَدَيْهِ خُبْرًۭا","fa":"[سرگذشت ذوالقرنین و ملت ها] این گونه [بود]، و یقیناً ما به آنچه [از وسایل و امکانات مادی و معنوی] نزد او بود، احاطه [علمی] داشتیم."},{"s":"سُورَةُ الكَهۡفِ","n":101,"ar":"ٱلَّذِينَ كَانَتْ أَعْيُنُهُمْ فِى غِطَآءٍ عَن ذِكْرِى وَكَانُوا۟ لَا يَسْتَطِيعُونَ سَمْعًا","fa":"همان کسانی که دیده [بصیرت] شان از یاد من در پرده [غفلت] بود، و نمی توانستند [سخن خدا را] بشنوند."},{"s":"سُورَةُ مَرۡيَمَ","n":1,"ar":"بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ كٓهيعٓصٓ","fa":"کهیعص"},{"s":"سُورَةُ مَرۡيَمَ","n":11,"ar":"فَخَرَجَ عَلَىٰ قَوْمِهِۦ مِنَ ٱلْمِحْرَابِ فَأَوْحَىٰٓ إِلَيْهِمْ أَن سَبِّحُوا۟ بُكْرَةًۭ وَعَشِيًّۭا","fa":"پس [به دنبال ناتوانی از سخن گفتن] از عبادتگاهش بر قومش درآمد و به آنان اشاره کرد که صبح و شام خدا را تسبیح گویید."},{"s":"سُورَةُ مَرۡيَمَ","n":21,"ar":"قَالَ كَذَٰلِكِ قَالَ رَبُّكِ هُوَ عَلَىَّ هَيِّنٌۭ ۖ وَلِنَجْعَلَهُۥٓ ءَايَةًۭ لِّلنَّاسِ وَرَحْمَةًۭ مِّنَّا ۚ وَكَانَ أَمْرًۭا مَّقْضِيًّۭا","fa":"گفت: چنین است [که گفتی، ولی] پروردگارت فرموده است: این کار بر من آسان است و [فرزندی بدون ازدواج به او بخشیدن] برای این [است] که او را نشانه ای [از قدرت خود] برای مردم و رحمتی از سوی خود قرار دهیم؛ و این کار شدنی است."},{"s":"سُورَةُ مَرۡيَمَ","n":31,"ar":"وَجَعَلَنِى مُبَارَكًا أَيْنَ مَا كُنتُ وَأَوْصَٰنِى بِٱلصَّلَوٰةِ وَٱلزَّكَوٰةِ مَا دُمْتُ حَيًّۭا","fa":"و هر جا که باشم بسیار بابرکت و سودمندم قرار داده، و مرا تا زنده ام به نماز و زکات سفارش کرده است."},{"s":"سُورَةُ مَرۡيَمَ","n":41,"ar":"وَٱذْكُرْ فِى ٱلْكِتَٰبِ إِبْرَٰهِيمَ ۚ إِنَّهُۥ كَانَ صِدِّيقًۭا نَّبِيًّا","fa":"و در این کتاب، [سرگذشتِ] ابراهیم را یاد کن، یقیناً او بسیار راستگو و پیامبر بود."},{"s":"سُورَةُ مَرۡيَمَ","n":51,"ar":"وَٱذْكُرْ فِى ٱلْكِتَٰبِ مُوسَىٰٓ ۚ إِنَّهُۥ كَانَ مُخْلَصًۭا وَكَانَ رَسُولًۭا نَّبِيًّۭا","fa":"و در این کتاب، [سرگذشتِ] موسی را یاد کن، بی تردید او انسانی خالص شده و فرستاده ای پیامبر بود."},{"s":"سُورَةُ مَرۡيَمَ","n":61,"ar":"جَنَّٰتِ عَدْنٍ ٱلَّتِى وَعَدَ ٱلرَّحْمَٰنُ عِبَادَهُۥ بِٱلْغَيْبِ ۚ إِنَّهُۥ كَانَ وَعْدُهُۥ مَأْتِيًّۭا","fa":"بهشت های جاویدی که [خدای] رحمان به بندگانش وعده داده در حالی که اکنون از نظرها پنهان است، یقیناً وعده خدا آمدنی است."},{"s":"سُورَةُ مَرۡيَمَ","n":71,"ar":"وَإِن مِّنكُمْ إِلَّا وَارِدُهَا ۚ كَانَ عَلَىٰ رَبِّكَ حَتْمًۭا مَّقْضِيًّۭا","fa":"و هیچ کس از شما نیست مگر آنکه وارد دوزخ می شود، [ورود همگان به دوزخ] بر پروردگارت مسلّم و حتمی است."},{"s":"سُورَةُ مَرۡيَمَ","n":81,"ar":"وَٱتَّخَذُوا۟ مِن دُونِ ٱللَّهِ ءَالِهَةًۭ لِّيَكُونُوا۟ لَهُمْ عِزًّۭا","fa":"و به جای خدا معبودانی گرفتند تا برای آنان مایه عزت و توانمندی باشد."},{"s":"سُورَةُ مَرۡيَمَ","n":91,"ar":"أَن دَعَوْا۟ لِلرَّحْمَٰنِ وَلَدًۭا","fa":"به خاطر آنکه برای [خدای] رحمان فرزندی ادعا کرده اند."},{"s":"سُورَةُ طه","n":3,"ar":"إِلَّا تَذْكِرَةًۭ لِّمَن يَخْشَىٰ","fa":"[بلکه آن را نازل کردیم] تا برای کسی که [از خدا] می ترسد، زمینه توجه و یادآوری باشد."},{"s":"سُورَةُ طه","n":13,"ar":"وَأَنَا ٱخْتَرْتُكَ فَٱسْتَمِعْ لِمَا يُوحَىٰٓ","fa":"و من تو را [به پیامبری] برگزیدم، پس به آنچه وحی می شود، گوش فرا دار."},{"s":"سُورَةُ طه","n":23,"ar":"لِنُرِيَكَ مِنْ ءَايَٰتِنَا ٱلْكُبْرَى","fa":"تا برخی از بزرگ ترین معجزات خود را به تو نشان دهیم."},{"s":"سُورَةُ طه","n":33,"ar":"كَىْ نُسَبِّحَكَ كَثِيرًۭا","fa":"تا تو را [در میان مشرکان از داشتن شریک] بسیار و فراوان تنزیه کنیم،"},{"s":"سُورَةُ طه","n":43,"ar":"ٱذْهَبَآ إِلَىٰ فِرْعَوْنَ إِنَّهُۥ طَغَىٰ","fa":"هر دو به سوی فرعون بروید؛ زیرا او [در برابر خدا] سرکشی کرده است."},{"s":"سُورَةُ طه","n":53,"ar":"ٱلَّذِى جَعَلَ لَكُمُ ٱلْأَرْضَ مَهْدًۭا وَسَلَكَ لَكُمْ فِيهَا سُبُلًۭا وَأَنزَلَ مِنَ ٱلسَّمَآءِ مَآءًۭ فَأَخْرَجْنَا بِهِۦٓ أَزْوَٰجًۭا مِّن نَّبَاتٍۢ شَتَّىٰ","fa":"همان کسی که زمین را برای شما بستری گسترده قرار داد، و برای شما در آن [به خاطر آسان شدن رفت و آمدتان] راه هایی پدید آورد، و از آسمان آبی نازل کرد، پس به وسیله آن انواعی از روییدنی های گوناگون بیرون آوردیم."},{"s":"سُورَةُ طه","n":63,"ar":"قَالُوٓا۟ إِنْ هَٰذَٰنِ لَسَٰحِرَٰنِ يُرِيدَانِ أَن يُخْرِجَاكُم مِّنْ أَرْضِكُم بِسِحْرِهِمَا وَيَذْهَبَا بِطَرِيقَتِكُمُ ٱلْمُثْلَىٰ","fa":"گفتند: مسلماً این دو نفر جادوگرند، می خواهند شما را با جادویشان از سرزمینتان بیرون کنند و آیین برتر شما را از بین ببرند."},{"s":"سُورَةُ طه","n":73,"ar":"إِنَّآ ءَامَنَّا بِرَبِّنَا لِيَغْفِرَ لَنَا خَطَٰيَٰنَا وَمَآ أَكْرَهْتَنَا عَلَيْهِ مِنَ ٱلسِّحْرِ ۗ وَٱللَّهُ خَيْرٌۭ وَأَبْقَىٰٓ","fa":"بی تردید ما به پروردگارمان ایمان آوردیم تا خطاهایمان و آن جادویی که ما را به آن واداشتی بر ما بیامرزد؛ وخدا بهتر وپایدارتر است."},{"s":"سُورَةُ طه","n":83,"ar":"۞ وَمَآ أَعْجَلَكَ عَن قَوْمِكَ يَٰمُوسَىٰ","fa":"ای موسی! چه چیز تو را شتابان کرد که قبل از قوم خود [در آمدن به کوه طور] پیشی گرفتی؟"},{"s":"سُورَةُ طه","n":93,"ar":"أَلَّا تَتَّبِعَنِ ۖ أَفَعَصَيْتَ أَمْرِى","fa":"از اینکه مرا [در برخورد شدید با گمراهان] پیروی کنی؟ آیا از فرمان من سرپیچی کردی؟"},{"s":"سُورَةُ طه","n":103,"ar":"يَتَخَٰفَتُونَ بَيْنَهُمْ إِن لَّبِثْتُمْ إِلَّا عَشْرًۭا","fa":"در میان خودشان پنهانی و بسیار آهسته می گویند: که [در برزخ] جز ده روز درنگ نکرده اید."},{"s":"سُورَةُ طه","n":113,"ar":"وَكَذَٰلِكَ أَنزَلْنَٰهُ قُرْءَانًا عَرَبِيًّۭا وَصَرَّفْنَا فِيهِ مِنَ ٱلْوَعِيدِ لَعَلَّهُمْ يَتَّقُونَ أَوْ يُحْدِثُ لَهُمْ ذِكْرًۭا","fa":"و این گونه آن را قرآنی به زبان عربی [فصیح و گویا] نازل کردیم، و در آن هشدارها و تهدیدهای گوناگون آوردیم، امید است [از عقاید و آرای بی پایه و گناه و طغیان] بپرهیزند، یا برای آنان بیداری و هشیاری پدید آورد."},{"s":"سُورَةُ طه","n":123,"ar":"قَالَ ٱهْبِطَا مِنْهَا جَمِيعًۢا ۖ بَعْضُكُمْ لِبَعْضٍ عَدُوٌّۭ ۖ فَإِمَّا يَأْتِيَنَّكُم مِّنِّى هُدًۭى فَمَنِ ٱتَّبَعَ هُدَاىَ فَلَا يَضِلُّ وَلَا يَشْقَىٰ","fa":"[خدا] گفت: هر دو با هم از بهشت [به سوی زمین] فرود آیید که برخی از شما دشمن برخی دیگرند، پس اگر از سوی من هدایتی به شما رسید، هر کس از هدایتم پیروی کند، نه گمراه می شود و نه به مشقت و رنج می افتد."},{"s":"سُورَةُ طه","n":133,"ar":"وَقَالُوا۟ لَوْلَا يَأْتِينَا بِـَٔايَةٍۢ مِّن رَّبِّهِۦٓ ۚ أَوَلَمْ تَأْتِهِم بَيِّنَةُ مَا فِى ٱلصُّحُفِ ٱلْأُولَىٰ","fa":"و [مشرکان] گفتند: چرا [پیامبر] معجزه ای از سوی پروردگارش برای ما نمی آورد؟ آیا [این قرآن که] شاهد و دلیلی روشن بر [معارف] کتاب های پیشین [آسمانی است] برای آنان نیامده؟!"},{"s":"سُورَةُ الأَنبِيَاءِ","n":8,"ar":"وَمَا جَعَلْنَٰهُمْ جَسَدًۭا لَّا يَأْكُلُونَ ٱلطَّعَامَ وَمَا كَانُوا۟ خَٰلِدِينَ","fa":"و آنان را جسدهایی که غذا نخورند قرار ندادیم، و جاویدان هم نبودند [که از دنیا نروند.]"},{"s":"سُورَةُ الأَنبِيَاءِ","n":18,"ar":"بَلْ نَقْذِفُ بِٱلْحَقِّ عَلَى ٱلْبَٰطِلِ فَيَدْمَغُهُۥ فَإِذَا هُوَ زَاهِقٌۭ ۚ وَلَكُمُ ٱلْوَيْلُ مِمَّا تَصِفُونَ","fa":"نه، بلکه [شأن ما این است که] با حق بر باطل می کوبیم تا آن را درهم شکند [و از هم بپاشد] پس ناگهان باطل نابود شود؛ و وای بر شما از آنچه [درباره خدا و مخلوقات او به ناحق] توصیف می کنید."},{"s":"سُورَةُ الأَنبِيَاءِ","n":28,"ar":"يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ وَلَا يَشْفَعُونَ إِلَّا لِمَنِ ٱرْتَضَىٰ وَهُم مِّنْ خَشْيَتِهِۦ مُشْفِقُونَ","fa":"خدا همه گذشته آنان و آینده شان را می داند، و جز برای کسی که خدا بپسندد شفاعت نمی کنند، و آنان از ترس [عظمت و جلال] او هراسان و بیمناکند."},{"s":"سُورَةُ الأَنبِيَاءِ","n":38,"ar":"وَيَقُولُونَ مَتَىٰ هَٰذَا ٱلْوَعْدُ إِن كُنتُمْ صَٰدِقِينَ","fa":"[به پیامبر و مؤمنان] می گویند: اگر راست می گویید، این وعده کی خواهد بود؟"},{"s":"سُورَةُ الأَنبِيَاءِ","n":48,"ar":"وَلَقَدْ ءَاتَيْنَا مُوسَىٰ وَهَٰرُونَ ٱلْفُرْقَانَ وَضِيَآءًۭ وَذِكْرًۭا لِّلْمُتَّقِينَ","fa":"یقیناً به موسی و هارون [کتابی که] جداکننده [حق از باطل] و نور و مایه یادآوری برای پرهیزکاران [است] عطا کردیم."},{"s":"سُورَةُ الأَنبِيَاءِ","n":58,"ar":"فَجَعَلَهُمْ جُذَٰذًا إِلَّا كَبِيرًۭا لَّهُمْ لَعَلَّهُمْ إِلَيْهِ يَرْجِعُونَ","fa":"پس [همه] بت ها را قطعه قطعه کرد و شکست مگر بت بزرگشان را که [برای درک ناتوانی بت ها] به آن مراجعه کنند."},{"s":"سُورَةُ الأَنبِيَاءِ","n":68,"ar":"قَالُوا۟ حَرِّقُوهُ وَٱنصُرُوٓا۟ ءَالِهَتَكُمْ إِن كُنتُمْ فَٰعِلِينَ","fa":"گفتند: اگر می خواهید کاری انجام دهید [و مرد کار هستید] او را بسوزانید، و معبودانتان را یاری دهید."},{"s":"سُورَةُ الأَنبِيَاءِ","n":78,"ar":"وَدَاوُۥدَ وَسُلَيْمَٰنَ إِذْ يَحْكُمَانِ فِى ٱلْحَرْثِ إِذْ نَفَشَتْ فِيهِ غَنَمُ ٱلْقَوْمِ وَكُنَّا لِحُكْمِهِمْ شَٰهِدِينَ","fa":"و داود و سلیمان را [یاد کن] زمانی که درباره آن کشتزار که شبانه گوسفندان قوم در آن چریده بودند، داوری می کردند، و ما گواه داوری آنان بودیم."},{"s":"سُورَةُ الأَنبِيَاءِ","n":88,"ar":"فَٱسْتَجَبْنَا لَهُۥ وَنَجَّيْنَٰهُ مِنَ ٱلْغَمِّ ۚ وَكَذَٰلِكَ نُۨجِى ٱلْمُؤْمِنِينَ","fa":"پس ندایش را اجابت کردیم و از اندوه نجاتش دادیم؛ و این گونه مؤمنان را نجات می دهیم."},{"s":"سُورَةُ الأَنبِيَاءِ","n":98,"ar":"إِنَّكُمْ وَمَا تَعْبُدُونَ مِن دُونِ ٱللَّهِ حَصَبُ جَهَنَّمَ أَنتُمْ لَهَا وَٰرِدُونَ","fa":"[به آنان گویند:] به یقین شما و معبودانی که به جای خدا می پرستیدید، هیزمِ دوزخید؛ [بی تردید] شما در آن وارد خواهید شد."},{"s":"سُورَةُ الأَنبِيَاءِ","n":108,"ar":"قُلْ إِنَّمَا يُوحَىٰٓ إِلَىَّ أَنَّمَآ إِلَٰهُكُمْ إِلَٰهٌۭ وَٰحِدٌۭ ۖ فَهَلْ أَنتُم مُّسْلِمُونَ","fa":"بگو: به من فقط وحی می شود که معبود شما خدای یکتاست؛ پس آیا تسلیم [فرمان ها و احکام او] می شوید؟"},{"s":"سُورَةُ الحَجِّ","n":6,"ar":"ذَٰلِكَ بِأَنَّ ٱللَّهَ هُوَ ٱلْحَقُّ وَأَنَّهُۥ يُحْىِ ٱلْمَوْتَىٰ وَأَنَّهُۥ عَلَىٰ كُلِّ شَىْءٍۢ قَدِيرٌۭ","fa":"[همه] این [امور] برای این است که [بدانید] خدا همان حق است، و اینکه او مردگان را زنده می کند، و اینکه او بر هر کاری تواناست."},{"s":"سُورَةُ الحَجِّ","n":16,"ar":"وَكَذَٰلِكَ أَنزَلْنَٰهُ ءَايَٰتٍۭ بَيِّنَٰتٍۢ وَأَنَّ ٱللَّهَ يَهْدِى مَن يُرِيدُ","fa":"و این گونه، قرآن را [به صورت] آیاتی روشن نازل کردیم؛ و قطعاً خدا هر که را بخواهد، هدایت می کند."},{"s":"سُورَةُ الحَجِّ","n":26,"ar":"وَإِذْ بَوَّأْنَا لِإِبْرَٰهِيمَ مَكَانَ ٱلْبَيْتِ أَن لَّا تُشْرِكْ بِى شَيْـًۭٔا وَطَهِّرْ بَيْتِىَ لِلطَّآئِفِينَ وَٱلْقَآئِمِينَ وَٱلرُّكَّعِ ٱلسُّجُودِ","fa":"و [یاد کن] هنگامی را که جای خانه [کعبه] را برای ابراهیم آماده کردیم [و از او پیمان گرفتیم] که هیچ چیز را شریک من قرار مده و خانه ام را برای طواف کنندگان و قیام کنندگان و رکوع کنندگان و سجده کنندگان [از پلیدی های ظاهری و باطنی] پاک و پاکیزه گردان."},{"s":"سُورَةُ الحَجِّ","n":36,"ar":"وَٱلْبُدْنَ جَعَلْنَٰهَا لَكُم مِّن شَعَٰٓئِرِ ٱللَّهِ لَكُمْ فِيهَا خَيْرٌۭ ۖ فَٱذْكُرُوا۟ ٱسْمَ ٱللَّهِ عَلَيْهَا صَوَآفَّ ۖ فَإِذَا وَجَبَتْ جُنُوبُهَا فَكُلُوا۟ مِنْهَا وَأَطْعِمُوا۟ ٱلْقَانِعَ وَٱلْمُعْتَرَّ ۚ كَذَٰلِكَ سَخَّرْنَٰهَا لَكُمْ لَعَلَّكُمْ تَشْكُرُونَ","fa":"شتران قربانی را برای شما از شعایر خدا قرار دادیم، برای شما در آنها سودی [مانند سواری گرفتن و تغذیه از شیر و گوشت آنها] ست؛ در حالی که به نظم در خط مستقیم ایستاده اند، نام خدا را [هنگام نحر کردنشان] بر آنها ذکر کنید، و زمانی که [بی جان] به پهلو در افتاده اند، از آنها بخورید و به تهیدستانی که اهل درخواست کردن نیستند و فقیرانی که اهل درخواست کردن هستند، بخورانید. این گونه آنها را برای شما رام و مسخّر کردیم تا سپاس گزاری کنید."},{"s":"سُورَةُ الحَجِّ","n":46,"ar":"أَفَلَمْ يَسِيرُوا۟ فِى ٱلْأَرْضِ فَتَكُونَ لَهُمْ قُلُوبٌۭ يَعْقِلُونَ بِهَآ أَوْ ءَاذَانٌۭ يَسْمَعُونَ بِهَا ۖ فَإِنَّهَا لَا تَعْمَى ٱلْأَبْصَٰرُ وَلَٰكِن تَعْمَى ٱلْقُلُوبُ ٱلَّتِى فِى ٱلصُّدُورِ","fa":"آیا در زمین گردش نکرده اند تا برای آنان دل هایی [بیدار و بینا] پیدا شود که با آن بیندیشند یا گوش هایی که با آن [اندرزها را] بشنوند؟ حقیقت این است که دیده ها کور نیست بلکه دل هایی که در سینه هاست، کور است!"},{"s":"سُورَةُ الحَجِّ","n":56,"ar":"ٱلْمُلْكُ يَوْمَئِذٍۢ لِّلَّهِ يَحْكُمُ بَيْنَهُمْ ۚ فَٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ فِى جَنَّٰتِ ٱلنَّعِيمِ","fa":"آن روز، حاکمیّت و فرمانروایی ویژه خداست. میان آنان داوری می کند؛ پس کسانی که ایمان آورده و کارهای شایسته انجام داده اند، در بهشت های پر نعمت اند."},{"s":"سُورَةُ الحَجِّ","n":66,"ar":"وَهُوَ ٱلَّذِىٓ أَحْيَاكُمْ ثُمَّ يُمِيتُكُمْ ثُمَّ يُحْيِيكُمْ ۗ إِنَّ ٱلْإِنسَٰنَ لَكَفُورٌۭ","fa":"و اوست که به شما حیات داد، سپس شما را می میراند، آن گاه شما را زنده می کند؛ به یقین که انسان بسیار ناسپاس است."},{"s":"سُورَةُ الحَجِّ","n":76,"ar":"يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ ۗ وَإِلَى ٱللَّهِ تُرْجَعُ ٱلْأُمُورُ","fa":"همه اعمال و احوال گذشته [رسولان چه فرشته و چه بشر] و [همه اعمال و احوال] آینده آنان را می داند؛ و همه کارها به خدا بازگردانده می شود."},{"s":"سُورَةُ المُؤۡمِنُونَ","n":8,"ar":"وَٱلَّذِينَ هُمْ لِأَمَٰنَٰتِهِمْ وَعَهْدِهِمْ رَٰعُونَ","fa":"و آنان که امانت ها و پیمان های خود را رعایت می کنند،"},{"s":"سُورَةُ المُؤۡمِنُونَ","n":18,"ar":"وَأَنزَلْنَا مِنَ ٱلسَّمَآءِ مَآءًۢ بِقَدَرٍۢ فَأَسْكَنَّٰهُ فِى ٱلْأَرْضِ ۖ وَإِنَّا عَلَىٰ ذَهَابٍۭ بِهِۦ لَقَٰدِرُونَ","fa":"و از آسمان، آبی به اندازه نازل کردیم و آن را در زمین جای دادیم؛ و بی تردید به از بین بردن آن کاملاً توانمندیم."},{"s":"سُورَةُ المُؤۡمِنُونَ","n":28,"ar":"فَإِذَا ٱسْتَوَيْتَ أَنتَ وَمَن مَّعَكَ عَلَى ٱلْفُلْكِ فَقُلِ ٱلْحَمْدُ لِلَّهِ ٱلَّذِى نَجَّىٰنَا مِنَ ٱلْقَوْمِ ٱلظَّٰلِمِينَ","fa":"پس هنگامی که تو و آنان که با تو هستند، بر کشتی سوار شدید، به خاطر این نعمت بگو: همه ستایش ها ویژه خداست که ما را از این گروه ستم پیشه نجات داد."},{"s":"سُورَةُ المُؤۡمِنُونَ","n":38,"ar":"إِنْ هُوَ إِلَّا رَجُلٌ ٱفْتَرَىٰ عَلَى ٱللَّهِ كَذِبًۭا وَمَا نَحْنُ لَهُۥ بِمُؤْمِنِينَ","fa":"او نیست مگر مردی که بر خدا افترا بسته است؛ و ما باور کننده او نیستیم."},{"s":"سُورَةُ المُؤۡمِنُونَ","n":48,"ar":"فَكَذَّبُوهُمَا فَكَانُوا۟ مِنَ ٱلْمُهْلَكِينَ","fa":"در نتیجه هر دو را تکذیب کردند و از هلاک شدگان شدند."},{"s":"سُورَةُ المُؤۡمِنُونَ","n":58,"ar":"وَٱلَّذِينَ هُم بِـَٔايَٰتِ رَبِّهِمْ يُؤْمِنُونَ","fa":"و آنان که به آیات پروردگارشان ایمان می آورند."},{"s":"سُورَةُ المُؤۡمِنُونَ","n":68,"ar":"أَفَلَمْ يَدَّبَّرُوا۟ ٱلْقَوْلَ أَمْ جَآءَهُم مَّا لَمْ يَأْتِ ءَابَآءَهُمُ ٱلْأَوَّلِينَ","fa":"آیا در این سخن [که وحی خداست] نیندیشیدند؟ یا مگر [برای اولین بار] کتابی برای آنان آمده است که برای پدران پیشین آنان نیامده بود؟ …."},{"s":"سُورَةُ المُؤۡمِنُونَ","n":78,"ar":"وَهُوَ ٱلَّذِىٓ أَنشَأَ لَكُمُ ٱلسَّمْعَ وَٱلْأَبْصَٰرَ وَٱلْأَفْـِٔدَةَ ۚ قَلِيلًۭا مَّا تَشْكُرُونَ","fa":"و اوست که برای شما گوش و دیده و دل پدید آورد، ولی اندکی سپاس گزاری می کنید،"},{"s":"سُورَةُ المُؤۡمِنُونَ","n":88,"ar":"قُلْ مَنۢ بِيَدِهِۦ مَلَكُوتُ كُلِّ شَىْءٍۢ وَهُوَ يُجِيرُ وَلَا يُجَارُ عَلَيْهِ إِن كُنتُمْ تَعْلَمُونَ","fa":"بگو: اگر معرفت و شناخت دارید [بگویید:] کیست که [حاکمیّت مطلق و] فرمانروایی همه چیز به دست اوست و او پناه دهد و برخلاف خواسته اش به کسی [از عذاب] پناه داده نمی شود."},{"s":"سُورَةُ المُؤۡمِنُونَ","n":98,"ar":"وَأَعُوذُ بِكَ رَبِّ أَن يَحْضُرُونِ","fa":"و پروردگارا! به تو پناه می آورم از اینکه [شیطان ها] نزد من حاضر شوند."},{"s":"سُورَةُ المُؤۡمِنُونَ","n":108,"ar":"قَالَ ٱخْسَـُٔوا۟ فِيهَا وَلَا تُكَلِّمُونِ","fa":"[خدا] می گوید: [ای سگان!] در دوزخ گم شوید و با من سخن مگویید!"},{"s":"سُورَةُ المُؤۡمِنُونَ","n":118,"ar":"وَقُل رَّبِّ ٱغْفِرْ وَٱرْحَمْ وَأَنتَ خَيْرُ ٱلرَّٰحِمِينَ","fa":"و بگو: پروردگارا! [مرا] بیامرز و [بر من] رحم کن و تو بهترین رحم کنندگانی."},{"s":"سُورَةُ النُّورِ","n":10,"ar":"وَلَوْلَا فَضْلُ ٱللَّهِ عَلَيْكُمْ وَرَحْمَتُهُۥ وَأَنَّ ٱللَّهَ تَوَّابٌ حَكِيمٌ","fa":"و اگر فضل و رحمت خدا بر شما نبود، و اینکه خدا بسیار توبه پذیر و حکیم است [به کیفرهای بسیار سختی دچار می شدید.]"},{"s":"سُورَةُ النُّورِ","n":20,"ar":"وَلَوْلَا فَضْلُ ٱللَّهِ عَلَيْكُمْ وَرَحْمَتُهُۥ وَأَنَّ ٱللَّهَ رَءُوفٌۭ رَّحِيمٌۭ","fa":"و اگر فضل و رحمت خدا بر شما نبود، و اینکه خدا رؤوف و مهربان است [به کیفرهای بسیار سختی دچار می شدید.]"},{"s":"سُورَةُ النُّورِ","n":30,"ar":"قُل لِّلْمُؤْمِنِينَ يَغُضُّوا۟ مِنْ أَبْصَٰرِهِمْ وَيَحْفَظُوا۟ فُرُوجَهُمْ ۚ ذَٰلِكَ أَزْكَىٰ لَهُمْ ۗ إِنَّ ٱللَّهَ خَبِيرٌۢ بِمَا يَصْنَعُونَ","fa":"به مردان مؤمن بگو: چشمان خود را [از آنچه حرام است مانند دیدن زنان نامحرم و عورت دیگران] فرو بندند، و شرمگاه خود را حفظ کنند، این برای آنان پاکیزه تر است، قطعاً خدا به کارهایی که انجام می دهند، آگاه است."},{"s":"سُورَةُ النُّورِ","n":40,"ar":"أَوْ كَظُلُمَٰتٍۢ فِى بَحْرٍۢ لُّجِّىٍّۢ يَغْشَىٰهُ مَوْجٌۭ مِّن فَوْقِهِۦ مَوْجٌۭ مِّن فَوْقِهِۦ سَحَابٌۭ ۚ ظُلُمَٰتٌۢ بَعْضُهَا فَوْقَ بَعْضٍ إِذَآ أَخْرَجَ يَدَهُۥ لَمْ يَكَدْ يَرَىٰهَا ۗ وَمَن لَّمْ يَجْعَلِ ٱللَّهُ لَهُۥ نُورًۭا فَمَا لَهُۥ مِن نُّورٍ","fa":"یا [اعمالشان] مانند تاریکی هایی است در دریایی بسیار عمیق که همواره موجی آن را می پوشاند، و بالای آن موجی دیگر است، و بر فراز آن ابری است، تاریکی هایی است برخی بالای برخی دیگر؛ [مبتلای این امواج و تاریکی ها] هرگاه دستش را بیرون آورد، بعید است آن را ببیند. و کسی که خدا نوری برای او قرار نداده است، برای او هیچ نوری نیست."},{"s":"سُورَةُ النُّورِ","n":50,"ar":"أَفِى قُلُوبِهِم مَّرَضٌ أَمِ ٱرْتَابُوٓا۟ أَمْ يَخَافُونَ أَن يَحِيفَ ٱللَّهُ عَلَيْهِمْ وَرَسُولُهُۥ ۚ بَلْ أُو۟لَٰٓئِكَ هُمُ ٱلظَّٰلِمُونَ","fa":"آیا در دل هایشان بیماری [نفاق] است یا [در دین خدا] شک کرده اند یا می ترسند که خدا و پیامبرش بر آنان ستم کند؟ [چنین نیست] بلکه اینان خود ستمکارند."},{"s":"سُورَةُ النُّورِ","n":60,"ar":"وَٱلْقَوَٰعِدُ مِنَ ٱلنِّسَآءِ ٱلَّٰتِى لَا يَرْجُونَ نِكَاحًۭا فَلَيْسَ عَلَيْهِنَّ جُنَاحٌ أَن يَضَعْنَ ثِيَابَهُنَّ غَيْرَ مُتَبَرِّجَٰتٍۭ بِزِينَةٍۢ ۖ وَأَن يَسْتَعْفِفْنَ خَيْرٌۭ لَّهُنَّ ۗ وَٱللَّهُ سَمِيعٌ عَلِيمٌۭ","fa":"و بر زنان از کار افتاده ای که امید ازدواجی ندارند، گناهی نیست که حجاب و روپوش خود را کنار بگذارند، در صورتی که با زیور و آرایش خویش قصد خودآرایی نداشته باشند. و پاکدامنی برای آنان بهتر است؛ و خدا شنوا و داناست."},{"s":"سُورَةُ الفُرۡقَانِ","n":6,"ar":"قُلْ أَنزَلَهُ ٱلَّذِى يَعْلَمُ ٱلسِّرَّ فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ ۚ إِنَّهُۥ كَانَ غَفُورًۭا رَّحِيمًۭا","fa":"بگو: آن را کسی نازل کرده است که همه نهان ها را در آسمان ها و زمین می داند، همانا او همواره بسیار آمرزنده و مهربان است."},{"s":"سُورَةُ الفُرۡقَانِ","n":16,"ar":"لَّهُمْ فِيهَا مَا يَشَآءُونَ خَٰلِدِينَ ۚ كَانَ عَلَىٰ رَبِّكَ وَعْدًۭا مَّسْـُٔولًۭا","fa":"در آنجا هر چه بخواهند در حالی که جاودانه اند برای آنان فراهم است، این بر عهده پروردگارت وعده ای است درخواست شده [و مورد انتظار اهل ایمان از خدای بخشنده و کریم.]"},{"s":"سُورَةُ الفُرۡقَانِ","n":26,"ar":"ٱلْمُلْكُ يَوْمَئِذٍ ٱلْحَقُّ لِلرَّحْمَٰنِ ۚ وَكَانَ يَوْمًا عَلَى ٱلْكَٰفِرِينَ عَسِيرًۭا","fa":"در آن روز فرمانروایی مطلق برای [خدای] رحمان ثابت است، و بر کافران روزی بسیار دشوار است،"},{"s":"سُورَةُ الفُرۡقَانِ","n":36,"ar":"فَقُلْنَا ٱذْهَبَآ إِلَى ٱلْقَوْمِ ٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَٰتِنَا فَدَمَّرْنَٰهُمْ تَدْمِيرًۭا","fa":"پس گفتیم: هر دو به سوی گروهی که آیات ما را تکذیب کردند، بروید. [آن گروه در برابر حق لجاجت و تکبّر ورزیدند] در نتیجه آنان را به شدت درهم کوبیده و هلاک کردیم."},{"s":"سُورَةُ الفُرۡقَانِ","n":46,"ar":"ثُمَّ قَبَضْنَٰهُ إِلَيْنَا قَبْضًۭا يَسِيرًۭا","fa":"سپس آن را [با بلند شدن آفتاب] اندک اندک به سوی خود باز می گیریم."},{"s":"سُورَةُ الفُرۡقَانِ","n":56,"ar":"وَمَآ أَرْسَلْنَٰكَ إِلَّا مُبَشِّرًۭا وَنَذِيرًۭا","fa":"تو را جز مژده رسان و بیم دهنده نفرستادیم."},{"s":"سُورَةُ الفُرۡقَانِ","n":66,"ar":"إِنَّهَا سَآءَتْ مُسْتَقَرًّۭا وَمُقَامًۭا","fa":"قطعاً دوزخ بد قرارگاه و بد اقامت گاهی است."},{"s":"سُورَةُ الفُرۡقَانِ","n":76,"ar":"خَٰلِدِينَ فِيهَا ۚ حَسُنَتْ مُسْتَقَرًّۭا وَمُقَامًۭا","fa":"در آنجا جاودانه اند. نیکو قرارگاه و خوب اقامت گاهی است."},{"s":"سُورَةُ الشُّعَرَاءِ","n":9,"ar":"وَإِنَّ رَبَّكَ لَهُوَ ٱلْعَزِيزُ ٱلرَّحِيمُ","fa":"و یقیناً پروردگارت همان توانای شکست ناپذیر مهربان است."},{"s":"سُورَةُ الشُّعَرَاءِ","n":19,"ar":"وَفَعَلْتَ فَعْلَتَكَ ٱلَّتِى فَعَلْتَ وَأَنتَ مِنَ ٱلْكَٰفِرِينَ","fa":"و آن کارت را که کردی، کردی در حالی که از ناسپاسان [زحمات و نعمت های ما] بودی."},{"s":"سُورَةُ الشُّعَرَاءِ","n":29,"ar":"قَالَ لَئِنِ ٱتَّخَذْتَ إِلَٰهًا غَيْرِى لَأَجْعَلَنَّكَ مِنَ ٱلْمَسْجُونِينَ","fa":"[فرعون] گفت: اگر معبودی جز من بگیری، قطعاً تو را از زندانیان [که زیر سخت ترین شکنجه اند] قرار خواهم داد."},{"s":"سُورَةُ الشُّعَرَاءِ","n":39,"ar":"وَقِيلَ لِلنَّاسِ هَلْ أَنتُم مُّجْتَمِعُونَ","fa":"و به همه مردم گفتند: آیا شما هم اجتماع خواهید کرد؟"},{"s":"سُورَةُ الشُّعَرَاءِ","n":49,"ar":"قَالَ ءَامَنتُمْ لَهُۥ قَبْلَ أَنْ ءَاذَنَ لَكُمْ ۖ إِنَّهُۥ لَكَبِيرُكُمُ ٱلَّذِى عَلَّمَكُمُ ٱلسِّحْرَ فَلَسَوْفَ تَعْلَمُونَ ۚ لَأُقَطِّعَنَّ أَيْدِيَكُمْ وَأَرْجُلَكُم مِّنْ خِلَٰفٍۢ وَلَأُصَلِّبَنَّكُمْ أَجْمَعِينَ","fa":"فرعون گفت: پیش از آنکه به شما اجازه دهم به او ایمان آوردید، حتماً او بزرگ شماست که جادوگری را به شما آموخته است، پس به زودی خواهید دانست که مسلماً دست ها و پاهای شما را یکی از راست و یکی از چپ قطع خواهم کرد، و یقیناً همه شما را به دار خواهم آویخت."},{"s":"سُورَةُ الشُّعَرَاءِ","n":59,"ar":"كَذَٰلِكَ وَأَوْرَثْنَٰهَا بَنِىٓ إِسْرَٰٓءِيلَ","fa":"این گونه [نعمت های خود را از چنگ آنان بیرون آوردیم] و آنها را به بنی اسرائیل به میراث دادیم."},{"s":"سُورَةُ الشُّعَرَاءِ","n":69,"ar":"وَٱتْلُ عَلَيْهِمْ نَبَأَ إِبْرَٰهِيمَ","fa":"و سرگذشت مهم ابراهیم را بر آنان بخوان،"},{"s":"سُورَةُ الشُّعَرَاءِ","n":79,"ar":"وَٱلَّذِى هُوَ يُطْعِمُنِى وَيَسْقِينِ","fa":"و آنکه او طعامم می دهد و سیرابم می کند"},{"s":"سُورَةُ الشُّعَرَاءِ","n":89,"ar":"إِلَّا مَنْ أَتَى ٱللَّهَ بِقَلْبٍۢ سَلِيمٍۢ","fa":"مگر کسی که دلی سالم [از رذایل وخبایث] به پیشگاه خدا بیاورد،"},{"s":"سُورَةُ الشُّعَرَاءِ","n":99,"ar":"وَمَآ أَضَلَّنَآ إِلَّا ٱلْمُجْرِمُونَ","fa":"و ما را جز مجرمان [خائن] گمراه نکردند،"},{"s":"سُورَةُ الشُّعَرَاءِ","n":109,"ar":"وَمَآ أَسْـَٔلُكُمْ عَلَيْهِ مِنْ أَجْرٍ ۖ إِنْ أَجْرِىَ إِلَّا عَلَىٰ رَبِّ ٱلْعَٰلَمِينَ","fa":"و من از شما بر ابلاغ رسالتم هیچ پاداشی نمی خواهم، پاداش من فقط بر عهده پروردگار جهانیان است،"},{"s":"سُورَةُ الشُّعَرَاءِ","n":119,"ar":"فَأَنجَيْنَٰهُ وَمَن مَّعَهُۥ فِى ٱلْفُلْكِ ٱلْمَشْحُونِ","fa":"پس او و کسانی را که با او در آن کشتی مملو [از سرنشینان، جنبندگان، متاع و ابزار] بود نجات دادیم،"},{"s":"سُورَةُ الشُّعَرَاءِ","n":129,"ar":"وَتَتَّخِذُونَ مَصَانِعَ لَعَلَّكُمْ تَخْلُدُونَ","fa":"و قلعه ها و کاخ های استوار و مجلل برمی گیرید، که شاید جاودانه بمانید؟"},{"s":"سُورَةُ الشُّعَرَاءِ","n":139,"ar":"فَكَذَّبُوهُ فَأَهْلَكْنَٰهُمْ ۗ إِنَّ فِى ذَٰلِكَ لَءَايَةًۭ ۖ وَمَا كَانَ أَكْثَرُهُم مُّؤْمِنِينَ","fa":"پس او را تکذیب کردند، و در نتیجه هلاکشان کردیم. بی تردید در این سرگذشت عبرتی بزرگ وجود دارد و [قوم هود] بیشترشان مؤمن نبودند،"},{"s":"سُورَةُ الشُّعَرَاءِ","n":149,"ar":"وَتَنْحِتُونَ مِنَ ٱلْجِبَالِ بُيُوتًۭا فَٰرِهِينَ","fa":"و ماهرانه و هنرمندانه از کوه ها خانه هایی می تراشید؟ [به امید آنکه از هر آسیبی حتی مرگ در امان بمانید!!]"},{"s":"سُورَةُ الشُّعَرَاءِ","n":159,"ar":"وَإِنَّ رَبَّكَ لَهُوَ ٱلْعَزِيزُ ٱلرَّحِيمُ","fa":"و یقیناً پروردگارت همان توانای شکست ناپذیر و مهرباناست."},{"s":"سُورَةُ الشُّعَرَاءِ","n":169,"ar":"رَبِّ نَجِّنِى وَأَهْلِى مِمَّا يَعْمَلُونَ","fa":"پروردگارا! مرا و خانواده ام را [از آثار، وزر و وبال] آنچه انجام می دهند، نجات بده؛"},{"s":"سُورَةُ الشُّعَرَاءِ","n":179,"ar":"فَٱتَّقُوا۟ ٱللَّهَ وَأَطِيعُونِ","fa":"بنابراین از خدا پروا کنید و از من فرمان ببرید،"},{"s":"سُورَةُ الشُّعَرَاءِ","n":189,"ar":"فَكَذَّبُوهُ فَأَخَذَهُمْ عَذَابُ يَوْمِ ٱلظُّلَّةِ ۚ إِنَّهُۥ كَانَ عَذَابَ يَوْمٍ عَظِيمٍ","fa":"پس او را تکذیب کردند؛ در نتیجه عذاب روز سایبان [یعنی روزی که ابری تیره و صاعقه زا سایه می اندازد] آنان را فرا گرفت، همانا آن عذاب روزی بزرگ بود،"},{"s":"سُورَةُ الشُّعَرَاءِ","n":199,"ar":"فَقَرَأَهُۥ عَلَيْهِم مَّا كَانُوا۟ بِهِۦ مُؤْمِنِينَ","fa":"و او آن را بر عرب ها می خواند، باز هم به آن ایمان نمی آوردند!!"},{"s":"سُورَةُ الشُّعَرَاءِ","n":209,"ar":"ذِكْرَىٰ وَمَا كُنَّا ظَٰلِمِينَ","fa":"برای اندرز دادن و اتمام حجت؛ و ما هرگز ستمکار نبوده ایم [که مردمی را بدون فرستادن پیامبر نابود کنیم.]"},{"s":"سُورَةُ الشُّعَرَاءِ","n":219,"ar":"وَتَقَلُّبَكَ فِى ٱلسَّٰجِدِينَ","fa":"و گردش و حرکت تو را در میان سجده کنندگان [مشاهده می کند،]"},{"s":"سُورَةُ النَّمۡلِ","n":2,"ar":"هُدًۭى وَبُشْرَىٰ لِلْمُؤْمِنِينَ","fa":"[که سراسر] هدایت کننده [انسان ها] و برای مؤمنان مژده دهنده است."},{"s":"سُورَةُ النَّمۡلِ","n":12,"ar":"وَأَدْخِلْ يَدَكَ فِى جَيْبِكَ تَخْرُجْ بَيْضَآءَ مِنْ غَيْرِ سُوٓءٍۢ ۖ فِى تِسْعِ ءَايَٰتٍ إِلَىٰ فِرْعَوْنَ وَقَوْمِهِۦٓ ۚ إِنَّهُمْ كَانُوا۟ قَوْمًۭا فَٰسِقِينَ","fa":"و دستت را در گریبانت کن تا بدون هیچ عیبی، سفید و درخشان بیرون آید، [با این دو معجزه که در ضمن] نه معجزه است به سوی فرعون و قومش [برو] که قطعاً آنان گروهی نافرمانند؛"},{"s":"سُورَةُ النَّمۡلِ","n":22,"ar":"فَمَكَثَ غَيْرَ بَعِيدٍۢ فَقَالَ أَحَطتُ بِمَا لَمْ تُحِطْ بِهِۦ وَجِئْتُكَ مِن سَبَإٍۭ بِنَبَإٍۢ يَقِينٍ","fa":"پس [هدهد] زمانی نه چندان دور درنگ کرد [و با شتاب بازگشت،] پس گفت: [ای سلیمان!] من به چیزی آگاهی یافته ام که تو به آن آگاهی نیافته ای، و [من] از [سرزمین] سبا خبری مهم و یقینی برایت آورده ام."},{"s":"سُورَةُ النَّمۡلِ","n":32,"ar":"قَالَتْ يَٰٓأَيُّهَا ٱلْمَلَؤُا۟ أَفْتُونِى فِىٓ أَمْرِى مَا كُنتُ قَاطِعَةً أَمْرًا حَتَّىٰ تَشْهَدُونِ","fa":"گفت: ای سران و اشراف! در کارم به من نظر دهید تا شما نزد من حضور داشتید، من [بدون شما] فیصله دهنده کاری نبوده ام."},{"s":"سُورَةُ النَّمۡلِ","n":42,"ar":"فَلَمَّا جَآءَتْ قِيلَ أَهَٰكَذَا عَرْشُكِ ۖ قَالَتْ كَأَنَّهُۥ هُوَ ۚ وَأُوتِينَا ٱلْعِلْمَ مِن قَبْلِهَا وَكُنَّا مُسْلِمِينَ","fa":"پس زمانی که [ملکه سبا] آمد، گفتند: آیا تخت تو نیز این گونه است؟ گفت: گویا این همان است!! و ما را پیش از این [به حقّانیّت و قدرت سلیمان] آگاه کردند و [همان زمان] تسلیم شدیم؛"},{"s":"سُورَةُ النَّمۡلِ","n":52,"ar":"فَتِلْكَ بُيُوتُهُمْ خَاوِيَةًۢ بِمَا ظَلَمُوٓا۟ ۗ إِنَّ فِى ذَٰلِكَ لَءَايَةًۭ لِّقَوْمٍۢ يَعْلَمُونَ","fa":"این خانه های آنان است که به سبب ستمشان [از سکنه] خالی مانده. بی تردید در این سرگذشت برای گروهی که معرفت و شناخت دارند، عبرتی بزرگ وجود دارد،"},{"s":"سُورَةُ النَّمۡلِ","n":62,"ar":"أَمَّن يُجِيبُ ٱلْمُضْطَرَّ إِذَا دَعَاهُ وَيَكْشِفُ ٱلسُّوٓءَ وَيَجْعَلُكُمْ خُلَفَآءَ ٱلْأَرْضِ ۗ أَءِلَٰهٌۭ مَّعَ ٱللَّهِ ۚ قَلِيلًۭا مَّا تَذَكَّرُونَ","fa":"[آیا آن شریکان انتخابی شما بهترند] یا آنکه وقتی درمانده ای او را بخواند اجابت می کند و آسیب و گرفتاریش را دفع می نماید، و شما را جانشینان [دیگران در روی] زمین قرار می دهد؟ آیا با خدا معبودی دیگر هست [که شریک در قدرت و ربوبیت او باشد؟!] اندکی متذکّر و هوشیار می شوند."},{"s":"سُورَةُ النَّمۡلِ","n":72,"ar":"قُلْ عَسَىٰٓ أَن يَكُونَ رَدِفَ لَكُم بَعْضُ ٱلَّذِى تَسْتَعْجِلُونَ","fa":"بگو: امید است بخشی از آن عذابی که رسیدنش را با شتاب می خواهید، دنبال شما باشد،"},{"s":"سُورَةُ النَّمۡلِ","n":82,"ar":"۞ وَإِذَا وَقَعَ ٱلْقَوْلُ عَلَيْهِمْ أَخْرَجْنَا لَهُمْ دَآبَّةًۭ مِّنَ ٱلْأَرْضِ تُكَلِّمُهُمْ أَنَّ ٱلنَّاسَ كَانُوا۟ بِـَٔايَٰتِنَا لَا يُوقِنُونَ","fa":"و هنگامی که [در اوقات پایانی دنیا] وعده عذاب ما بر آنان حتمی و لازم شود، جنبنده ای را از زمین برای آنان بیرون می آوریم که با آنان سخن می گوید [تا به آیات ما وآخرت واصول آن یقین کنند]؛ زیرا مردم پیش از این به آیات ما یقین نداشتند."},{"s":"سُورَةُ النَّمۡلِ","n":92,"ar":"وَأَنْ أَتْلُوَا۟ ٱلْقُرْءَانَ ۖ فَمَنِ ٱهْتَدَىٰ فَإِنَّمَا يَهْتَدِى لِنَفْسِهِۦ ۖ وَمَن ضَلَّ فَقُلْ إِنَّمَآ أَنَا۠ مِنَ ٱلْمُنذِرِينَ","fa":"و اینکه قرآن را بخوانم؛ پس هر که راه یابد فقط به سود خود راه یافته است، و هر که گمراه شود [آثار شوم گمراهی فقط متوجه خود اوست] پس [به مردم] بگو: من فقط از بیم دهندگانم،"},{"s":"سُورَةُ القَصَصِ","n":9,"ar":"وَقَالَتِ ٱمْرَأَتُ فِرْعَوْنَ قُرَّتُ عَيْنٍۢ لِّى وَلَكَ ۖ لَا تَقْتُلُوهُ عَسَىٰٓ أَن يَنفَعَنَآ أَوْ نَتَّخِذَهُۥ وَلَدًۭا وَهُمْ لَا يَشْعُرُونَ","fa":"و همسر فرعون گفت: [این نوزاد] برای من و تو مایه شادمانی و خوشحالی است، او را نکشید، امید است ما را سود دهد، یا وی را به فرزندی خود بگیریم. ولی آنان آگاه نبودند [که دشمنشان را به دست خود می پرورند.]"},{"s":"سُورَةُ القَصَصِ","n":19,"ar":"فَلَمَّآ أَنْ أَرَادَ أَن يَبْطِشَ بِٱلَّذِى هُوَ عَدُوٌّۭ لَّهُمَا قَالَ يَٰمُوسَىٰٓ أَتُرِيدُ أَن تَقْتُلَنِى كَمَا قَتَلْتَ نَفْسًۢا بِٱلْأَمْسِ ۖ إِن تُرِيدُ إِلَّآ أَن تَكُونَ جَبَّارًۭا فِى ٱلْأَرْضِ وَمَا تُرِيدُ أَن تَكُونَ مِنَ ٱلْمُصْلِحِينَ","fa":"هنگامی که خواست با کسی که دشمن هر دوی آنان بود به سختی برخورد کند [و از آن بنی اسرائیلی مظلوم دفاع نماید، مرد ستمدیده با ارزیابی اشتباهش در حقّ موسی به تصور آنکه موسی قصد وی را دارد] گفت: ای موسی! آیا می خواهی مرا بکشی چنان که دیروز یک نفر را کشتی؟ تو می خواهی در این سرزمین فقط یاغی و سرکش باشی، ونمی خواهی از مصلحان به شمار آیی!"},{"s":"سُورَةُ القَصَصِ","n":29,"ar":"۞ فَلَمَّا قَضَىٰ مُوسَى ٱلْأَجَلَ وَسَارَ بِأَهْلِهِۦٓ ءَانَسَ مِن جَانِبِ ٱلطُّورِ نَارًۭا قَالَ لِأَهْلِهِ ٱمْكُثُوٓا۟ إِنِّىٓ ءَانَسْتُ نَارًۭا لَّعَلِّىٓ ءَاتِيكُم مِّنْهَا بِخَبَرٍ أَوْ جَذْوَةٍۢ مِّنَ ٱلنَّارِ لَعَلَّكُمْ تَصْطَلُونَ","fa":"چون موسی آن مدت را به پایان برد و با خانواده اش رهسپار [مصر] شد، از جانب طور آتشی دید، به خانواده اش گفت: درنگ کنید که من آتشی دیدم، [می روم] شاید خبری از آن برای شما بیاورم یا پاره ای از آتش را می آورم تا گرم شوید."},{"s":"سُورَةُ القَصَصِ","n":39,"ar":"وَٱسْتَكْبَرَ هُوَ وَجُنُودُهُۥ فِى ٱلْأَرْضِ بِغَيْرِ ٱلْحَقِّ وَظَنُّوٓا۟ أَنَّهُمْ إِلَيْنَا لَا يُرْجَعُونَ","fa":"او و سپاهیانش به ناحق در زمین سرکشی و تکبّر کردند، و پنداشتند که آنان را به سوی ما بازنمی گردانند،"},{"s":"سُورَةُ القَصَصِ","n":49,"ar":"قُلْ فَأْتُوا۟ بِكِتَٰبٍۢ مِّنْ عِندِ ٱللَّهِ هُوَ أَهْدَىٰ مِنْهُمَآ أَتَّبِعْهُ إِن كُنتُمْ صَٰدِقِينَ","fa":"بگو: [بنا بر ادعای شما چنانچه تورات و قرآن از جانب خدا نیست] اگر راست می گویید کتابی از نزد خدا بیاورید که هدایت کننده تر از این دو باشد تا آن را پیروی کنم."},{"s":"سُورَةُ القَصَصِ","n":59,"ar":"وَمَا كَانَ رَبُّكَ مُهْلِكَ ٱلْقُرَىٰ حَتَّىٰ يَبْعَثَ فِىٓ أُمِّهَا رَسُولًۭا يَتْلُوا۟ عَلَيْهِمْ ءَايَٰتِنَا ۚ وَمَا كُنَّا مُهْلِكِى ٱلْقُرَىٰٓ إِلَّا وَأَهْلُهَا ظَٰلِمُونَ","fa":"و پروردگارت بر آن نبوده است که شهرها را نابود کند، تا آنکه [پیش از نابودی] در مرکز آنها پیامبری برانگیزد که آیات ما را بر آنان بخواند، و ما [در هیچ حالی از احوال] نابودکننده شهرها نبوده ایم مگر در حالی که اهلش ستمکار بوده اند."},{"s":"سُورَةُ القَصَصِ","n":69,"ar":"وَرَبُّكَ يَعْلَمُ مَا تُكِنُّ صُدُورُهُمْ وَمَا يُعْلِنُونَ","fa":"و پروردگارت آنچه را سینه هایشان پنهان می نماید و آنچه را آشکار می کند، می داند"},{"s":"سُورَةُ القَصَصِ","n":79,"ar":"فَخَرَجَ عَلَىٰ قَوْمِهِۦ فِى زِينَتِهِۦ ۖ قَالَ ٱلَّذِينَ يُرِيدُونَ ٱلْحَيَوٰةَ ٱلدُّنْيَا يَٰلَيْتَ لَنَا مِثْلَ مَآ أُوتِىَ قَٰرُونُ إِنَّهُۥ لَذُو حَظٍّ عَظِيمٍۢ","fa":"[قارون] در میان آرایش و زینت خود بر قومش درآمد؛ آنانکه خواهان زندگی دنیا بودند، گفتند: ای کاش مانند آنچه به قارون داده اند برای ما هم بود، واقعاً او دارای بهره بزرگی است."},{"s":"سُورَةُ العَنكَبُوتِ","n":1,"ar":"بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ الٓمٓ","fa":"الم"},{"s":"سُورَةُ العَنكَبُوتِ","n":11,"ar":"وَلَيَعْلَمَنَّ ٱللَّهُ ٱلَّذِينَ ءَامَنُوا۟ وَلَيَعْلَمَنَّ ٱلْمُنَٰفِقِينَ","fa":"و یقیناً خدا کسانی را که ایمان آورده اند، می شناسد و بی تردید منافقان را نیز می شناسد،"},{"s":"سُورَةُ العَنكَبُوتِ","n":21,"ar":"يُعَذِّبُ مَن يَشَآءُ وَيَرْحَمُ مَن يَشَآءُ ۖ وَإِلَيْهِ تُقْلَبُونَ","fa":"هر کس را بخواهد عذاب می کند، و هر کس را بخواهد مورد رحمت قرار می دهد، و فقط به سوی او بازگردانده می شوید."},{"s":"سُورَةُ العَنكَبُوتِ","n":31,"ar":"وَلَمَّا جَآءَتْ رُسُلُنَآ إِبْرَٰهِيمَ بِٱلْبُشْرَىٰ قَالُوٓا۟ إِنَّا مُهْلِكُوٓا۟ أَهْلِ هَٰذِهِ ٱلْقَرْيَةِ ۖ إِنَّ أَهْلَهَا كَانُوا۟ ظَٰلِمِينَ","fa":"و زمانی که فرستادگان ما با بشارت [ولادت اسحاق] نزد ابراهیم آمدند، گفتند: ما یقیناً اهل شهر را نابود می کنیم؛ زیرا اهل آن ستمکارند."},{"s":"سُورَةُ العَنكَبُوتِ","n":41,"ar":"مَثَلُ ٱلَّذِينَ ٱتَّخَذُوا۟ مِن دُونِ ٱللَّهِ أَوْلِيَآءَ كَمَثَلِ ٱلْعَنكَبُوتِ ٱتَّخَذَتْ بَيْتًۭا ۖ وَإِنَّ أَوْهَنَ ٱلْبُيُوتِ لَبَيْتُ ٱلْعَنكَبُوتِ ۖ لَوْ كَانُوا۟ يَعْلَمُونَ","fa":"داستان کسانی که به جای خدا سرپرستانی گرفته اند، مانند داستان عنکبوت است که خانه ای [بی دیوار، بی سقف و بی حفاظ] برای خود بنا کرده باشد، و بی تردید سست ترین خانه ها خانه عنکبوت است، اگر [به این واقعیت] معرفت و شناخت داشتند [بت ها را سرپرستان خود نمی گرفتند.]"},{"s":"سُورَةُ العَنكَبُوتِ","n":51,"ar":"أَوَلَمْ يَكْفِهِمْ أَنَّآ أَنزَلْنَا عَلَيْكَ ٱلْكِتَٰبَ يُتْلَىٰ عَلَيْهِمْ ۚ إِنَّ فِى ذَٰلِكَ لَرَحْمَةًۭ وَذِكْرَىٰ لِقَوْمٍۢ يُؤْمِنُونَ","fa":"آیا [در قرآن عیب و نقصی می یابند؟ و] برای آنان کافی نبوده است که ما این کتاب را که [همواره] بر آنان خوانده می شود بر تو نازل کردیم؟! همانا در این کتاب رحمتی است [ویژه و مایه یادآوری] و پندی برای مردمی که ایمان می آورند."},{"s":"سُورَةُ العَنكَبُوتِ","n":61,"ar":"وَلَئِن سَأَلْتَهُم مَّنْ خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ وَسَخَّرَ ٱلشَّمْسَ وَٱلْقَمَرَ لَيَقُولُنَّ ٱللَّهُ ۖ فَأَنَّىٰ يُؤْفَكُونَ","fa":"اگر از آنان [که شرک می ورزند] بپرسی: چه کسی آسمان ها و زمین را آفریده و خورشید و ماه را رام و مسخّر کرده؟ بی تردید خواهند گفت: خدا. پس چگونه [از حق به باطل] منحرف می شوند؟!"},{"s":"سُورَةُ الرُّومِ","n":2,"ar":"غُلِبَتِ ٱلرُّومُ","fa":"رومیان مغلوب شدند،"},{"s":"سُورَةُ الرُّومِ","n":12,"ar":"وَيَوْمَ تَقُومُ ٱلسَّاعَةُ يُبْلِسُ ٱلْمُجْرِمُونَ","fa":"و روزی که قیامت برپا شود گنهکاران [از شدت سختی و هولناکی آن اندوهگین گردند و به علت پذیرفته نشدن بهانه و عذرشان از رحمت خدا] مأیوس شوند،"},{"s":"سُورَةُ الرُّومِ","n":22,"ar":"وَمِنْ ءَايَٰتِهِۦ خَلْقُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَٱخْتِلَٰفُ أَلْسِنَتِكُمْ وَأَلْوَٰنِكُمْ ۚ إِنَّ فِى ذَٰلِكَ لَءَايَٰتٍۢ لِّلْعَٰلِمِينَ","fa":"و از نشانه های [قدرت و ربوبیت] او آفرینش آسمان ها وزمین و اختلاف و گوناگونی زبان ها و رنگ های شماست؛ بی تردید در این [واقعیات] نشانه هایی است برای دانایان،"},{"s":"سُورَةُ الرُّومِ","n":32,"ar":"مِنَ ٱلَّذِينَ فَرَّقُوا۟ دِينَهُمْ وَكَانُوا۟ شِيَعًۭا ۖ كُلُّ حِزْبٍۭ بِمَا لَدَيْهِمْ فَرِحُونَ","fa":"مشرکانی که دینشان را بخش بخش کردند و [سرانجام] گروه گروه شدند، در حالی که هر گروهی به آنچه [از بخشی از دین] نزد آنان است [به تصور اینکه حق است] شادمانند!"},{"s":"سُورَةُ الرُّومِ","n":42,"ar":"قُلْ سِيرُوا۟ فِى ٱلْأَرْضِ فَٱنظُرُوا۟ كَيْفَ كَانَ عَٰقِبَةُ ٱلَّذِينَ مِن قَبْلُ ۚ كَانَ أَكْثَرُهُم مُّشْرِكِينَ","fa":"بگو: در زمین بگردید پس با تأمل بنگرید که سرانجام کسانی که پیش تر بودند [و مرتکب کار زشت شدند] چگونه بود؟ بیشتر آنان مشرک بودند."},{"s":"سُورَةُ الرُّومِ","n":52,"ar":"فَإِنَّكَ لَا تُسْمِعُ ٱلْمَوْتَىٰ وَلَا تُسْمِعُ ٱلصُّمَّ ٱلدُّعَآءَ إِذَا وَلَّوْا۟ مُدْبِرِينَ","fa":"[اینان که کفر را بر ایمان ترجیح داده اند، مانند مردگان اند] پس تو نمی توانی [دعوتت را] به مردگان بشنوانی و نمی توانی دعوتت را به کران زمانی که پشت کنان روی می گردانند، بشنوانی."},{"s":"سُورَةُ لُقۡمَانَ","n":2,"ar":"تِلْكَ ءَايَٰتُ ٱلْكِتَٰبِ ٱلْحَكِيمِ","fa":"این آیات [با عظمتِ] کتاب محکم و استوار است،"},{"s":"سُورَةُ لُقۡمَانَ","n":12,"ar":"وَلَقَدْ ءَاتَيْنَا لُقْمَٰنَ ٱلْحِكْمَةَ أَنِ ٱشْكُرْ لِلَّهِ ۚ وَمَن يَشْكُرْ فَإِنَّمَا يَشْكُرُ لِنَفْسِهِۦ ۖ وَمَن كَفَرَ فَإِنَّ ٱللَّهَ غَنِىٌّ حَمِيدٌۭ","fa":"و به راستی ما به لقمان حکمت عطا کردیم که نسبت به خدا سپاس گزار و شاکر باش و هرکه سپاس گزارد تنها به سود خود سپاس می گزارد، و هرکه ناسپاسی کند [به خدا زیان نمی زند، زیرا] خدا بی نیاز و ستوده است."},{"s":"سُورَةُ لُقۡمَانَ","n":22,"ar":"۞ وَمَن يُسْلِمْ وَجْهَهُۥٓ إِلَى ٱللَّهِ وَهُوَ مُحْسِنٌۭ فَقَدِ ٱسْتَمْسَكَ بِٱلْعُرْوَةِ ٱلْوُثْقَىٰ ۗ وَإِلَى ٱللَّهِ عَٰقِبَةُ ٱلْأُمُورِ","fa":"و هرکس همه وجود خود را به سوی خدا کند در حالی که نیکوکار باشد بی تردید به محکم ترین دستگیره چنگ زده است؛ و سرانجام و عاقبت همه کارها فقط به سوی خداست."},{"s":"سُورَةُ لُقۡمَانَ","n":32,"ar":"وَإِذَا غَشِيَهُم مَّوْجٌۭ كَٱلظُّلَلِ دَعَوُا۟ ٱللَّهَ مُخْلِصِينَ لَهُ ٱلدِّينَ فَلَمَّا نَجَّىٰهُمْ إِلَى ٱلْبَرِّ فَمِنْهُم مُّقْتَصِدٌۭ ۚ وَمَا يَجْحَدُ بِـَٔايَٰتِنَآ إِلَّا كُلُّ خَتَّارٍۢ كَفُورٍۢ","fa":"و چون آنان را [در دریا] موجی [به دنبال موجی] مانند ابرهای سایه انداز فرو پوشد، خدا را در حالی که ایمان و عبادت را برای او [از هرگونه شرکی] خالص می کنند، می خوانند، و زمانی که آنان را به خشکی می رساند برخی از آنان به راه میانه و معتدل [که راه توحید است] می روند [و برخی پیمان می شکنند] و آیات ما را جز هر پیمان شکن خائن و کفر پیشه ای انکار نمی کند."},{"s":"سُورَةُ السَّجۡدَةِ","n":8,"ar":"ثُمَّ جَعَلَ نَسْلَهُۥ مِن سُلَٰلَةٍۢ مِّن مَّآءٍۢ مَّهِينٍۢ","fa":"سپس نسل او را از چکیده ای از آب پست و بی مقدار قرار داد،"},{"s":"سُورَةُ السَّجۡدَةِ","n":18,"ar":"أَفَمَن كَانَ مُؤْمِنًۭا كَمَن كَانَ فَاسِقًۭا ۚ لَّا يَسْتَوُۥنَ","fa":"با این حال آیا کسانی که مؤمن اند مانند کسانی هستند که فاسق اند؟ [نه هرگز این دو گروه] مساوی و یکسان نیستند."},{"s":"سُورَةُ السَّجۡدَةِ","n":28,"ar":"وَيَقُولُونَ مَتَىٰ هَٰذَا ٱلْفَتْحُ إِن كُنتُمْ صَٰدِقِينَ","fa":"و [مشرکان از روی مسخره به مؤمنان] می گویند: اگر راست می گویید این فتح و پیروزی [که به خود وعده می دهید و به آن دلخوش هستید] کی خواهد بود؟"},{"s":"سُورَةُ الأَحۡزَابِ","n":8,"ar":"لِّيَسْـَٔلَ ٱلصَّٰدِقِينَ عَن صِدْقِهِمْ ۚ وَأَعَدَّ لِلْكَٰفِرِينَ عَذَابًا أَلِيمًۭا","fa":"تا صادقان را از صدقشان بپرسد [و پاداش صدقشان را به آنان عطا کند] و برای کافران عذابی دردناک آماده کرده است."},{"s":"سُورَةُ الأَحۡزَابِ","n":18,"ar":"۞ قَدْ يَعْلَمُ ٱللَّهُ ٱلْمُعَوِّقِينَ مِنكُمْ وَٱلْقَآئِلِينَ لِإِخْوَٰنِهِمْ هَلُمَّ إِلَيْنَا ۖ وَلَا يَأْتُونَ ٱلْبَأْسَ إِلَّا قَلِيلًا","fa":"یقیناً خدا بازدارندگان را از میان شما [که مجاهدان را با وسوسه و اغواگری از شرکت در جهاد باز می دارند] و کسانی را که به برادرانشان [آن براداران دینی که ایمانشان سست است] می گویند: [برای عیش و نوش] به سوی ما بیایید [شما را به شرکت در جهاد چه کار؟] می شناسد؛ و جز اندکی به جهاد نمی آیند."},{"s":"سُورَةُ الأَحۡزَابِ","n":28,"ar":"يَٰٓأَيُّهَا ٱلنَّبِىُّ قُل لِّأَزْوَٰجِكَ إِن كُنتُنَّ تُرِدْنَ ٱلْحَيَوٰةَ ٱلدُّنْيَا وَزِينَتَهَا فَتَعَالَيْنَ أُمَتِّعْكُنَّ وَأُسَرِّحْكُنَّ سَرَاحًۭا جَمِيلًۭا","fa":"ای پیامبر! به همسرانت بگو: اگر شما زندگی دنیا و زیور و زینتش را می خواهید بیایید تا برخوردارتان نمایم و با روشی پسندیده رهایتان کنم،"},{"s":"سُورَةُ الأَحۡزَابِ","n":38,"ar":"مَّا كَانَ عَلَى ٱلنَّبِىِّ مِنْ حَرَجٍۢ فِيمَا فَرَضَ ٱللَّهُ لَهُۥ ۖ سُنَّةَ ٱللَّهِ فِى ٱلَّذِينَ خَلَوْا۟ مِن قَبْلُ ۚ وَكَانَ أَمْرُ ٱللَّهِ قَدَرًۭا مَّقْدُورًا","fa":"بر پیامبر در آنچه خدا برای او مقرّر و لازم کرده منعی نیست، خدا این روش را درباره کسانی [از پیامبران] که پیش از این گذشته اند مقرّر داشته است و همواره فرمان خدا نافذ و اندازه گیری شده است."},{"s":"سُورَةُ الأَحۡزَابِ","n":48,"ar":"وَلَا تُطِعِ ٱلْكَٰفِرِينَ وَٱلْمُنَٰفِقِينَ وَدَعْ أَذَىٰهُمْ وَتَوَكَّلْ عَلَى ٱللَّهِ ۚ وَكَفَىٰ بِٱللَّهِ وَكِيلًۭا","fa":"و از کافران و منافقان اطاعت مکن و آزارشان را واگذار و بر خدا توکل کن، و کافی است که خدا نگهبان و کارساز [انسان] باشد،"},{"s":"سُورَةُ الأَحۡزَابِ","n":58,"ar":"وَٱلَّذِينَ يُؤْذُونَ ٱلْمُؤْمِنِينَ وَٱلْمُؤْمِنَٰتِ بِغَيْرِ مَا ٱكْتَسَبُوا۟ فَقَدِ ٱحْتَمَلُوا۟ بُهْتَٰنًۭا وَإِثْمًۭا مُّبِينًۭا","fa":"و کسانی که مردان و زنان مؤمن را [با متهم کردن] به اعمالی که انجام نداده اند، می آزارند، بی تردید بهتان و گناه بزرگی بر عهده گرفته اند."},{"s":"سُورَةُ الأَحۡزَابِ","n":68,"ar":"رَبَّنَآ ءَاتِهِمْ ضِعْفَيْنِ مِنَ ٱلْعَذَابِ وَٱلْعَنْهُمْ لَعْنًۭا كَبِيرًۭا","fa":"پروردگارا! آنان را از عذاب دو چندان ده، و کاملاً از رحمتت دورشان ساز."},{"s":"سُورَةُ سَبَإٍ","n":5,"ar":"وَٱلَّذِينَ سَعَوْ فِىٓ ءَايَٰتِنَا مُعَٰجِزِينَ أُو۟لَٰٓئِكَ لَهُمْ عَذَابٌۭ مِّن رِّجْزٍ أَلِيمٌۭ","fa":"و کسانی که در [انکار و تکذیب] آیات ما کوشیدند، به گمان اینکه [می توانند] ما را عاجز کنند [تا از دسترس قدرت ما بیرون روند] برای آنان عذابی دردناک از سخت ترین عذاب هاست."},{"s":"سُورَةُ سَبَإٍ","n":15,"ar":"لَقَدْ كَانَ لِسَبَإٍۢ فِى مَسْكَنِهِمْ ءَايَةٌۭ ۖ جَنَّتَانِ عَن يَمِينٍۢ وَشِمَالٍۢ ۖ كُلُوا۟ مِن رِّزْقِ رَبِّكُمْ وَٱشْكُرُوا۟ لَهُۥ ۚ بَلْدَةٌۭ طَيِّبَةٌۭ وَرَبٌّ غَفُورٌۭ","fa":"یقیناً برای قوم سبا در جای اقامتشان نشانه ای [از قدرت و رحمت خدا] وجود داشت، دو باغ از طرف راست و چپ. [گفتیم:] از رزق و روزی پروردگارتان بخورید، و برای او سپاس گزاری کنید، سرزمینی خوش و دلپذیر [دارید]، و پروردگاری بسیار آمرزنده"},{"s":"سُورَةُ سَبَإٍ","n":25,"ar":"قُل لَّا تُسْـَٔلُونَ عَمَّآ أَجْرَمْنَا وَلَا نُسْـَٔلُ عَمَّا تَعْمَلُونَ","fa":"بگو: شما از گناه ما بازخواست نخواهید شد، و ما هم از آنچه شما انجام می دهید، بازخواست نخواهیم شد."},{"s":"سُورَةُ سَبَإٍ","n":35,"ar":"وَقَالُوا۟ نَحْنُ أَكْثَرُ أَمْوَٰلًۭا وَأَوْلَٰدًۭا وَمَا نَحْنُ بِمُعَذَّبِينَ","fa":"و گفتند: اموال و فرزندان ما از شما بیشتر است و [این دلیل توجه ویژه خدا به ماست؛ بنابراین اگر عذابی هم باشد] ما را عذاب نخواهند کرد."},{"s":"سُورَةُ سَبَإٍ","n":45,"ar":"وَكَذَّبَ ٱلَّذِينَ مِن قَبْلِهِمْ وَمَا بَلَغُوا۟ مِعْشَارَ مَآ ءَاتَيْنَٰهُمْ فَكَذَّبُوا۟ رُسُلِى ۖ فَكَيْفَ كَانَ نَكِيرِ","fa":"و کسانی که پیش از اینان بودند [آیات ما و پیامبران را] تکذیب کردند، و اینان به یک دهم قدرت و ثروتی که به آنان داده بودیم، نرسیده اند، پس پیامبرانم را تکذیب کردند [در نتیجه هلاکشان کردیم]؛ پس [بنگر] عذاب من چگونه بود؟"},{"s":"سُورَةُ فَاطِرٍ","n":1,"ar":"بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ ٱلْحَمْدُ لِلَّهِ فَاطِرِ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ جَاعِلِ ٱلْمَلَٰٓئِكَةِ رُسُلًا أُو۟لِىٓ أَجْنِحَةٍۢ مَّثْنَىٰ وَثُلَٰثَ وَرُبَٰعَ ۚ يَزِيدُ فِى ٱلْخَلْقِ مَا يَشَآءُ ۚ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَىْءٍۢ قَدِيرٌۭ","fa":"همه ستایش ها ویژه خداست که آفریننده آسمان ها و زمین است [و] فرشتگان را که دارای بالهایی دوگانه و سه گانه و چهارگانه اند رسولانی [برای انجام دادن فرمان های تکوینی و تشریعی اش] قرار داده است. هرچه بخواهد در آفرینش می افزاید؛ یقیناً خدا بر هر کاری تواناست."},{"s":"سُورَةُ فَاطِرٍ","n":11,"ar":"وَٱللَّهُ خَلَقَكُم مِّن تُرَابٍۢ ثُمَّ مِن نُّطْفَةٍۢ ثُمَّ جَعَلَكُمْ أَزْوَٰجًۭا ۚ وَمَا تَحْمِلُ مِنْ أُنثَىٰ وَلَا تَضَعُ إِلَّا بِعِلْمِهِۦ ۚ وَمَا يُعَمَّرُ مِن مُّعَمَّرٍۢ وَلَا يُنقَصُ مِنْ عُمُرِهِۦٓ إِلَّا فِى كِتَٰبٍ ۚ إِنَّ ذَٰلِكَ عَلَى ٱللَّهِ يَسِيرٌۭ","fa":"و خدا شما را از خاک [مرده]، سپس از نطفه آفرید، آن گاه شما را زوج هایی [نر و ماده] قرار داد. هیچ ماده ای باردار نمی شود و بارش را نمی نهد مگر به علم او، و هیچ کس عمر طولانی نمی کند واز عمرش کاسته نمی شود مگر اینکه در کتابی [چون لوح محفوظ] ثبت است. بی تردید این [کارها] بر خدا آسان است."},{"s":"سُورَةُ فَاطِرٍ","n":21,"ar":"وَلَا ٱلظِّلُّ وَلَا ٱلْحَرُورُ","fa":"و نه سایه و نه باد گرم سوزان،"},{"s":"سُورَةُ فَاطِرٍ","n":31,"ar":"وَٱلَّذِىٓ أَوْحَيْنَآ إِلَيْكَ مِنَ ٱلْكِتَٰبِ هُوَ ٱلْحَقُّ مُصَدِّقًۭا لِّمَا بَيْنَ يَدَيْهِ ۗ إِنَّ ٱللَّهَ بِعِبَادِهِۦ لَخَبِيرٌۢ بَصِيرٌۭ","fa":"و آنچه از کتاب به تو وحی کرده ایم، همان حق است، [و] تصدیق کننده [کتاب هایی که] پیش از آن بوده است؛ یقیناً خدا به بندگانش آگاه و بیناست."},{"s":"سُورَةُ فَاطِرٍ","n":41,"ar":"۞ إِنَّ ٱللَّهَ يُمْسِكُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ أَن تَزُولَا ۚ وَلَئِن زَالَتَآ إِنْ أَمْسَكَهُمَا مِنْ أَحَدٍۢ مِّنۢ بَعْدِهِۦٓ ۚ إِنَّهُۥ كَانَ حَلِيمًا غَفُورًۭا","fa":"یقیناً خدا آسمان ها و زمین را از اینکه از جای خود منحرف شوند [و فرو ریزند] نگه می دارد. و اگر منحرف شوند هیچ کس بعد از او نمی تواند نگاهشان دارد؛ مسلماً خدا همواره بردبار و بسیار آمرزنده است."},{"s":"سُورَةُ يسٓ","n":6,"ar":"لِتُنذِرَ قَوْمًۭا مَّآ أُنذِرَ ءَابَآؤُهُمْ فَهُمْ غَٰفِلُونَ","fa":"تا مردمی را بیم دهی که پدرانشان را بیم نداده اند و به این علت [از حقایق] بی خبرند."},{"s":"سُورَةُ يسٓ","n":16,"ar":"قَالُوا۟ رَبُّنَا يَعْلَمُ إِنَّآ إِلَيْكُمْ لَمُرْسَلُونَ","fa":"گفتند: پروردگارمان می داند که یقیناً ما به سوی شما فرستاده شده ایم،"},{"s":"سُورَةُ يسٓ","n":26,"ar":"قِيلَ ٱدْخُلِ ٱلْجَنَّةَ ۖ قَالَ يَٰلَيْتَ قَوْمِى يَعْلَمُونَ","fa":"[سرانجام به دست آن مشرکان شهید شد، و به او] گفته شد: به بهشت درآی. گفت: ای کاش قوم من معرفت و آگاهی داشتند،"},{"s":"سُورَةُ يسٓ","n":36,"ar":"سُبْحَٰنَ ٱلَّذِى خَلَقَ ٱلْأَزْوَٰجَ كُلَّهَا مِمَّا تُنۢبِتُ ٱلْأَرْضُ وَمِنْ أَنفُسِهِمْ وَمِمَّا لَا يَعْلَمُونَ","fa":"منزّه [از هر عیب و نقصی] است آنکه همه زوج ها را آفرید از آنچه زمین می رویاند و از وجود خودشان و از آنچه نمی دانند،"},{"s":"سُورَةُ يسٓ","n":46,"ar":"وَمَا تَأْتِيهِم مِّنْ ءَايَةٍۢ مِّنْ ءَايَٰتِ رَبِّهِمْ إِلَّا كَانُوا۟ عَنْهَا مُعْرِضِينَ","fa":"و هیچ آیه ای از آیات پروردگارشان برای آنان نمی آید مگر اینکه از آن روی می گردانند."},{"s":"سُورَةُ يسٓ","n":56,"ar":"هُمْ وَأَزْوَٰجُهُمْ فِى ظِلَٰلٍ عَلَى ٱلْأَرَآئِكِ مُتَّكِـُٔونَ","fa":"آنان و همسرانشان در زیر سایه هایی [آرام بخش] بر تخت هایی [آراسته چون حجله عروس] تکیه می زنند."},{"s":"سُورَةُ يسٓ","n":66,"ar":"وَلَوْ نَشَآءُ لَطَمَسْنَا عَلَىٰٓ أَعْيُنِهِمْ فَٱسْتَبَقُوا۟ ٱلصِّرَٰطَ فَأَنَّىٰ يُبْصِرُونَ","fa":"و اگر بخواهیم [در همین دنیا] دیدگانشان را محو می کنیم، پس به [سوی همان] راه [گمراهی] بر یکدیگر پیشی می گیرند؛ نهایتاً چگونه و کجا می توانند [صراط مستقیم را] ببینند؟"},{"s":"سُورَةُ يسٓ","n":76,"ar":"فَلَا يَحْزُنكَ قَوْلُهُمْ ۘ إِنَّا نَعْلَمُ مَا يُسِرُّونَ وَمَا يُعْلِنُونَ","fa":"پس گفتارشان تو را اندوهگین نکند، بی تردید ما آنچه را پنهان می دارند و آنچه را آشکار می کنند، می دانیم."},{"s":"سُورَةُ الصَّافَّاتِ","n":3,"ar":"فَٱلتَّٰلِيَٰتِ ذِكْرًا","fa":"و به تلاوت کنندگان وحی،"},{"s":"سُورَةُ الصَّافَّاتِ","n":13,"ar":"وَإِذَا ذُكِّرُوا۟ لَا يَذْكُرُونَ","fa":"و هنگامی که به آنان تذکر، می دهند متذکّر نمی شوند؛"},{"s":"سُورَةُ الصَّافَّاتِ","n":23,"ar":"مِن دُونِ ٱللَّهِ فَٱهْدُوهُمْ إِلَىٰ صِرَٰطِ ٱلْجَحِيمِ","fa":"پس همه را به سوی راه دوزخ راهنمایی کنید."},{"s":"سُورَةُ الصَّافَّاتِ","n":33,"ar":"فَإِنَّهُمْ يَوْمَئِذٍۢ فِى ٱلْعَذَابِ مُشْتَرِكُونَ","fa":"پس بی تردید همه 2آنان در آن روز در عذاب شریک اند،"},{"s":"سُورَةُ الصَّافَّاتِ","n":43,"ar":"فِى جَنَّٰتِ ٱلنَّعِيمِ","fa":"در بهشت های پر نعمت،"},{"s":"سُورَةُ الصَّافَّاتِ","n":53,"ar":"أَءِذَا مِتْنَا وَكُنَّا تُرَابًۭا وَعِظَٰمًا أَءِنَّا لَمَدِينُونَ","fa":"آیا زمانی که ما مردیم و خاک استخوان شدیم، حتماً [زنده می شویم و] پاداشمان می دهند؟"},{"s":"سُورَةُ الصَّافَّاتِ","n":63,"ar":"إِنَّا جَعَلْنَٰهَا فِتْنَةًۭ لِّلظَّٰلِمِينَ","fa":"ما آن را برای ستمکاران مایه شکنجه و عذاب قرار داده ایم."},{"s":"سُورَةُ الصَّافَّاتِ","n":73,"ar":"فَٱنظُرْ كَيْفَ كَانَ عَٰقِبَةُ ٱلْمُنذَرِينَ","fa":"پس با تأمل بنگر سرانجام بیم داده شدگان چگونه بود؟"},{"s":"سُورَةُ الصَّافَّاتِ","n":83,"ar":"۞ وَإِنَّ مِن شِيعَتِهِۦ لَإِبْرَٰهِيمَ","fa":"و به راستی ابراهیم از پیروان نوح بود،"},{"s":"سُورَةُ الصَّافَّاتِ","n":93,"ar":"فَرَاغَ عَلَيْهِمْ ضَرْبًۢا بِٱلْيَمِينِ","fa":"پس [به آنها روی آورد و] با دست راست ضربه ای کاری بر آنها کوبید [و خردشان کرد.]"},{"s":"سُورَةُ الصَّافَّاتِ","n":103,"ar":"فَلَمَّآ أَسْلَمَا وَتَلَّهُۥ لِلْجَبِينِ","fa":"پس هنگامی که آن دو تسلیم [خواسته خدا] شدند و ابراهیم، جبین او را به زمین نهاد [تا ذبحش کند]"},{"s":"سُورَةُ الصَّافَّاتِ","n":113,"ar":"وَبَٰرَكْنَا عَلَيْهِ وَعَلَىٰٓ إِسْحَٰقَ ۚ وَمِن ذُرِّيَّتِهِمَا مُحْسِنٌۭ وَظَالِمٌۭ لِّنَفْسِهِۦ مُبِينٌۭ","fa":"و بر او و بر اسحاق برکت دادیم، و از دودمان آن دو برخی نیکوکارند و برخی آشکارا ستمکار بر خویشند،"},{"s":"سُورَةُ الصَّافَّاتِ","n":123,"ar":"وَإِنَّ إِلْيَاسَ لَمِنَ ٱلْمُرْسَلِينَ","fa":"و بی تردید الیاس از پیامبران بود."},{"s":"سُورَةُ الصَّافَّاتِ","n":133,"ar":"وَإِنَّ لُوطًۭا لَّمِنَ ٱلْمُرْسَلِينَ","fa":"و بی تردید لوط از پیامبران بود."},{"s":"سُورَةُ الصَّافَّاتِ","n":143,"ar":"فَلَوْلَآ أَنَّهُۥ كَانَ مِنَ ٱلْمُسَبِّحِينَ","fa":"[و در شکم ماهی به تسبیح خدا مشغول شد که] اگر او از تسبیح کنندگان نبود،"},{"s":"سُورَةُ الصَّافَّاتِ","n":153,"ar":"أَصْطَفَى ٱلْبَنَاتِ عَلَى ٱلْبَنِينَ","fa":"آیا دختران را بر پسران ترجیح داده است؟"},{"s":"سُورَةُ الصَّافَّاتِ","n":163,"ar":"إِلَّا مَنْ هُوَ صَالِ ٱلْجَحِيمِ","fa":"مگر کسانی را که [به اختیار خود به خاطر پذیرفتن وسوسه و اغواگری شما] به دوزخ درآیند،"},{"s":"سُورَةُ الصَّافَّاتِ","n":173,"ar":"وَإِنَّ جُندَنَا لَهُمُ ٱلْغَٰلِبُونَ","fa":"و مسلماً سپاه ما پیروزند."},{"s":"سُورَةُ صٓ","n":1,"ar":"بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ صٓ ۚ وَٱلْقُرْءَانِ ذِى ٱلذِّكْرِ","fa":"ص، سوگند به قرآن که مشتمل بر ذکر [حقایق، معارف، مطالب اخلاقی و اجتماعی و احکام حلال و حرام] است."},{"s":"سُورَةُ صٓ","n":11,"ar":"جُندٌۭ مَّا هُنَالِكَ مَهْزُومٌۭ مِّنَ ٱلْأَحْزَابِ","fa":"اینان لشکری ناچیز و اندک [از احزاب کفر و شرک] اند که در آنجا [که میدان جنگ بدر است] شکست خوردنی هستند."},{"s":"سُورَةُ صٓ","n":21,"ar":"۞ وَهَلْ أَتَىٰكَ نَبَؤُا۟ ٱلْخَصْمِ إِذْ تَسَوَّرُوا۟ ٱلْمِحْرَابَ","fa":"و آیا خبر مهم آن دادخواهان هنگامی که از دیوار بلند نمازخانه او بالا رفتند به تو رسیده است؟"},{"s":"سُورَةُ صٓ","n":31,"ar":"إِذْ عُرِضَ عَلَيْهِ بِٱلْعَشِىِّ ٱلصَّٰفِنَٰتُ ٱلْجِيَادُ","fa":"[یاد کن] هنگامی را که در پایان روز اسب های چابک و تیزرو بر او عرضه کردند."},{"s":"سُورَةُ صٓ","n":41,"ar":"وَٱذْكُرْ عَبْدَنَآ أَيُّوبَ إِذْ نَادَىٰ رَبَّهُۥٓ أَنِّى مَسَّنِىَ ٱلشَّيْطَٰنُ بِنُصْبٍۢ وَعَذَابٍ","fa":"و بنده ما ایوب را یاد کن، هنگامی که پروردگارش را ندا داد که شیطان [به سبب رنج و شکنجه ای که دچارش هستم] مرا سرزنش و شماتت می کند [تا از رحمت تو دلسردم کند.]"},{"s":"سُورَةُ صٓ","n":51,"ar":"مُتَّكِـِٔينَ فِيهَا يَدْعُونَ فِيهَا بِفَٰكِهَةٍۢ كَثِيرَةٍۢ وَشَرَابٍۢ","fa":"در حالی که در آنجا بر تخت ها تکیه می زنند و میوه های فراوان و نوشیدنی مورد دلخواهشان را در آنجا می طلبند،"},{"s":"سُورَةُ صٓ","n":61,"ar":"قَالُوا۟ رَبَّنَا مَن قَدَّمَ لَنَا هَٰذَا فَزِدْهُ عَذَابًۭا ضِعْفًۭا فِى ٱلنَّارِ","fa":"می گویند: پروردگارا! هر کس این عذاب را از پیش برای ما فراهم آورده است، برای او در آتش عذابی دو چندان بیفزا."},{"s":"سُورَةُ صٓ","n":71,"ar":"إِذْ قَالَ رَبُّكَ لِلْمَلَٰٓئِكَةِ إِنِّى خَٰلِقٌۢ بَشَرًۭا مِّن طِينٍۢ","fa":"[یاد کن] هنگامی را که پروردگارت به فرشتگان گفت: همانا من بشری از گل خواهم آفرید."},{"s":"سُورَةُ صٓ","n":81,"ar":"إِلَىٰ يَوْمِ ٱلْوَقْتِ ٱلْمَعْلُومِ","fa":"تا زمانی معین و معلوم."},{"s":"سُورَةُ الزُّمَرِ","n":3,"ar":"أَلَا لِلَّهِ ٱلدِّينُ ٱلْخَالِصُ ۚ وَٱلَّذِينَ ٱتَّخَذُوا۟ مِن دُونِهِۦٓ أَوْلِيَآءَ مَا نَعْبُدُهُمْ إِلَّا لِيُقَرِّبُونَآ إِلَى ٱللَّهِ زُلْفَىٰٓ إِنَّ ٱللَّهَ يَحْكُمُ بَيْنَهُمْ فِى مَا هُمْ فِيهِ يَخْتَلِفُونَ ۗ إِنَّ ٱللَّهَ لَا يَهْدِى مَنْ هُوَ كَٰذِبٌۭ كَفَّارٌۭ","fa":"آگاه باشید! که دین خالص ویژه خداست، و آنان که به جای خدا سرپرستان و معبودانی برگزیده اند [و می گویند:] ما آنان را جز برای اینکه ما را هر چه بیشتر به خدا نزدیک کنند، نمی پرستیم. بی تردید خدا میان آنان [و مؤمنان] درباره آنچه که اختلاف می کنند [و آن آیین توحید و شرک است] داوری خواهد کرد؛ قطعاً خدا آن کس را که دروغگو و بسیار ناسپاس است، هدایت نمی کند."},{"s":"سُورَةُ الزُّمَرِ","n":13,"ar":"قُلْ إِنِّىٓ أَخَافُ إِنْ عَصَيْتُ رَبِّى عَذَابَ يَوْمٍ عَظِيمٍۢ","fa":"بگو: اگر پروردگارم را نافرمانی کنم از عذاب روزی بزرگ می ترسم."},{"s":"سُورَةُ الزُّمَرِ","n":23,"ar":"ٱللَّهُ نَزَّلَ أَحْسَنَ ٱلْحَدِيثِ كِتَٰبًۭا مُّتَشَٰبِهًۭا مَّثَانِىَ تَقْشَعِرُّ مِنْهُ جُلُودُ ٱلَّذِينَ يَخْشَوْنَ رَبَّهُمْ ثُمَّ تَلِينُ جُلُودُهُمْ وَقُلُوبُهُمْ إِلَىٰ ذِكْرِ ٱللَّهِ ۚ ذَٰلِكَ هُدَى ٱللَّهِ يَهْدِى بِهِۦ مَن يَشَآءُ ۚ وَمَن يُضْلِلِ ٱللَّهُ فَمَا لَهُۥ مِنْ هَادٍ","fa":"خدا نیکوترین سخن را نازل کرد، کتابی که [آیاتش در نظم، زیبایی، فصاحت، بلاغت و عمق محتوا] شبیه یکدیگر است، مشتمل بر داستان های پندآموز [و امر، نهی، وعده، وعید، حلال و حرام] است؛ از شنیدن آیاتش پوست کسانی که از پروردگارشان می هراسند به هم جمع می شود، آن گاه پوستشان و دلشان به یاد خدا نرم می گردد و آرامش می یابد. این هدایت خداست که هر که را بخواهد به آن راهنمایی می کند؛ و هر که را خدا [به کیفر کفر و عنادش] گمراه کند، او را هیچ هدایت کننده ای نخواهد بود."},{"s":"سُورَةُ الزُّمَرِ","n":33,"ar":"وَٱلَّذِى جَآءَ بِٱلصِّدْقِ وَصَدَّقَ بِهِۦٓ ۙ أُو۟لَٰٓئِكَ هُمُ ٱلْمُتَّقُونَ","fa":"و آنکه سخن راست و درست آورد و کسانی که آن را باور کردند، اینانند که پرهیزکارانند."},{"s":"سُورَةُ الزُّمَرِ","n":43,"ar":"أَمِ ٱتَّخَذُوا۟ مِن دُونِ ٱللَّهِ شُفَعَآءَ ۚ قُلْ أَوَلَوْ كَانُوا۟ لَا يَمْلِكُونَ شَيْـًۭٔا وَلَا يَعْقِلُونَ","fa":"[نه اینکه بی خبران، درباره قدرت خدا نمی اندیشند] بلکه به جای خدا [از بتان] شفیعانی برای خود گرفته اند. بگو: آیا [از آنها شفاعت می خواهید] هر چند مالک چیزی [و اختیاردار شفاعتی] نباشند و علم و عقلی نداشته باشند [و پرستندگان خود را نشناسند؟]"},{"s":"سُورَةُ الزُّمَرِ","n":53,"ar":"۞ قُلْ يَٰعِبَادِىَ ٱلَّذِينَ أَسْرَفُوا۟ عَلَىٰٓ أَنفُسِهِمْ لَا تَقْنَطُوا۟ مِن رَّحْمَةِ ٱللَّهِ ۚ إِنَّ ٱللَّهَ يَغْفِرُ ٱلذُّنُوبَ جَمِيعًا ۚ إِنَّهُۥ هُوَ ٱلْغَفُورُ ٱلرَّحِيمُ","fa":"بگو: ای بندگان من که [با ارتکاب گناه] بر خود زیاده روی کردید! از رحمت خدا نومید نشوید، یقیناً خدا همه گناهان را می آمرزد؛ زیرا او بسیار آمرزنده و مهربان است؛"},{"s":"سُورَةُ الزُّمَرِ","n":63,"ar":"لَّهُۥ مَقَالِيدُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ ۗ وَٱلَّذِينَ كَفَرُوا۟ بِـَٔايَٰتِ ٱللَّهِ أُو۟لَٰٓئِكَ هُمُ ٱلْخَٰسِرُونَ","fa":"کلیدهای آسمان ها و زمیندر مالکیّت اوست، و کسانی که به آیات خدا کفر ورزیدند، هم آنان زیانکارند."},{"s":"سُورَةُ الزُّمَرِ","n":73,"ar":"وَسِيقَ ٱلَّذِينَ ٱتَّقَوْا۟ رَبَّهُمْ إِلَى ٱلْجَنَّةِ زُمَرًا ۖ حَتَّىٰٓ إِذَا جَآءُوهَا وَفُتِحَتْ أَبْوَٰبُهَا وَقَالَ لَهُمْ خَزَنَتُهَا سَلَٰمٌ عَلَيْكُمْ طِبْتُمْ فَٱدْخُلُوهَا خَٰلِدِينَ","fa":"و کسانی که از پروردگارشان پروا کردند گروه گروه به بهشت رانده می شوند، چون به آن رسند در حالی که درهایش از پیش گشوده شده است، نگهبانانش به آنان گویند: سلام بر شما، پاکیزه و نیکو شدید، پس وارد آن شوید که [در آن] جاودانه اید."},{"s":"سُورَةُ غَافِرٍ","n":8,"ar":"رَبَّنَا وَأَدْخِلْهُمْ جَنَّٰتِ عَدْنٍ ٱلَّتِى وَعَدتَّهُمْ وَمَن صَلَحَ مِنْ ءَابَآئِهِمْ وَأَزْوَٰجِهِمْ وَذُرِّيَّٰتِهِمْ ۚ إِنَّكَ أَنتَ ٱلْعَزِيزُ ٱلْحَكِيمُ","fa":"پروردگارا! و آنان را در بهشت های جاودانی که به آنان و به شایستگان از پدران و همسران و فرزندانشان وعده داده ای در آور؛ یقیناً تو توانای شکست ناپذیر و حکیمی؛"},{"s":"سُورَةُ غَافِرٍ","n":18,"ar":"وَأَنذِرْهُمْ يَوْمَ ٱلْءَازِفَةِ إِذِ ٱلْقُلُوبُ لَدَى ٱلْحَنَاجِرِ كَٰظِمِينَ ۚ مَا لِلظَّٰلِمِينَ مِنْ حَمِيمٍۢ وَلَا شَفِيعٍۢ يُطَاعُ","fa":"و آنان را از روز نزدیک بیم ده، آن گاه که [از شدت ترس] جان ها به گلوگاه رسد، در حالی که همه وجودشان پر از غم و اندوه است. برای ستمکاران هیچ دوست مهربانی و شفیعی که شفاعتش پذیرفته شود، وجود ندارد!"},{"s":"سُورَةُ غَافِرٍ","n":28,"ar":"وَقَالَ رَجُلٌۭ مُّؤْمِنٌۭ مِّنْ ءَالِ فِرْعَوْنَ يَكْتُمُ إِيمَٰنَهُۥٓ أَتَقْتُلُونَ رَجُلًا أَن يَقُولَ رَبِّىَ ٱللَّهُ وَقَدْ جَآءَكُم بِٱلْبَيِّنَٰتِ مِن رَّبِّكُمْ ۖ وَإِن يَكُ كَٰذِبًۭا فَعَلَيْهِ كَذِبُهُۥ ۖ وَإِن يَكُ صَادِقًۭا يُصِبْكُم بَعْضُ ٱلَّذِى يَعِدُكُمْ ۖ إِنَّ ٱللَّهَ لَا يَهْدِى مَنْ هُوَ مُسْرِفٌۭ كَذَّابٌۭ","fa":"و مرد مؤمنی از خاندان فرعون که ایمانش را پنهان می داشت، گفت: آیا مردی را می کشید که می گوید: پروردگار من خداست؟ و بی تردید از سوی پروردگارتان برای شما دلایل روشنی آورده است، و اگر دروغگو باشد دروغش به زیان خود اوست، و اگر راستگو باشد برخی از عذاب هایی که به شما وعده می دهد به شما خواهد رسید؛ زیرا خدا کسی را که اسراف کار و بسیار دروغگوست، هدایت نمی کند."},{"s":"سُورَةُ غَافِرٍ","n":38,"ar":"وَقَالَ ٱلَّذِىٓ ءَامَنَ يَٰقَوْمِ ٱتَّبِعُونِ أَهْدِكُمْ سَبِيلَ ٱلرَّشَادِ","fa":"و آن مرد مؤمن گفت: ای قوم من! از من پیروی کنید تا شما را به راه راست هدایت کنم."},{"s":"سُورَةُ غَافِرٍ","n":48,"ar":"قَالَ ٱلَّذِينَ ٱسْتَكْبَرُوٓا۟ إِنَّا كُلٌّۭ فِيهَآ إِنَّ ٱللَّهَ قَدْ حَكَمَ بَيْنَ ٱلْعِبَادِ","fa":"مستکبران می گویند: هم اکنون همه ما در آتش هستیم، بی تردید خدا [به عدالت و انصاف] میان بندگان داوری کرده است."},{"s":"سُورَةُ غَافِرٍ","n":58,"ar":"وَمَا يَسْتَوِى ٱلْأَعْمَىٰ وَٱلْبَصِيرُ وَٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ وَلَا ٱلْمُسِىٓءُ ۚ قَلِيلًۭا مَّا تَتَذَكَّرُونَ","fa":"و بینا و نابینا، یکسان نیستند و [نیز] آنان که ایمان آورده و کارهای شایسته انجام داده اند با [مردم] بدکار برابر نمی باشند. اندکی متذکّر [این حقایق] می شوید."},{"s":"سُورَةُ غَافِرٍ","n":68,"ar":"هُوَ ٱلَّذِى يُحْىِۦ وَيُمِيتُ ۖ فَإِذَا قَضَىٰٓ أَمْرًۭا فَإِنَّمَا يَقُولُ لَهُۥ كُن فَيَكُونُ","fa":"اوست که زنده می کند و می میراند، و چون پدید آمدن چیزی را اراده کند، فقط به آن می گوید: باش. پس بی درنگ موجود می شود."},{"s":"سُورَةُ غَافِرٍ","n":78,"ar":"وَلَقَدْ أَرْسَلْنَا رُسُلًۭا مِّن قَبْلِكَ مِنْهُم مَّن قَصَصْنَا عَلَيْكَ وَمِنْهُم مَّن لَّمْ نَقْصُصْ عَلَيْكَ ۗ وَمَا كَانَ لِرَسُولٍ أَن يَأْتِىَ بِـَٔايَةٍ إِلَّا بِإِذْنِ ٱللَّهِ ۚ فَإِذَا جَآءَ أَمْرُ ٱللَّهِ قُضِىَ بِٱلْحَقِّ وَخَسِرَ هُنَالِكَ ٱلْمُبْطِلُونَ","fa":"قطعاً پیش از تو پیامبرانی فرستادیم؛ سرگذشت گروهی از آنان را برای تو حکایت کرده ایم، و سرگذشت برخی را بیان نکرده ایم. هیچ پیامبری را نسزد که جز به اذن خدا معجزه ای بیاورد؛ بنابراین هنگامی که فرمان خدا [به عذاب دشمنان لجوج] برسد، بر پایه حقّ و درستی داوری خواهد شد و آنجاست که اهل باطل زیان خواهند کرد."},{"s":"سُورَةُ فُصِّلَتۡ","n":3,"ar":"كِتَٰبٌۭ فُصِّلَتْ ءَايَٰتُهُۥ قُرْءَانًا عَرَبِيًّۭا لِّقَوْمٍۢ يَعْلَمُونَ","fa":"کتابی است که آیاتش در نهایت روشنی بیان شده است، [به زبانی] فصیح و گویا برای مردمی که اهل معرفت و آگاهی اند؛"},{"s":"سُورَةُ فُصِّلَتۡ","n":13,"ar":"فَإِنْ أَعْرَضُوا۟ فَقُلْ أَنذَرْتُكُمْ صَٰعِقَةًۭ مِّثْلَ صَٰعِقَةِ عَادٍۢ وَثَمُودَ","fa":"اگر روی گرداندند، بگو: من شما را از صاعقه ای [مرگبار] چون صاعقه عاد و ثمود بیم می دهم."},{"s":"سُورَةُ فُصِّلَتۡ","n":23,"ar":"وَذَٰلِكُمْ ظَنُّكُمُ ٱلَّذِى ظَنَنتُم بِرَبِّكُمْ أَرْدَىٰكُمْ فَأَصْبَحْتُم مِّنَ ٱلْخَٰسِرِينَ","fa":"و این گمانتان بود که به پروردگارتان بردید [و همان] شما را هلاک کرد، در نتیجه از زیانکاران شدید."},{"s":"سُورَةُ فُصِّلَتۡ","n":33,"ar":"وَمَنْ أَحْسَنُ قَوْلًۭا مِّمَّن دَعَآ إِلَى ٱللَّهِ وَعَمِلَ صَٰلِحًۭا وَقَالَ إِنَّنِى مِنَ ٱلْمُسْلِمِينَ","fa":"و خوش گفتارتر از کسی که به سوی خدا دعوت کند و کار شایسته انجام دهد و گوید: من از تسلیم شدگان [در برابر فرمان ها و احکام خدا] هستم، کیست؟"},{"s":"سُورَةُ فُصِّلَتۡ","n":43,"ar":"مَّا يُقَالُ لَكَ إِلَّا مَا قَدْ قِيلَ لِلرُّسُلِ مِن قَبْلِكَ ۚ إِنَّ رَبَّكَ لَذُو مَغْفِرَةٍۢ وَذُو عِقَابٍ أَلِيمٍۢ","fa":"جز آنچه به پیامبران پیش از تو گفته شده است، به تو گفته نمی شود؛ مسلماً پروردگارت صاحب آمرزش ودارای عذابی دردناک است؛"},{"s":"سُورَةُ فُصِّلَتۡ","n":53,"ar":"سَنُرِيهِمْ ءَايَٰتِنَا فِى ٱلْءَافَاقِ وَفِىٓ أَنفُسِهِمْ حَتَّىٰ يَتَبَيَّنَ لَهُمْ أَنَّهُ ٱلْحَقُّ ۗ أَوَلَمْ يَكْفِ بِرَبِّكَ أَنَّهُۥ عَلَىٰ كُلِّ شَىْءٍۢ شَهِيدٌ","fa":"به زودی نشانه های خود را در کرانه ها و اطراف جهان و در نفوس خودشان به آنان نشان خواهیم داد تا برای آنان روشن شود که بی تردید او حق است. آیا کافی نیست که پروردگارت [با ظاهر کردن حقایق و دلایل] بر همه چیز گواه است [که تنها او آفریننده و بی نیاز است و غیر او مخلوق و از هر جهت نیازمند به اوست.]"},{"s":"سُورَةُ الشُّورَىٰ","n":9,"ar":"أَمِ ٱتَّخَذُوا۟ مِن دُونِهِۦٓ أَوْلِيَآءَ ۖ فَٱللَّهُ هُوَ ٱلْوَلِىُّ وَهُوَ يُحْىِ ٱلْمَوْتَىٰ وَهُوَ عَلَىٰ كُلِّ شَىْءٍۢ قَدِيرٌۭ","fa":"آیا به جای او سرپرستان و معبودانی برای خود گرفته اند؟ در حالی که سرپرست و معبود واقعی خداست، و تنها اوست که مردگان را زنده می کند و فقط اوست که بر هر کاری تواناست؛"},{"s":"سُورَةُ الشُّورَىٰ","n":19,"ar":"ٱللَّهُ لَطِيفٌۢ بِعِبَادِهِۦ يَرْزُقُ مَن يَشَآءُ ۖ وَهُوَ ٱلْقَوِىُّ ٱلْعَزِيزُ","fa":"خدا نسبت به بندگانش بسیار مهربان و نیکوکار است، هر که را بخواهد روزی می بخشد و او نیرومند و توانای شکست ناپذیر است."},{"s":"سُورَةُ الشُّورَىٰ","n":29,"ar":"وَمِنْ ءَايَٰتِهِۦ خَلْقُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَمَا بَثَّ فِيهِمَا مِن دَآبَّةٍۢ ۚ وَهُوَ عَلَىٰ جَمْعِهِمْ إِذَا يَشَآءُ قَدِيرٌۭ","fa":"و از نشانه های [ربوبیت و قدرت] او آفرینش آسمان ها و زمین است و [نیز] آنچه از جنبنده میان آن دو پراکنده است، و او هرگاه بخواهد بر جمع کردنشان تواناست."},{"s":"سُورَةُ الشُّورَىٰ","n":39,"ar":"وَٱلَّذِينَ إِذَآ أَصَابَهُمُ ٱلْبَغْىُ هُمْ يَنتَصِرُونَ","fa":"و آنان که هرگاه ستمی به آنان رسد [تسلیم ستم و ستمکار نمی شوند، بلکه از دشمن به حکم حق و برابر با قوانین اسلام] انتقام می گیرند؛"},{"s":"سُورَةُ الشُّورَىٰ","n":49,"ar":"لِّلَّهِ مُلْكُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ ۚ يَخْلُقُ مَا يَشَآءُ ۚ يَهَبُ لِمَن يَشَآءُ إِنَٰثًۭا وَيَهَبُ لِمَن يَشَآءُ ٱلذُّكُورَ","fa":"مالکیّت و فرمانروایی آسمان ها و زمین فقط در سیطره خداست، هر چه را بخواهد می آفریند، به هر کس بخواهد دختر عطا می کند و به هر کس بخواهد پسر می بخشد؛"},{"s":"سُورَةُ الزُّخۡرُفِ","n":6,"ar":"وَكَمْ أَرْسَلْنَا مِن نَّبِىٍّۢ فِى ٱلْأَوَّلِينَ","fa":"و چه بسیار پیامبرانی که در میان پیشینیان [که مردمی اسراف کار بودند] فرستادیم [و به سبب اسرافشان از فرستادن پیامبر دریغ نکردیم؛]"},{"s":"سُورَةُ الزُّخۡرُفِ","n":16,"ar":"أَمِ ٱتَّخَذَ مِمَّا يَخْلُقُ بَنَاتٍۢ وَأَصْفَىٰكُم بِٱلْبَنِينَ","fa":"آیا از آنچه خدا می آفریند، دخترانی برای خود برگرفته و شما را به داشتن پسران برگزیده است؟"},{"s":"سُورَةُ الزُّخۡرُفِ","n":26,"ar":"وَإِذْ قَالَ إِبْرَٰهِيمُ لِأَبِيهِ وَقَوْمِهِۦٓ إِنَّنِى بَرَآءٌۭ مِّمَّا تَعْبُدُونَ","fa":"و [یاد کن] هنگامی را که ابراهیم به پدر و قومش گفت: من بی تردید از آنچه می پرستید، بیزارم."},{"s":"سُورَةُ الزُّخۡرُفِ","n":36,"ar":"وَمَن يَعْشُ عَن ذِكْرِ ٱلرَّحْمَٰنِ نُقَيِّضْ لَهُۥ شَيْطَٰنًۭا فَهُوَ لَهُۥ قَرِينٌۭ","fa":"و هر کس خود را از یاد [خدای] رحمان به کوردلی و حجاب باطن بزند، شیطانی بر او می گماریم که آن شیطان ملازم و دمسازش باشد."},{"s":"سُورَةُ الزُّخۡرُفِ","n":46,"ar":"وَلَقَدْ أَرْسَلْنَا مُوسَىٰ بِـَٔايَٰتِنَآ إِلَىٰ فِرْعَوْنَ وَمَلَإِي۟هِۦ فَقَالَ إِنِّى رَسُولُ رَبِّ ٱلْعَٰلَمِينَ","fa":"و به راستی ما موسی را با نشانه های خود به سوی فرعون و سران و اشراف قومش فرستادیم، پس گفت: من فرستاده پروردگار جهانیانم؛"},{"s":"سُورَةُ الزُّخۡرُفِ","n":56,"ar":"فَجَعَلْنَٰهُمْ سَلَفًۭا وَمَثَلًۭا لِّلْءَاخِرِينَ","fa":"در نتیجه آنان را پیشگامان [دوزخیان] و عبرتی برای آیندگان قرار دادیم."},{"s":"سُورَةُ الزُّخۡرُفِ","n":66,"ar":"هَلْ يَنظُرُونَ إِلَّا ٱلسَّاعَةَ أَن تَأْتِيَهُم بَغْتَةًۭ وَهُمْ لَا يَشْعُرُونَ","fa":"آیا جز این انتظاری دارند که ناگاه قیامت در رسد در حالی که نمی فهمند؟"},{"s":"سُورَةُ الزُّخۡرُفِ","n":76,"ar":"وَمَا ظَلَمْنَٰهُمْ وَلَٰكِن كَانُوا۟ هُمُ ٱلظَّٰلِمِينَ","fa":"و ما بر آنان ستم نکردیم، ولی آنان خود ستمکار بودند،"},{"s":"سُورَةُ الزُّخۡرُفِ","n":86,"ar":"وَلَا يَمْلِكُ ٱلَّذِينَ يَدْعُونَ مِن دُونِهِ ٱلشَّفَٰعَةَ إِلَّا مَن شَهِدَ بِٱلْحَقِّ وَهُمْ يَعْلَمُونَ","fa":"و کسانی را که به جای خدا می پرستند، اختیار شفاعت ندارند، اختیار شفاعت فقط با کسانی است که [از روی بصیرت] شهادت به حق داده اند و آنان [حقیقت حال کسانی را که می خواهند برای آنان شفاعت کنند] می دانند."},{"s":"سُورَةُ الدُّخَانِ","n":7,"ar":"رَبِّ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَمَا بَيْنَهُمَآ ۖ إِن كُنتُم مُّوقِنِينَ","fa":"[همان] پروردگار آسمان ها و زمین و آنچه میان آنهاست، اگر یقین دارید."},{"s":"سُورَةُ الدُّخَانِ","n":17,"ar":"۞ وَلَقَدْ فَتَنَّا قَبْلَهُمْ قَوْمَ فِرْعَوْنَ وَجَآءَهُمْ رَسُولٌۭ كَرِيمٌ","fa":"و همانا پیش از آنان قوم فرعون را آزمودیم، و پیامبری بزرگوار برای آنان آمد،"},{"s":"سُورَةُ الدُّخَانِ","n":27,"ar":"وَنَعْمَةٍۢ كَانُوا۟ فِيهَا فَٰكِهِينَ","fa":"و نعمت هایی که با آسایش و خوشی از آن برخوردار بودند."},{"s":"سُورَةُ الدُّخَانِ","n":37,"ar":"أَهُمْ خَيْرٌ أَمْ قَوْمُ تُبَّعٍۢ وَٱلَّذِينَ مِن قَبْلِهِمْ ۚ أَهْلَكْنَٰهُمْ ۖ إِنَّهُمْ كَانُوا۟ مُجْرِمِينَ","fa":"آیا اینان [در قدرت و شوکت] برترند یا قوم تُبَّع، و کسانی که پیش از آنان بودند؟ ما همه آنان را هلاک کردیم؛ زیرا مجرم بودند؛"},{"s":"سُورَةُ الدُّخَانِ","n":47,"ar":"خُذُوهُ فَٱعْتِلُوهُ إِلَىٰ سَوَآءِ ٱلْجَحِيمِ","fa":"[گفته می شود:] این گنهکار را بگیرید و او را به زور به وسط دوزخ بکشانید."},{"s":"سُورَةُ الدُّخَانِ","n":57,"ar":"فَضْلًۭا مِّن رَّبِّكَ ۚ ذَٰلِكَ هُوَ ٱلْفَوْزُ ٱلْعَظِيمُ","fa":"[این] فضل و احسانی است از سوی پروردگار تو، [و] این همان کامیابی بزرگ است."},{"s":"سُورَةُ الجَاثِيَةِ","n":8,"ar":"يَسْمَعُ ءَايَٰتِ ٱللَّهِ تُتْلَىٰ عَلَيْهِ ثُمَّ يُصِرُّ مُسْتَكْبِرًۭا كَأَن لَّمْ يَسْمَعْهَا ۖ فَبَشِّرْهُ بِعَذَابٍ أَلِيمٍۢ","fa":"که آیات خدا را در حالی که بر او می خوانند می شنود، آن گاه از روی سرکشی و تکبّر چنان که گویی آن را نشنیده است [بر کفر، عناد، دشمنی و مخالفتش] پافشاری می کند؛ پس او را به عذابی دردناک بشارت ده."},{"s":"سُورَةُ الجَاثِيَةِ","n":18,"ar":"ثُمَّ جَعَلْنَٰكَ عَلَىٰ شَرِيعَةٍۢ مِّنَ ٱلْأَمْرِ فَٱتَّبِعْهَا وَلَا تَتَّبِعْ أَهْوَآءَ ٱلَّذِينَ لَا يَعْلَمُونَ","fa":"سپس تو را [در امر نبوّت و دین] بر آیینی ویژه و کامل قرار دادیم؛ بنابراین از آن پیروی کن و از هواهای نفسانی کسانی که [به حقایق] معرفت و آگاهی ندارند، پیروی مکن."},{"s":"سُورَةُ الجَاثِيَةِ","n":28,"ar":"وَتَرَىٰ كُلَّ أُمَّةٍۢ جَاثِيَةًۭ ۚ كُلُّ أُمَّةٍۢ تُدْعَىٰٓ إِلَىٰ كِتَٰبِهَا ٱلْيَوْمَ تُجْزَوْنَ مَا كُنتُمْ تَعْمَلُونَ","fa":"و هر امتی را در آن روز به زانو درافتاده می بینی، [آن روز] هر امتی به سوی نامه اعمالش خوانده می شود [و به آنان می گویند:] امروز همان اعمالی که همواره انجام می دادید به شما پاداش می دهند."},{"s":"سُورَةُ الأَحۡقَافِ","n":1,"ar":"بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ حمٓ","fa":"حم"},{"s":"سُورَةُ الأَحۡقَافِ","n":11,"ar":"وَقَالَ ٱلَّذِينَ كَفَرُوا۟ لِلَّذِينَ ءَامَنُوا۟ لَوْ كَانَ خَيْرًۭا مَّا سَبَقُونَآ إِلَيْهِ ۚ وَإِذْ لَمْ يَهْتَدُوا۟ بِهِۦ فَسَيَقُولُونَ هَٰذَآ إِفْكٌۭ قَدِيمٌۭ","fa":"و کافران درباره مؤمنان گفتند: اگر [آیین محمّد] بهتر [از آیین ما] بود [آنان در پذیرفتنش] بر ما نسبت به آن پیشی نمی گرفتند [بلکه خود ما زودتر از آنان به این کتاب ایمان می آوردیم]. و چون [خودشان به خاطر کبر و عنادشان] به وسیله آن هدایت نیافتند، به زودی خواهند گفت: این یک دروغ قدیمی است."},{"s":"سُورَةُ الأَحۡقَافِ","n":21,"ar":"۞ وَٱذْكُرْ أَخَا عَادٍ إِذْ أَنذَرَ قَوْمَهُۥ بِٱلْأَحْقَافِ وَقَدْ خَلَتِ ٱلنُّذُرُ مِنۢ بَيْنِ يَدَيْهِ وَمِنْ خَلْفِهِۦٓ أَلَّا تَعْبُدُوٓا۟ إِلَّا ٱللَّهَ إِنِّىٓ أَخَافُ عَلَيْكُمْ عَذَابَ يَوْمٍ عَظِيمٍۢ","fa":"و [سرگذشت هود] برادر قوم عاد را یاد کن، هنگامی که قومش را در سرزمین احقاف بیم داد، و بی تردید بیم دهندگانی پیش از او و پس از او [در آن سرزمین] گذشته بودند که فقط خدا را بپرستید؛ زیرا من بر شما از عذاب روزی بزرگ می ترسم."},{"s":"سُورَةُ الأَحۡقَافِ","n":31,"ar":"يَٰقَوْمَنَآ أَجِيبُوا۟ دَاعِىَ ٱللَّهِ وَءَامِنُوا۟ بِهِۦ يَغْفِرْ لَكُم مِّن ذُنُوبِكُمْ وَيُجِرْكُم مِّنْ عَذَابٍ أَلِيمٍۢ","fa":"ای قوم ما! دعوت کننده [به سوی] خدا [پیامبر اسلام] را اجابت کنید و به او ایمان آورید تا خدا برخی از گناهانتان را بیامرزد و از عذابی دردناک پناهتان دهد؛"},{"s":"سُورَةُ مُحَمَّدٍ","n":6,"ar":"وَيُدْخِلُهُمُ ٱلْجَنَّةَ عَرَّفَهَا لَهُمْ","fa":"و آنان را در بهشتی که در دنیا به آنان شناسانده در می آورد."},{"s":"سُورَةُ مُحَمَّدٍ","n":16,"ar":"وَمِنْهُم مَّن يَسْتَمِعُ إِلَيْكَ حَتَّىٰٓ إِذَا خَرَجُوا۟ مِنْ عِندِكَ قَالُوا۟ لِلَّذِينَ أُوتُوا۟ ٱلْعِلْمَ مَاذَا قَالَ ءَانِفًا ۚ أُو۟لَٰٓئِكَ ٱلَّذِينَ طَبَعَ ٱللَّهُ عَلَىٰ قُلُوبِهِمْ وَٱتَّبَعُوٓا۟ أَهْوَآءَهُمْ","fa":"گروهی از آنان [که منافق اند در ظاهر به گفتارت] گوش می دهند، ولی هنگامی که از نزد تو بیرون روند به کسانی که آگاهی و معرفت به آنان داده شده [از روی مسخره] می گویند: هم اکنون چه گفت؟ [ما که گفته او را نفهمیدیم.] آنان کسانی هستند که خدا بر دل هایشان مهر [تیره بختی] نهاده واز هواهای نفسانی خود پیروی کرده اند،"},{"s":"سُورَةُ مُحَمَّدٍ","n":26,"ar":"ذَٰلِكَ بِأَنَّهُمْ قَالُوا۟ لِلَّذِينَ كَرِهُوا۟ مَا نَزَّلَ ٱللَّهُ سَنُطِيعُكُمْ فِى بَعْضِ ٱلْأَمْرِ ۖ وَٱللَّهُ يَعْلَمُ إِسْرَارَهُمْ","fa":"این به سبب آن است که آنان به کسانی [چون مشرکان و کافران] که نازل شدن وحی را خوش نداشتند، گفتند: [ما] در بعضی از امور [که بر ضد مؤمنان است] از شما اطاعت خواهیم کرد. در حالی که خدا اسرارشان را می داند."},{"s":"سُورَةُ مُحَمَّدٍ","n":36,"ar":"إِنَّمَا ٱلْحَيَوٰةُ ٱلدُّنْيَا لَعِبٌۭ وَلَهْوٌۭ ۚ وَإِن تُؤْمِنُوا۟ وَتَتَّقُوا۟ يُؤْتِكُمْ أُجُورَكُمْ وَلَا يَسْـَٔلْكُمْ أَمْوَٰلَكُمْ","fa":"زندگی دنیا فقط بازی و سرگرمی است، اگر ایمان بیاورید و پرهیزکاری کنید، خدا پاداش هایتان را می دهد و از شما نمی خواهد [که] اموالتان را [در راه خدا انفاق کنید؛]"},{"s":"سُورَةُ الفَتۡحِ","n":8,"ar":"إِنَّآ أَرْسَلْنَٰكَ شَٰهِدًۭا وَمُبَشِّرًۭا وَنَذِيرًۭا","fa":"ما تو را گواه [بر اعمال امت] و مژده رسان و بیم دهنده فرستادیم؛"},{"s":"سُورَةُ الفَتۡحِ","n":18,"ar":"۞ لَّقَدْ رَضِىَ ٱللَّهُ عَنِ ٱلْمُؤْمِنِينَ إِذْ يُبَايِعُونَكَ تَحْتَ ٱلشَّجَرَةِ فَعَلِمَ مَا فِى قُلُوبِهِمْ فَأَنزَلَ ٱلسَّكِينَةَ عَلَيْهِمْ وَأَثَٰبَهُمْ فَتْحًۭا قَرِيبًۭا","fa":"یقیناً خدا از مؤمنان هنگامی که زیر آن درخت [که در منطقه حدیبیه بود] با تو بیعت می کردند خشنود شد، و خدا آنچه را [از خلوص نیّت و پاکی قصد] در دل هایشان بود می دانست، در نتیجه آرامش را بر آنان نازل کرد، و پیروزی نزدیکی را [که پیروزی در خیبر بود] به آنان پاداش داد."},{"s":"سُورَةُ الفَتۡحِ","n":28,"ar":"هُوَ ٱلَّذِىٓ أَرْسَلَ رَسُولَهُۥ بِٱلْهُدَىٰ وَدِينِ ٱلْحَقِّ لِيُظْهِرَهُۥ عَلَى ٱلدِّينِ كُلِّهِۦ ۚ وَكَفَىٰ بِٱللَّهِ شَهِيدًۭا","fa":"اوست که پیامبرش را با هدایت و دین حق فرستاد تا آن را بر همه ادیان پیروز کند، و کافی است که خدا [بر وقوع این حقیقت] گواه باشد."},{"s":"سُورَةُ الحُجُرَاتِ","n":9,"ar":"وَإِن طَآئِفَتَانِ مِنَ ٱلْمُؤْمِنِينَ ٱقْتَتَلُوا۟ فَأَصْلِحُوا۟ بَيْنَهُمَا ۖ فَإِنۢ بَغَتْ إِحْدَىٰهُمَا عَلَى ٱلْأُخْرَىٰ فَقَٰتِلُوا۟ ٱلَّتِى تَبْغِى حَتَّىٰ تَفِىٓءَ إِلَىٰٓ أَمْرِ ٱللَّهِ ۚ فَإِن فَآءَتْ فَأَصْلِحُوا۟ بَيْنَهُمَا بِٱلْعَدْلِ وَأَقْسِطُوٓا۟ ۖ إِنَّ ٱللَّهَ يُحِبُّ ٱلْمُقْسِطِينَ","fa":"و اگر دو گروه از مؤمنان با یکدیگر بجنگند میان آنها صلح و آشتی برقرار کنید، و اگر یکی از آن دو گروه بر دیگری تجاوز کند، با آن گروهی که تجاوز می کند، بجنگید تا به حکم خدا باز گردد. پس اگر بازگشت، میانشان به عدالت و انصاف، صلح و آشتی برقرار کنید؛ و همواره دادگری را پیشه سازید که خدا دادگران را دوست دارد."},{"s":"سُورَةُ قٓ","n":1,"ar":"بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ قٓ ۚ وَٱلْقُرْءَانِ ٱلْمَجِيدِ","fa":"ق، سوگند به قرآن مجید [که محمّد، فرستاده ماست و وقوع قیامت حق است.]"},{"s":"سُورَةُ قٓ","n":11,"ar":"رِّزْقًۭا لِّلْعِبَادِ ۖ وَأَحْيَيْنَا بِهِۦ بَلْدَةًۭ مَّيْتًۭا ۚ كَذَٰلِكَ ٱلْخُرُوجُ","fa":"برای آنکه رزق و روزی بندگان باشد، و نیز به وسیله آن آب سرزمین مرده را زنده کردیم؛ و بیرون آمدنشان [پس از مرگ از خاک گور برای ورود به قیامت] این گونه است."},{"s":"سُورَةُ قٓ","n":21,"ar":"وَجَآءَتْ كُلُّ نَفْسٍۢ مَّعَهَا سَآئِقٌۭ وَشَهِيدٌۭ","fa":"هر کسی در آن روز می آید در حالی که سوق دهنده ای و شاهدی با اوست، [که سوق دهنده او را به محشر می راند و شاهد بر اعمالش گواهی می دهد.]"},{"s":"سُورَةُ قٓ","n":31,"ar":"وَأُزْلِفَتِ ٱلْجَنَّةُ لِلْمُتَّقِينَ غَيْرَ بَعِيدٍ","fa":"و بهشت را به پرهیزکاران نزدیک می کنند بی آنکه فاصله ای از آنان داشته باشد."},{"s":"سُورَةُ قٓ","n":41,"ar":"وَٱسْتَمِعْ يَوْمَ يُنَادِ ٱلْمُنَادِ مِن مَّكَانٍۢ قَرِيبٍۢ","fa":"و گوش فرا ده روزی که ندا دهنده از جایی نزدیک ندا می دهد."},{"s":"سُورَةُ الذَّارِيَاتِ","n":6,"ar":"وَإِنَّ ٱلدِّينَ لَوَٰقِعٌۭ","fa":"وقطعاً [روز] جزا واقع خواهد شد."},{"s":"سُورَةُ الذَّارِيَاتِ","n":16,"ar":"ءَاخِذِينَ مَآ ءَاتَىٰهُمْ رَبُّهُمْ ۚ إِنَّهُمْ كَانُوا۟ قَبْلَ ذَٰلِكَ مُحْسِنِينَ","fa":"آنچه را پروردگارشان به آنان عطا کرده دریافت می کنند؛ زیرا که آنان پیش از این همواره نیکوکار بودند."},{"s":"سُورَةُ الذَّارِيَاتِ","n":26,"ar":"فَرَاغَ إِلَىٰٓ أَهْلِهِۦ فَجَآءَ بِعِجْلٍۢ سَمِينٍۢ","fa":"پس به سوی خانواده اش بازگشت و گوساله ای فربه [و بریان شده] آورد."},{"s":"سُورَةُ الذَّارِيَاتِ","n":36,"ar":"فَمَا وَجَدْنَا فِيهَا غَيْرَ بَيْتٍۢ مِّنَ ٱلْمُسْلِمِينَ","fa":"در آنجا جز یک خانه از مسلمانان [که اهلش مطیع خدا بودند، نیافتیم.]"},{"s":"سُورَةُ الذَّارِيَاتِ","n":46,"ar":"وَقَوْمَ نُوحٍۢ مِّن قَبْلُ ۖ إِنَّهُمْ كَانُوا۟ قَوْمًۭا فَٰسِقِينَ","fa":"و قوم نوح را پیش از این [هلاک کردیم]؛ زیرا آنان همواره مردمی نافرمان بودند."},{"s":"سُورَةُ الذَّارِيَاتِ","n":56,"ar":"وَمَا خَلَقْتُ ٱلْجِنَّ وَٱلْإِنسَ إِلَّا لِيَعْبُدُونِ","fa":"و جن و انس را جز برای اینکه مرا بپرستند نیافریدیم؛"},{"s":"سُورَةُ الطُّورِ","n":6,"ar":"وَٱلْبَحْرِ ٱلْمَسْجُورِ","fa":"و به آن دریای مملو و برافروخته،"},{"s":"سُورَةُ الطُّورِ","n":16,"ar":"ٱصْلَوْهَا فَٱصْبِرُوٓا۟ أَوْ لَا تَصْبِرُوا۟ سَوَآءٌ عَلَيْكُمْ ۖ إِنَّمَا تُجْزَوْنَ مَا كُنتُمْ تَعْمَلُونَ","fa":"در آن در آیید [و بسوزید]؛ پس صبر کنید یا نکنید برای شما یکسان است. فقط اعمالی را که همواره انجام می دادید، جزا داده می شوید."},{"s":"سُورَةُ الطُّورِ","n":26,"ar":"قَالُوٓا۟ إِنَّا كُنَّا قَبْلُ فِىٓ أَهْلِنَا مُشْفِقِينَ","fa":"می گویند: ما پیش تر [در دنیا] در میان کسان خود [از عذاب امروز] ترسان بودیم؛"},{"s":"سُورَةُ الطُّورِ","n":36,"ar":"أَمْ خَلَقُوا۟ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ ۚ بَل لَّا يُوقِنُونَ","fa":"یاآنان آسمان ها و زمین را آفریده اند؟ نه، بلکه یقین ندارند."},{"s":"سُورَةُ الطُّورِ","n":46,"ar":"يَوْمَ لَا يُغْنِى عَنْهُمْ كَيْدُهُمْ شَيْـًۭٔا وَلَا هُمْ يُنصَرُونَ","fa":"روزی که نیرنگشان چیزی از عذاب را از آنان دفع نمی کند و یاری هم نخواهند شد."},{"s":"سُورَةُ النَّجۡمِ","n":7,"ar":"وَهُوَ بِٱلْأُفُقِ ٱلْأَعْلَىٰ","fa":"در حالی که در افق اعلا بود."},{"s":"سُورَةُ النَّجۡمِ","n":17,"ar":"مَا زَاغَ ٱلْبَصَرُ وَمَا طَغَىٰ","fa":"دیده [پیامبر آنچه را دید] بر غیر حقیقت و به خطا ندید و از مرز دیدن حقیقت هم درنگذشت."},{"s":"سُورَةُ النَّجۡمِ","n":27,"ar":"إِنَّ ٱلَّذِينَ لَا يُؤْمِنُونَ بِٱلْءَاخِرَةِ لَيُسَمُّونَ ٱلْمَلَٰٓئِكَةَ تَسْمِيَةَ ٱلْأُنثَىٰ","fa":"مسلماً کسانی که به آخرت ایمان ندارند، فرشتگان را در نامگذاری به نام زن نامگذاری می کنند؛"},{"s":"سُورَةُ النَّجۡمِ","n":37,"ar":"وَإِبْرَٰهِيمَ ٱلَّذِى وَفَّىٰٓ","fa":"و [یا به آنچه در صحیفه های] ابراهیم [است] همان که به طور کامل [به پیمانش با خدا] وفا کرد [آگاهش نکرده اند؟]"},{"s":"سُورَةُ النَّجۡمِ","n":47,"ar":"وَأَنَّ عَلَيْهِ ٱلنَّشْأَةَ ٱلْأُخْرَىٰ","fa":"و پدید آوردن جهان دیگر بر عهده اوست،"},{"s":"سُورَةُ النَّجۡمِ","n":57,"ar":"أَزِفَتِ ٱلْءَازِفَةُ","fa":"قیامت نزدیک شد."},{"s":"سُورَةُ القَمَرِ","n":5,"ar":"حِكْمَةٌۢ بَٰلِغَةٌۭ ۖ فَمَا تُغْنِ ٱلنُّذُرُ","fa":"[این خبرها] پندی رساست، ولی هشدارها [به این ستمکاران لجوج] سودی نمی بخشد."},{"s":"سُورَةُ القَمَرِ","n":15,"ar":"وَلَقَد تَّرَكْنَٰهَآ ءَايَةًۭ فَهَلْ مِن مُّدَّكِرٍۢ","fa":"و بی تردید آن سرگذشت را [برای آیندگان] مایه پند و عبرت باقی گذاشتیم، پس آیا پند گیرنده ای هست؟"},{"s":"سُورَةُ القَمَرِ","n":25,"ar":"أَءُلْقِىَ ٱلذِّكْرُ عَلَيْهِ مِنۢ بَيْنِنَا بَلْ هُوَ كَذَّابٌ أَشِرٌۭ","fa":"آیا از میان ما فقط بر او وحی نازل شده است؟! [نه، چنین نیست] بلکه او بسیار دروغگو و پر افاده و متکبر است [که می خواهد بر ما بزرگی کند.]"},{"s":"سُورَةُ القَمَرِ","n":35,"ar":"نِّعْمَةًۭ مِّنْ عِندِنَا ۚ كَذَٰلِكَ نَجْزِى مَن شَكَرَ","fa":"[این] نعمت و رحمتی از سوی ما بود، این گونه کسی را که سپاس گزار است، پاداش می دهیم."},{"s":"سُورَةُ القَمَرِ","n":45,"ar":"سَيُهْزَمُ ٱلْجَمْعُ وَيُوَلُّونَ ٱلدُّبُرَ","fa":"به زودی [این] گروه [متحد در جنگی که خود بر ضد مؤمنان تدارک می بینند] شکست می خورند و پشت کنان می گریزند."},{"s":"سُورَةُ القَمَرِ","n":55,"ar":"فِى مَقْعَدِ صِدْقٍ عِندَ مَلِيكٍۢ مُّقْتَدِرٍۭ","fa":"در جایگاهی حق و پسندیده نزد پادشاهی توانا."},{"s":"سُورَةُ الرَّحۡمَٰن","n":10,"ar":"وَٱلْأَرْضَ وَضَعَهَا لِلْأَنَامِ","fa":"و زمین را برای [زندگی] مردم نهاد؛"},{"s":"سُورَةُ الرَّحۡمَٰن","n":20,"ar":"بَيْنَهُمَا بَرْزَخٌۭ لَّا يَبْغِيَانِ","fa":"[ولی] میان آن دو حایلی است که به هم تجاوز نمی کنند [درنتیجه باهم مخلوط نمی شوند!]"},{"s":"سُورَةُ الرَّحۡمَٰن","n":30,"ar":"فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ","fa":"پس کدامیک از نعمت های پروردگارتان را انکار می کنید؟"},{"s":"سُورَةُ الرَّحۡمَٰن","n":40,"ar":"فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ","fa":"پس کدامیک از نعمت های پروردگارتان را انکار می کنید؟"},{"s":"سُورَةُ الرَّحۡمَٰن","n":50,"ar":"فِيهِمَا عَيْنَانِ تَجْرِيَانِ","fa":"در آن دو بهشت دو چشمه ای است که همواره جاری است."},{"s":"سُورَةُ الرَّحۡمَٰن","n":60,"ar":"هَلْ جَزَآءُ ٱلْإِحْسَٰنِ إِلَّا ٱلْإِحْسَٰنُ","fa":"آیا پاداش نیکی جز نیکی است؟"},{"s":"سُورَةُ الرَّحۡمَٰن","n":70,"ar":"فِيهِنَّ خَيْرَٰتٌ حِسَانٌۭ","fa":"در آنها زنانی نیکو سیرت و زیبا صورت اند."},{"s":"سُورَةُ الوَاقِعَةِ","n":2,"ar":"لَيْسَ لِوَقْعَتِهَا كَاذِبَةٌ","fa":"که در واقع شدنش دروغی [در کار] نیست،"},{"s":"سُورَةُ الوَاقِعَةِ","n":12,"ar":"فِى جَنَّٰتِ ٱلنَّعِيمِ","fa":"در بهشت های پر نعمت اند."},{"s":"سُورَةُ الوَاقِعَةِ","n":22,"ar":"وَحُورٌ عِينٌۭ","fa":"و حوریانی چشم درشت،"},{"s":"سُورَةُ الوَاقِعَةِ","n":32,"ar":"وَفَٰكِهَةٍۢ كَثِيرَةٍۢ","fa":"و میوه ای فراوان،"},{"s":"سُورَةُ الوَاقِعَةِ","n":42,"ar":"فِى سَمُومٍۢ وَحَمِيمٍۢ","fa":"در میان بادی سوزان و آبی جوشان [قرار دارند،]"},{"s":"سُورَةُ الوَاقِعَةِ","n":52,"ar":"لَءَاكِلُونَ مِن شَجَرٍۢ مِّن زَقُّومٍۢ","fa":"قطعاً از درختی که از زقّوم است [و دارای مایعی جوشان و بسیار بدمزه و بدبوست] خواهید خورد؛"},{"s":"سُورَةُ الوَاقِعَةِ","n":62,"ar":"وَلَقَدْ عَلِمْتُمُ ٱلنَّشْأَةَ ٱلْأُولَىٰ فَلَوْلَا تَذَكَّرُونَ","fa":"و به راستی پیدایش نخستین را [که جهان فعلی است] شناختید، پس چرا متذکّر [پدید شدن جهان دیگر] نمی شوید؟!"},{"s":"سُورَةُ الوَاقِعَةِ","n":72,"ar":"ءَأَنتُمْ أَنشَأْتُمْ شَجَرَتَهَآ أَمْ نَحْنُ ٱلْمُنشِـُٔونَ","fa":"آیا شما درختش را به وجود آورده اید یا ما به وجود آوردنده ایم؟"},{"s":"سُورَةُ الوَاقِعَةِ","n":82,"ar":"وَتَجْعَلُونَ رِزْقَكُمْ أَنَّكُمْ تُكَذِّبُونَ","fa":"و فقط نصیب خود را این قرار می دهید که آن را انکار کنید؟!"},{"s":"سُورَةُ الوَاقِعَةِ","n":92,"ar":"وَأَمَّآ إِن كَانَ مِنَ ٱلْمُكَذِّبِينَ ٱلضَّآلِّينَ","fa":"و اما اگر از انکار کنندگان [حقایق و] گمراه باشد،"},{"s":"سُورَةُ الحَدِيدِ","n":6,"ar":"يُولِجُ ٱلَّيْلَ فِى ٱلنَّهَارِ وَيُولِجُ ٱلنَّهَارَ فِى ٱلَّيْلِ ۚ وَهُوَ عَلِيمٌۢ بِذَاتِ ٱلصُّدُورِ","fa":"شب را در روز در می آورد و روز را در شب در می آورد، و او به نیّات و اسرار سینه ها داناست."},{"s":"سُورَةُ الحَدِيدِ","n":16,"ar":"۞ أَلَمْ يَأْنِ لِلَّذِينَ ءَامَنُوٓا۟ أَن تَخْشَعَ قُلُوبُهُمْ لِذِكْرِ ٱللَّهِ وَمَا نَزَلَ مِنَ ٱلْحَقِّ وَلَا يَكُونُوا۟ كَٱلَّذِينَ أُوتُوا۟ ٱلْكِتَٰبَ مِن قَبْلُ فَطَالَ عَلَيْهِمُ ٱلْأَمَدُ فَقَسَتْ قُلُوبُهُمْ ۖ وَكَثِيرٌۭ مِّنْهُمْ فَٰسِقُونَ","fa":"آیا برای اهل ایمان وقت آن نرسیده که دل هایشان برای یاد خدا و قرآنی که نازل شده نرم و فروتن شود؟ و مانند کسانی نباشند که پیش از این کتاب آسمانی به آنان داده شده بود، آن گاه روزگار [سرگرمی در امور دنیا و مشغول بودن به آرزوهای دور و دراز] بر آنان طولانی گشت، در نتیجه دل هایشان سخت و غیر قابل انعطاف شد، و بسیاری از آنان نافرمان بودند."},{"s":"سُورَةُ الحَدِيدِ","n":26,"ar":"وَلَقَدْ أَرْسَلْنَا نُوحًۭا وَإِبْرَٰهِيمَ وَجَعَلْنَا فِى ذُرِّيَّتِهِمَا ٱلنُّبُوَّةَ وَٱلْكِتَٰبَ ۖ فَمِنْهُم مُّهْتَدٍۢ ۖ وَكَثِيرٌۭ مِّنْهُمْ فَٰسِقُونَ","fa":"به یقین ما نوح و ابراهیم را فرستادیم و در میان فرزندان آن دو نفر، نبوّت و کتاب قرار دادیم، پس برخی از آنان هدایت یافتند و بسیاری از آنان نافرمان بودند."},{"s":"سُورَةُ المُجَادلَةِ","n":7,"ar":"أَلَمْ تَرَ أَنَّ ٱللَّهَ يَعْلَمُ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ ۖ مَا يَكُونُ مِن نَّجْوَىٰ ثَلَٰثَةٍ إِلَّا هُوَ رَابِعُهُمْ وَلَا خَمْسَةٍ إِلَّا هُوَ سَادِسُهُمْ وَلَآ أَدْنَىٰ مِن ذَٰلِكَ وَلَآ أَكْثَرَ إِلَّا هُوَ مَعَهُمْ أَيْنَ مَا كَانُوا۟ ۖ ثُمَّ يُنَبِّئُهُم بِمَا عَمِلُوا۟ يَوْمَ ٱلْقِيَٰمَةِ ۚ إِنَّ ٱللَّهَ بِكُلِّ شَىْءٍ عَلِيمٌ","fa":"آیا ندانسته ای که خدا آنچه را در آسمان ها و آنچه را در زمین است، می داند؟ هیچ گفتگوی محرمانه ای میان سه نفر نیست مگر اینکه او چهارمی آنان است، و نه میان پنج نفر مگر اینکه او ششمی آنان است، و نه کمتر از آن و نه بیشتر مگر اینکه هر کجا باشند او با آنان است، سپس روز قیامت آنان را به اعمالی که انجام داده اند آگاه می کند؛ زیرا خدا به همه چیز داناست."},{"s":"سُورَةُ المُجَادلَةِ","n":17,"ar":"لَّن تُغْنِىَ عَنْهُمْ أَمْوَٰلُهُمْ وَلَآ أَوْلَٰدُهُم مِّنَ ٱللَّهِ شَيْـًٔا ۚ أُو۟لَٰٓئِكَ أَصْحَٰبُ ٱلنَّارِ ۖ هُمْ فِيهَا خَٰلِدُونَ","fa":"هرگز اموال و اولادشان چیزی از عذاب خدا را از آنان دفع نمی کند، آنان اهل آتش اند و در آن جاودانه اند."},{"s":"سُورَةُ الحَشۡرِ","n":5,"ar":"مَا قَطَعْتُم مِّن لِّينَةٍ أَوْ تَرَكْتُمُوهَا قَآئِمَةً عَلَىٰٓ أُصُولِهَا فَبِإِذْنِ ٱللَّهِ وَلِيُخْزِىَ ٱلْفَٰسِقِينَ","fa":"آنچه از درخت خرما [که در مالکیّت این دشمنان غدّار بود] بریدید یا آنها را بر ریشه ها و تنه هایش رها کردید، به فرمان خدا بود، تا نافرمانان را زبون و رسوا کند."},{"s":"سُورَةُ الحَشۡرِ","n":15,"ar":"كَمَثَلِ ٱلَّذِينَ مِن قَبْلِهِمْ قَرِيبًۭا ۖ ذَاقُوا۟ وَبَالَ أَمْرِهِمْ وَلَهُمْ عَذَابٌ أَلِيمٌۭ","fa":"[داستان این یهودی های نابکار بنی نظیر] مانند کسانی است که اندکی پیش از اینان [در پیرامون مدینه] بودند که سرانجام وخیم کارشان را چشیدند، و برای آنان عذابی دردناک است."},{"s":"سُورَةُ المُمۡتَحنَةِ","n":1,"ar":"بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَتَّخِذُوا۟ عَدُوِّى وَعَدُوَّكُمْ أَوْلِيَآءَ تُلْقُونَ إِلَيْهِم بِٱلْمَوَدَّةِ وَقَدْ كَفَرُوا۟ بِمَا جَآءَكُم مِّنَ ٱلْحَقِّ يُخْرِجُونَ ٱلرَّسُولَ وَإِيَّاكُمْ ۙ أَن تُؤْمِنُوا۟ بِٱللَّهِ رَبِّكُمْ إِن كُنتُمْ خَرَجْتُمْ جِهَٰدًۭا فِى سَبِيلِى وَٱبْتِغَآءَ مَرْضَاتِى ۚ تُسِرُّونَ إِلَيْهِم بِٱلْمَوَدَّةِ وَأَنَا۠ أَعْلَمُ بِمَآ أَخْفَيْتُمْ وَمَآ أَعْلَنتُمْ ۚ وَمَن يَفْعَلْهُ مِنكُمْ فَقَدْ ضَلَّ سَوَآءَ ٱلسَّبِيلِ","fa":"ای اهل ایمان! دشمنان من و دشمنان خودتان را دوستان خود مگیرید، شما با آنان اظهار دوستی می کنید، در حالی که آنان به طور یقین به آنچه از حق برای شما آمده کافرند، و پیامبر و شما را به خاطر ایمانتان به خدا که پروردگار شماست [از وطن] بیرون می کنند، [پس آنان را دوستان خود مگیرید] اگر برای جهاد در راه من و طلب خشنودیم بیرون آمده اید [چرا] مخفیانه به آنان پیام می دهید که دوستشان دارید؟ در حالی که من به آنچه پنهان می داشتید و آنچه آشکار کردید داناترم، و هر کس از شما با دشمنان من رابطه دوستی برقرار کند، مسلماً از راه راست منحرف شده است."},{"s":"سُورَةُ المُمۡتَحنَةِ","n":11,"ar":"وَإِن فَاتَكُمْ شَىْءٌۭ مِّنْ أَزْوَٰجِكُمْ إِلَى ٱلْكُفَّارِ فَعَاقَبْتُمْ فَـَٔاتُوا۟ ٱلَّذِينَ ذَهَبَتْ أَزْوَٰجُهُم مِّثْلَ مَآ أَنفَقُوا۟ ۚ وَٱتَّقُوا۟ ٱللَّهَ ٱلَّذِىٓ أَنتُم بِهِۦ مُؤْمِنُونَ","fa":"اگر برخی از همسران شما با پیوستن به کفار از دست شما رفتند [و کافران مهریه مورد مطالبه شما را ندادند] و شما غنیمتی یافتید، پس به کسانی که همسرانشان را [به خاطر پیوستن به کفار] از دست داده اند، معادل مهریه ای که داده اند از غنایم بپردازید، و از خدایی که به او ایمان دارید پروا کنید."},{"s":"سُورَةُ الصَّفِّ","n":8,"ar":"يُرِيدُونَ لِيُطْفِـُٔوا۟ نُورَ ٱللَّهِ بِأَفْوَٰهِهِمْ وَٱللَّهُ مُتِمُّ نُورِهِۦ وَلَوْ كَرِهَ ٱلْكَٰفِرُونَ","fa":"می خواهند نور خدا را با دهان هایشان خاموش کنند در حالی که خدا کامل کننده نور خود است، گرچه کافران خوش نداشته باشند."},{"s":"سُورَةُ الجُمُعَةِ","n":4,"ar":"ذَٰلِكَ فَضْلُ ٱللَّهِ يُؤْتِيهِ مَن يَشَآءُ ۚ وَٱللَّهُ ذُو ٱلْفَضْلِ ٱلْعَظِيمِ","fa":"این [برانگیختن به پیامبری و مسؤولیت عظیم تعلیم و تربیت،] فضل خداست که آن را به هر کس بخواهد عطا می کند، و خدا صاحب فضل بزرگ است."},{"s":"سُورَةُ المُنَافِقُونَ","n":3,"ar":"ذَٰلِكَ بِأَنَّهُمْ ءَامَنُوا۟ ثُمَّ كَفَرُوا۟ فَطُبِعَ عَلَىٰ قُلُوبِهِمْ فَهُمْ لَا يَفْقَهُونَ","fa":"این [صفت زشت نفاق و بدی اعمال] به سبب آن است که آنان [نخست] ایمان آوردند، سپس کافر شدند در نتیجه بر دل هایشان مهر [تیره بختی] زده شد، به این علّت [حقایق را] نمی فهمند."},{"s":"سُورَةُ التَّغَابُنِ","n":2,"ar":"هُوَ ٱلَّذِى خَلَقَكُمْ فَمِنكُمْ كَافِرٌۭ وَمِنكُم مُّؤْمِنٌۭ ۚ وَٱللَّهُ بِمَا تَعْمَلُونَ بَصِيرٌ","fa":"اوست که شما را آفرید؛ گروهی از شما کافرند، و برخی مؤمن، و خدا به آنچه انجام می دهید، بیناست."},{"s":"سُورَةُ التَّغَابُنِ","n":12,"ar":"وَأَطِيعُوا۟ ٱللَّهَ وَأَطِيعُوا۟ ٱلرَّسُولَ ۚ فَإِن تَوَلَّيْتُمْ فَإِنَّمَا عَلَىٰ رَسُولِنَا ٱلْبَلَٰغُ ٱلْمُبِينُ","fa":"و از خدا اطاعت کنید و از پیامبر فرمان برید، و اگر روی برگردانید [بدانید که] بر عهده پیامبر فقط رساندن آشکار [پیام وحی] است."},{"s":"سُورَةُ الطَّلَاقِ","n":4,"ar":"وَٱلَّٰٓـِٔى يَئِسْنَ مِنَ ٱلْمَحِيضِ مِن نِّسَآئِكُمْ إِنِ ٱرْتَبْتُمْ فَعِدَّتُهُنَّ ثَلَٰثَةُ أَشْهُرٍۢ وَٱلَّٰٓـِٔى لَمْ يَحِضْنَ ۚ وَأُو۟لَٰتُ ٱلْأَحْمَالِ أَجَلُهُنَّ أَن يَضَعْنَ حَمْلَهُنَّ ۚ وَمَن يَتَّقِ ٱللَّهَ يَجْعَل لَّهُۥ مِنْ أَمْرِهِۦ يُسْرًۭا","fa":"و از زنان شما آنانی که از عادت ماهیانه ناامیدند، اگر شک دارید [که به سبب رسیدن به سن یائسگی یا عاملی دیگر است] عدّه آنان [پس از طلاق] سه ماه است. و [هم چنین عدّه] زنانی که [با وجود سن معمولی] عادت نشده اند [سه ماه است] و [پایان] عدّه زنان باردار، روزی است که وضع حمل می کنند. و هر که از خدا پروا کند برای او در کارش آسانی قرار می دهد."},{"s":"سُورَةُ التَّحۡرِيمِ","n":2,"ar":"قَدْ فَرَضَ ٱللَّهُ لَكُمْ تَحِلَّةَ أَيْمَٰنِكُمْ ۚ وَٱللَّهُ مَوْلَىٰكُمْ ۖ وَهُوَ ٱلْعَلِيمُ ٱلْحَكِيمُ","fa":"به یقین خدا راه گشودن [و شکستن] سوگندهایتان را [در مواردی] برای شما مقرّر کرده است، [و آن اینکه سوگندها را با کفاره دادن بشکنید تا از محدودیت و تنگنا درآیید] و خدا سرپرست و یار شماست، و او دانا و حکیم است."},{"s":"سُورَةُ التَّحۡرِيمِ","n":12,"ar":"وَمَرْيَمَ ٱبْنَتَ عِمْرَٰنَ ٱلَّتِىٓ أَحْصَنَتْ فَرْجَهَا فَنَفَخْنَا فِيهِ مِن رُّوحِنَا وَصَدَّقَتْ بِكَلِمَٰتِ رَبِّهَا وَكُتُبِهِۦ وَكَانَتْ مِنَ ٱلْقَٰنِتِينَ","fa":"و [نیز] مریم دختر عمران [را مثل زده است] که دامان خود را پاک نگه داشت و در نتیجه از روح خود در او دمیدیم و کلمات پروردگارش و کتاب های او را تصدیق کرد و از اطاعت کنندگان [فرمان های خدا] بود."},{"s":"سُورَةُ المُلۡكِ","n":10,"ar":"وَقَالُوا۟ لَوْ كُنَّا نَسْمَعُ أَوْ نَعْقِلُ مَا كُنَّا فِىٓ أَصْحَٰبِ ٱلسَّعِيرِ","fa":"و می گویند: اگر ما [دعوت سعادت بخش آنان را] شنیده بودیم، یا [در حقایقی که برای ما آوردند] تعقّل کرده بودیم، در میان [آتش] اهل آتش سوزان نبودیم."},{"s":"سُورَةُ المُلۡكِ","n":20,"ar":"أَمَّنْ هَٰذَا ٱلَّذِى هُوَ جُندٌۭ لَّكُمْ يَنصُرُكُم مِّن دُونِ ٱلرَّحْمَٰنِ ۚ إِنِ ٱلْكَٰفِرُونَ إِلَّا فِى غُرُورٍ","fa":"آیا آن کیست [از] سپاهتان که شما را به هنگام نزول عذاب در برابر خدای رحمان یاری دهد؟ کافران جز دچار فریب [شیطان] نیستند."},{"s":"سُورَةُ المُلۡكِ","n":30,"ar":"قُلْ أَرَءَيْتُمْ إِنْ أَصْبَحَ مَآؤُكُمْ غَوْرًۭا فَمَن يَأْتِيكُم بِمَآءٍۢ مَّعِينٍۭ","fa":"بگو: به من خبر دهید اگر آب مورد بهره برداری شما [چون آب رودها، چشمه ها، سدها و چاه ها] در زمین فرو رود [تا آنجا که از دسترس شما خارج گردد] پس کیست که برایتان آب روان و گوارا بیاورد؟!"},{"s":"سُورَةُ القَلَمِ","n":10,"ar":"وَلَا تُطِعْ كُلَّ حَلَّافٍۢ مَّهِينٍ","fa":"و از هر سوگند خورده زبون و فرومایه فرمان مبر،"},{"s":"سُورَةُ القَلَمِ","n":20,"ar":"فَأَصْبَحَتْ كَٱلصَّرِيمِ","fa":"پس [آن باغ] به صورت شبی تاریک درآمد [و جز خاکستر چیزی در آن دیده نمی شد!]"},{"s":"سُورَةُ القَلَمِ","n":30,"ar":"فَأَقْبَلَ بَعْضُهُمْ عَلَىٰ بَعْضٍۢ يَتَلَٰوَمُونَ","fa":"پس به یکدیگر رو کرده به سرزنش و ملامت هم پرداختند."},{"s":"سُورَةُ القَلَمِ","n":40,"ar":"سَلْهُمْ أَيُّهُم بِذَٰلِكَ زَعِيمٌ","fa":"از آنان بپرس کدامشان ضامن آن ادعاست [که مسلمان و مجرم یکسانند؟!!]"},{"s":"سُورَةُ القَلَمِ","n":50,"ar":"فَٱجْتَبَٰهُ رَبُّهُۥ فَجَعَلَهُۥ مِنَ ٱلصَّٰلِحِينَ","fa":"پس پروردگارش او را برگزید و از شایستگان قرار داد"},{"s":"سُورَةُ الحَاقَّةِ","n":8,"ar":"فَهَلْ تَرَىٰ لَهُم مِّنۢ بَاقِيَةٍۢ","fa":"آیا از آنان هیچ باقی مانده ای می بینی؟"},{"s":"سُورَةُ الحَاقَّةِ","n":18,"ar":"يَوْمَئِذٍۢ تُعْرَضُونَ لَا تَخْفَىٰ مِنكُمْ خَافِيَةٌۭ","fa":"آن روز [همه شما برای حسابرسی به پیشگاه خدا] عرضه می شوید در حالی که هیچ [عمل و نیّت] پوشیده ای از شما پنهان نمی ماند."},{"s":"سُورَةُ الحَاقَّةِ","n":28,"ar":"مَآ أَغْنَىٰ عَنِّى مَالِيَهْ ۜ","fa":"ثروتم عذاب را از من دفع نکرد،"},{"s":"سُورَةُ الحَاقَّةِ","n":38,"ar":"فَلَآ أُقْسِمُ بِمَا تُبْصِرُونَ","fa":"پس سوگند یاد می کنم به آنچه [از محسوسات] می بینید،"},{"s":"سُورَةُ الحَاقَّةِ","n":48,"ar":"وَإِنَّهُۥ لَتَذْكِرَةٌۭ لِّلْمُتَّقِينَ","fa":"بی تردید این قرآن، وسیله پند و تذکری برای پرهیزکاران است."},{"s":"سُورَةُ المَعَارِجِ","n":6,"ar":"إِنَّهُمْ يَرَوْنَهُۥ بَعِيدًۭا","fa":"دشمنان و مخالفان، آن [عذاب] را دور می بینند"},{"s":"سُورَةُ المَعَارِجِ","n":16,"ar":"نَزَّاعَةًۭ لِّلشَّوَىٰ","fa":"در حالی که دست و پا و پوست سر را بر می کند!!"},{"s":"سُورَةُ المَعَارِجِ","n":26,"ar":"وَٱلَّذِينَ يُصَدِّقُونَ بِيَوْمِ ٱلدِّينِ","fa":"و آنان که همواره روز پاداش را باور دارند،"},{"s":"سُورَةُ المَعَارِجِ","n":36,"ar":"فَمَالِ ٱلَّذِينَ كَفَرُوا۟ قِبَلَكَ مُهْطِعِينَ","fa":"کافران را چه شده که به تو چشم دوخته به سویت شتابانند؟"},{"s":"سُورَةُ نُوحٍ","n":2,"ar":"قَالَ يَٰقَوْمِ إِنِّى لَكُمْ نَذِيرٌۭ مُّبِينٌ","fa":"گفت: ای قوم من! همانا من شما را بیم دهنده ایآشکارم،"},{"s":"سُورَةُ نُوحٍ","n":12,"ar":"وَيُمْدِدْكُم بِأَمْوَٰلٍۢ وَبَنِينَ وَيَجْعَل لَّكُمْ جَنَّٰتٍۢ وَيَجْعَل لَّكُمْ أَنْهَٰرًۭا","fa":"و شما را با اموال و فرزندان یاری کند، و برایتان باغ ها و نهرها قرار دهد،"},{"s":"سُورَةُ نُوحٍ","n":22,"ar":"وَمَكَرُوا۟ مَكْرًۭا كُبَّارًۭا","fa":"و [این پیشوایان گمراهی، برای گمراه نگاه داشتن این مردم] نیرنگی بزرگ به کار گرفتند،"},{"s":"سُورَةُ الجِنِّ","n":4,"ar":"وَأَنَّهُۥ كَانَ يَقُولُ سَفِيهُنَا عَلَى ٱللَّهِ شَطَطًۭا","fa":"و اینکه سبک مغز و نادان ما همواره درباره خدا سخنی دور از حق می گفت [که او دارای همسر و فرزند است!]"},{"s":"سُورَةُ الجِنِّ","n":14,"ar":"وَأَنَّا مِنَّا ٱلْمُسْلِمُونَ وَمِنَّا ٱلْقَٰسِطُونَ ۖ فَمَنْ أَسْلَمَ فَأُو۟لَٰٓئِكَ تَحَرَّوْا۟ رَشَدًۭا","fa":"و اینکه گروهی از ما تسلیم [فرمان ها و احکام] خدایند، و برخی منحرف اند، پس کسانی که تسلیم شدند در صدد یافتن حقیقت و راه مستقیم اند،"},{"s":"سُورَةُ الجِنِّ","n":24,"ar":"حَتَّىٰٓ إِذَا رَأَوْا۟ مَا يُوعَدُونَ فَسَيَعْلَمُونَ مَنْ أَضْعَفُ نَاصِرًۭا وَأَقَلُّ عَدَدًۭا","fa":"[اینان همواره شما را ضعیف و ناتوان و بی یار می شمارند] تا زمانی که آنچه را [از عذاب] وعده داده می شوند ببینند، پس به زودی آگاه می شوند چه کسی یاورش ناتوان تر و نفراتش کمتر است؟"},{"s":"سُورَةُ المُزَّمِّلِ","n":6,"ar":"إِنَّ نَاشِئَةَ ٱلَّيْلِ هِىَ أَشَدُّ وَطْـًۭٔا وَأَقْوَمُ قِيلًا","fa":"بی تردید عبادت [ی که در دل] شب [انجام می گیرد] محکم تر و پایدارتر و گفتار در آن استوارتر و درست تر است."},{"s":"سُورَةُ المُزَّمِّلِ","n":16,"ar":"فَعَصَىٰ فِرْعَوْنُ ٱلرَّسُولَ فَأَخَذْنَٰهُ أَخْذًۭا وَبِيلًۭا","fa":"پس فرعون از آن رسول نافرمانی کرد، پس او را به عذابی سخت گرفتیم."},{"s":"سُورَةُ المُدَّثِّرِ","n":6,"ar":"وَلَا تَمْنُن تَسْتَكْثِرُ","fa":"و [احسانت را بر دیگران] در حالی که [آن را] بزرگ و فراوان بینی، منت مگذار،"},{"s":"سُورَةُ المُدَّثِّرِ","n":16,"ar":"كَلَّآ ۖ إِنَّهُۥ كَانَ لِءَايَٰتِنَا عَنِيدًۭا","fa":"این چنین نیست؛ زیرا او همواره به آیات ما دشمنی می ورزد،"},{"s":"سُورَةُ المُدَّثِّرِ","n":26,"ar":"سَأُصْلِيهِ سَقَرَ","fa":"به زودی او را در سقر درآورم"},{"s":"سُورَةُ المُدَّثِّرِ","n":36,"ar":"نَذِيرًۭا لِّلْبَشَرِ","fa":"هشدار دهنده به بشر است،"},{"s":"سُورَةُ المُدَّثِّرِ","n":46,"ar":"وَكُنَّا نُكَذِّبُ بِيَوْمِ ٱلدِّينِ","fa":"و همواره روز جزا را انکار می کردیم"},{"s":"سُورَةُ المُدَّثِّرِ","n":56,"ar":"وَمَا يَذْكُرُونَ إِلَّآ أَن يَشَآءَ ٱللَّهُ ۚ هُوَ أَهْلُ ٱلتَّقْوَىٰ وَأَهْلُ ٱلْمَغْفِرَةِ","fa":"و از آن پند نمی گیرند مگر آنکه خدا بخواهد، او سزاوار است که از وی پروا کنند، و سزاوار است که به آمرزشش امید بندند."},{"s":"سُورَةُ القِيَامَةِ","n":10,"ar":"يَقُولُ ٱلْإِنسَٰنُ يَوْمَئِذٍ أَيْنَ ٱلْمَفَرُّ","fa":"آن روز انسان گوید: گریزگاه کجاست؟"},{"s":"سُورَةُ القِيَامَةِ","n":20,"ar":"كَلَّا بَلْ تُحِبُّونَ ٱلْعَاجِلَةَ","fa":"[اینکه می پندارید قیامتی در کار نیست] این چنین نیست، بلکه شما عاشق ایندنیای زودگذر هستید،"},{"s":"سُورَةُ القِيَامَةِ","n":30,"ar":"إِلَىٰ رَبِّكَ يَوْمَئِذٍ ٱلْمَسَاقُ","fa":"آن روز، روز سوق و مسیر به سوی پروردگار توست."},{"s":"سُورَةُ القِيَامَةِ","n":40,"ar":"أَلَيْسَ ذَٰلِكَ بِقَٰدِرٍ عَلَىٰٓ أَن يُحْۦِىَ ٱلْمَوْتَىٰ","fa":"آیا چنین نیرومند آگاهی توانا نیست که مردگان را زنده کند؟"},{"s":"سُورَةُ الإِنسَانِ","n":10,"ar":"إِنَّا نَخَافُ مِن رَّبِّنَا يَوْمًا عَبُوسًۭا قَمْطَرِيرًۭا","fa":"ما از پروردگارمان در روزی که روز عبوس و بسیار هولناکی است می ترسیم."},{"s":"سُورَةُ الإِنسَانِ","n":20,"ar":"وَإِذَا رَأَيْتَ ثَمَّ رَأَيْتَ نَعِيمًۭا وَمُلْكًۭا كَبِيرًا","fa":"و چون آنجا را ببینی، نعمتی فراوان و کشوری بزرگ بینی،"},{"s":"سُورَةُ الإِنسَانِ","n":30,"ar":"وَمَا تَشَآءُونَ إِلَّآ أَن يَشَآءَ ٱللَّهُ ۚ إِنَّ ٱللَّهَ كَانَ عَلِيمًا حَكِيمًۭا","fa":"و تا خدا نخواهد، نخواهید خواست؛ یقیناً خدا همواره دانا و حکیم است."},{"s":"سُورَةُ المُرۡسَلَاتِ","n":9,"ar":"وَإِذَا ٱلسَّمَآءُ فُرِجَتْ","fa":"و آن زمانی که آسمان بشکافد."},{"s":"سُورَةُ المُرۡسَلَاتِ","n":19,"ar":"وَيْلٌۭ يَوْمَئِذٍۢ لِّلْمُكَذِّبِينَ","fa":"وای در آن روز بر تکذیب کنندگان!"},{"s":"سُورَةُ المُرۡسَلَاتِ","n":29,"ar":"ٱنطَلِقُوٓا۟ إِلَىٰ مَا كُنتُم بِهِۦ تُكَذِّبُونَ","fa":"[آن روز به آنان گویند:] به سوی آتشی که همواره آن را تکذیب می کردید، بروید؛"},{"s":"سُورَةُ المُرۡسَلَاتِ","n":39,"ar":"فَإِن كَانَ لَكُمْ كَيْدٌۭ فَكِيدُونِ","fa":"پس اگر [برای فرار از عذاب] چاره و تدبیری دارید، آن را به کار گیرید."},{"s":"سُورَةُ المُرۡسَلَاتِ","n":49,"ar":"وَيْلٌۭ يَوْمَئِذٍۢ لِّلْمُكَذِّبِينَ","fa":"وای در آن روز بر تکذیب کنندگان!"},{"s":"سُورَةُ النَّبَإِ","n":9,"ar":"وَجَعَلْنَا نَوْمَكُمْ سُبَاتًۭا","fa":"و خوابتان را مایه استراحت و آرامش [و تمدّد اعصاب] قرار دادیم،"},{"s":"سُورَةُ النَّبَإِ","n":19,"ar":"وَفُتِحَتِ ٱلسَّمَآءُ فَكَانَتْ أَبْوَٰبًۭا","fa":"و آسمان گشوده می شود، پس به صورت درهایی درمی آید."},{"s":"سُورَةُ النَّبَإِ","n":29,"ar":"وَكُلَّ شَىْءٍ أَحْصَيْنَٰهُ كِتَٰبًۭا","fa":"و [ما] همه چیز را [از خوبی و بدی آنان] برشمرده و در نامه اعمالشان ثبت کرده ایم."},{"s":"سُورَةُ النَّبَإِ","n":39,"ar":"ذَٰلِكَ ٱلْيَوْمُ ٱلْحَقُّ ۖ فَمَن شَآءَ ٱتَّخَذَ إِلَىٰ رَبِّهِۦ مَـَٔابًا","fa":"آن [روز] روز حق است، پس هرکه بخواهد راه بازگشتی به سوی پروردگارش برگزیند؛"},{"s":"سُورَةُ النَّازِعَاتِ","n":9,"ar":"أَبْصَٰرُهَا خَٰشِعَةٌۭ","fa":"دیدگانشان [از ترس و هول قیامت] فرو افتاده است."},{"s":"سُورَةُ النَّازِعَاتِ","n":19,"ar":"وَأَهْدِيَكَ إِلَىٰ رَبِّكَ فَتَخْشَىٰ","fa":"من تو را به سوی پروردگارت راهنمایی می کنم تا از او بترسی [و از طغیان دست برداری.]"},{"s":"سُورَةُ النَّازِعَاتِ","n":29,"ar":"وَأَغْطَشَ لَيْلَهَا وَأَخْرَجَ ضُحَىٰهَا","fa":"و شبش را تاریکو روزش را روشن ساخت،"},{"s":"سُورَةُ النَّازِعَاتِ","n":39,"ar":"فَإِنَّ ٱلْجَحِيمَ هِىَ ٱلْمَأْوَىٰ","fa":"پس بی تردید جایگاهش دوزخ است؛"},{"s":"سُورَةُ عَبَسَ","n":3,"ar":"وَمَا يُدْرِيكَ لَعَلَّهُۥ يَزَّكَّىٰٓ","fa":"تو چه می دانی شاید او [در پرتو تعالیم اسلام از آلودگی] پاک و پاکیزه شود"},{"s":"سُورَةُ عَبَسَ","n":13,"ar":"فِى صُحُفٍۢ مُّكَرَّمَةٍۢ","fa":"در صحیفه هایی است ارزشمند"},{"s":"سُورَةُ عَبَسَ","n":23,"ar":"كَلَّا لَمَّا يَقْضِ مَآ أَمَرَهُۥ","fa":"این چنین نیست [که وظیفه اش را انجام داده باشد] هنوز آنچه را به او دستور داده به جا نیاورده است."},{"s":"سُورَةُ عَبَسَ","n":33,"ar":"فَإِذَا جَآءَتِ ٱلصَّآخَّةُ","fa":"پس زمانی که آن بانگ هولناک و مهیب در رسد،"},{"s":"سُورَةُ التَّكۡوِيرِ","n":1,"ar":"بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ إِذَا ٱلشَّمْسُ كُوِّرَتْ","fa":"هنگامی که خورشید را به هم درپیچند"},{"s":"سُورَةُ التَّكۡوِيرِ","n":11,"ar":"وَإِذَا ٱلسَّمَآءُ كُشِطَتْ","fa":"و هنگامی که آسمان را به شدت برکنند و برچینند"},{"s":"سُورَةُ التَّكۡوِيرِ","n":21,"ar":"مُّطَاعٍۢ ثَمَّ أَمِينٍۢ","fa":"آنجا مورد اطاعت [فرشتگان] و امین است…."},{"s":"سُورَةُ الانفِطَارِ","n":2,"ar":"وَإِذَا ٱلْكَوَاكِبُ ٱنتَثَرَتْ","fa":"و هنگامی که ستارگان پراکنده شوند"},{"s":"سُورَةُ الانفِطَارِ","n":12,"ar":"يَعْلَمُونَ مَا تَفْعَلُونَ","fa":"که آنچه را [از خیر و شر] انجام می دهید، می دانند [و ضبط می کنند.]"},{"s":"سُورَةُ المُطَفِّفِينَ","n":3,"ar":"وَإِذَا كَالُوهُمْ أَو وَّزَنُوهُمْ يُخْسِرُونَ","fa":"و چون برای آنان پیمانه و وزن کنند، کم می دهند."},{"s":"سُورَةُ المُطَفِّفِينَ","n":13,"ar":"إِذَا تُتْلَىٰ عَلَيْهِ ءَايَٰتُنَا قَالَ أَسَٰطِيرُ ٱلْأَوَّلِينَ","fa":"[که] هرگاه آیات ما را بر او خوانند می گوید: افسانه های پیشینیان است."},{"s":"سُورَةُ المُطَفِّفِينَ","n":23,"ar":"عَلَى ٱلْأَرَآئِكِ يَنظُرُونَ","fa":"بر تخت ها [ی آراسته و پرارزش تکیه زده و مناظر زیبای بهشت را با چشم سر و جمال محبوب را با چشم دل] می نگرند."},{"s":"سُورَةُ المُطَفِّفِينَ","n":33,"ar":"وَمَآ أُرْسِلُوا۟ عَلَيْهِمْ حَٰفِظِينَ","fa":"و حال آنکه کافران را بر مؤمنان نگهبان و مراقب نفرستاده بودند [که مراقب هدایت و گمراهی آنان باشند.]"},{"s":"سُورَةُ الانشِقَاقِ","n":7,"ar":"فَأَمَّا مَنْ أُوتِىَ كِتَٰبَهُۥ بِيَمِينِهِۦ","fa":"اما کسی که نامه اعمالش را به دست راستش دهند،"},{"s":"سُورَةُ الانشِقَاقِ","n":17,"ar":"وَٱلَّيْلِ وَمَا وَسَقَ","fa":"و سوگند به شب و آنچه را [از موجودات پراکنده شده در روز، در خانه ها و لانه ها] جمع می کند"},{"s":"سُورَةُ البُرُوجِ","n":2,"ar":"وَٱلْيَوْمِ ٱلْمَوْعُودِ","fa":"و سوگند به روزی که [برپا شدنش را برای داوری میان مردم] وعده داده اند"},{"s":"سُورَةُ البُرُوجِ","n":12,"ar":"إِنَّ بَطْشَ رَبِّكَ لَشَدِيدٌ","fa":"بی تردید به قهر گرفتن و مجازات پروردگارت بسیار سخت است. …."},{"s":"سُورَةُ البُرُوجِ","n":22,"ar":"فِى لَوْحٍۢ مَّحْفُوظٍۭ","fa":"که در لوح محفوظ است [به همین خاطر از دستبرد هر تحریف گری مصون است.]"},{"s":"سُورَةُ الطَّارِقِ","n":10,"ar":"فَمَا لَهُۥ مِن قُوَّةٍۢ وَلَا نَاصِرٍۢ","fa":"پس انسان را [در آن روز در برابر عذاب] نه نیرویی است و نه یاوری."},{"s":"سُورَةُ الأَعۡلَىٰ","n":3,"ar":"وَٱلَّذِى قَدَّرَ فَهَدَىٰ","fa":"و آنکه اندازه قرار داد و هدایت کرد،"},{"s":"سُورَةُ الأَعۡلَىٰ","n":13,"ar":"ثُمَّ لَا يَمُوتُ فِيهَا وَلَا يَحْيَىٰ","fa":"آن گاه در آنجا نه می میرد و نه به خوشی زندگی می کند."},{"s":"سُورَةُ الغَاشِيَةِ","n":4,"ar":"تَصْلَىٰ نَارًا حَامِيَةًۭ","fa":"در آتشی سوزان درآیند."},{"s":"سُورَةُ الغَاشِيَةِ","n":14,"ar":"وَأَكْوَابٌۭ مَّوْضُوعَةٌۭ","fa":"و [در کنار چشمه هایش] قدح ها نهاده شده است"},{"s":"سُورَةُ الغَاشِيَةِ","n":24,"ar":"فَيُعَذِّبُهُ ٱللَّهُ ٱلْعَذَابَ ٱلْأَكْبَرَ","fa":"پس خدا او را به عذاب بزرگ تر عذاب خواهد کرد."}];
